(window.LUMINA_T = window.LUMINA_T || {})["oncologie-support"] = [{"pmid":"42928805","title":"Clinical Effects of Photobiomodulation, Corticosteroids, and Nonsteroidal Anti-Inflammatory Drugs Following Third Molar Surgery: A Systematic Review of Randomized Clinical Trials.","journal_abbr":"Int J Dent","authors":["Alpaca Zevallos ÉA","Nogueira LLT","Ferreira AJ","et al."],"date":"2026-10-25","year":2026,"doi":"10.1155/ijod/5965550","pmcid":"PMC13695851","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus"],"l1":"The three approaches may improve different postoperative outcomes, but the available evidence does not support a definitive hierarchy among them. Direct head-to-head trials with standardized outcomes, treatment protocols, and follow-up…","kw":"corticosteroids facial edema nonsteroidal anti-inflammatory drugs photobiomodulation postoperative pain third molar"},{"pmid":"42782358","title_fr":"Nouveau protocole de laser basse énergie dans le lymphœdème lié au cancer du sein","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[650,904],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Dans le lymphœdème lié au cancer du sein, différentes longueurs d'onde modifient les propriétés mécaniques des tissus, avec des résultats exploratoires.","l2":"Essai randomisé.","l3":{"points":["Comparaison de longueurs d'onde."],"limites":["Exploratoire ; critère principal non prédéfini."],"pratique":"À confirmer."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Effectiveness of a novel low-level laser therapy protocol in managing breast cancer-related lymphedema.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Yoon JA","Bae H","Choi SH","et al."],"date":"2026-09-24","year":2026,"week":"2026-S39","doi":"10.1007/s10103-026-05045-6","pmcid":"PMC13612665","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/42782358.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"In this study, we investigate the effects of low-level laser therapy (LLLT) at different wavelengths on lymphedema to further determine the appropriate protocol and effectiveness of LLLT in patients with breast cancer-related lymphedema (BCRL). A randomized controlled trial was conducted involving 46 patients with BCRL. Participants were assigned to receive 904 nm LLLT, 650 nm LLLT, or sham treatment. ICG lymphography was used to assess dermal backflow as a marker of lymphatic dysfunction. Ultrasonography was used to assess subcutaneous thickness and tissue mechanical properties; shear wave velocity (SWV), with higher values indicating greater tissue stiffness, was measured using shear wave elastography. Extracellular fluid volume and local tissue water content were evaluated using multifrequency bioelectrical impedance analysis (MFBIA) and tissue dielectric constant (TDC), respectively. No significant between-group differences were observed in ICG lymphography, MFBIA, or TDC outcomes. For ultrasonographic outcomes, the overall between-group difference in the change in upper-lateral SWV ratio was significant (p = 0.029), and Bonferroni-adjusted post-hoc analysis showed a greater reduction in Group A (904 nm) than in Group B (650 nm) (adjusted p = 0.026). Within Group A, SWV ratios decreased significantly at the lower-lateral site and at the LLLT treatment site. These site-specific findings were not accompanied by measurable changes in lymphatic transport or fluid-related outcomes. Adding 904 nm-650 nm LLLT to conventional decongestive therapy did not produce significant additional effects on extracellular fluid-related or lymphatic functional outcomes. Site-specific reductions in SWV observed with 904 nm LLLT suggest a potential wavelength-dependent effect on local tissue mechanical properties; however, these findings are limited and should be considered exploratory. Larger adequately powered studies with prespecified primary outcomes and longer follow-up are required."}],"keywords":["Breast cancer","Fibrosis","Low-level laser therapy","Lymphedema","Photobiomodulation","Randomized controlled trial"]},{"pmid":"42753963","title":"Toward precision photobiomodulation for radiation-induced xerostomia: Clinical evidence, salivary biomarkers, and artificial intelligence.","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Eftekharian S","Rastkar S"],"date":"2026-09-17","year":2026,"doi":"10.1016/j.pdpdt.2026.105656","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"PBMT is a plausible supportive intervention, but biomarker-guided or AI-guided precision PBMT remains unvalidated. Future studies should standardize dosimetry, separate subjective and objective endpoints, account for gland-specific…","kw":"Head and neck cancer Hyposalivation Machine learning Photobiomodulation therapy Precision medicine Radiomics Humans Xerostomia Biomarkers Head and Neck Neoplasm"},{"pmid":"42719955","title":"Current approaches to comprehensive oral care after cancer therapy.","journal_abbr":"Dent Med Probl","authors":["Jawor N","Pogoda K","Ziętek M","et al."],"date":"2026-09-10","year":2026,"doi":"10.17219/dmp/216725","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"The emerging therapeutic modalities, such as low-level laser therapy (LLLT) and novel pharmacological agents, were critically assessed with regard to their clinical effectiveness.Overall, the evidence emphasizes the need for an…","kw":"interdisciplinary oncology oral mucositis osteoradionecrosis post-cancer dental care xerostomia Humans Mouth Diseases Oral Hygiene Neoplasms Xerostomia Osteorad"},{"pmid":"42714658","title":"Fractional CO₂ vaginal laser therapy for genitourinary syndrome of menopause in breast cancer survivors: a scoping review.","journal_abbr":"Lasers Med Sci","authors":["Jacobsen S","Eliasen EK","Stokvad JK","et al."],"date":"2026-09-09","year":2026,"doi":"10.1007/s10103-026-05029-6","pmcid":"PMC13558295","license":"cc by-nc-nd","oa":true,"pub_types":["Scoping Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Vaginal CO₂ laser therapy appears well tolerated in the short term, but current evidence remains limited. Further adequately powered sham-controlled trials with standardized outcomes and long-term follow-up are needed to establish…","kw":"Breast cancer survivors Energy-based devices Genitourinary syndrome of menopause Non-hormonal treatment Scoping review Vaginal CO₂ laser therapy Female Humans B"},{"pmid":"42782929","title":"Effectiveness of Photobiomodulation as a Treatment for Xerostomia in Patients with Head and Neck Cancer Undergoing Radiotherapy: A Systematic Review and Meta-Analysis.","journal_abbr":"Dent J (Basel)","authors":["De La Hoz TQ","Peña YS","Ramírez FQ","et al."],"date":"2026-08-31","year":2026,"doi":"10.3390/dj14090542","pmcid":"PMC13605498","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Conclusions: Photobiomodulation provides a clinically meaningful reduction in radiotherapy-related oral pain and may confer symptomatic benefit in xerostomia; however, its effect on salivary flow restoration remains uncertain.…","kw":"head and neck cancer low-level laser therapy meta-analysis oral pain photobiomodulation radiotherapy"},{"pmid":"42659420","title":"Photobiomodulation in the management of oral lesions: a targeted, evidence-based approach.","journal_abbr":"Braz Oral Res","authors":["Koth VS","Gabriel AF","Deckmann I","et al."],"date":"2026-08-24","year":2026,"doi":"10.1590/1807-3107bor-2026.vol40suppl1059","pmcid":"PMC13508680","license":"cc by","oa":true,"pdf":"pdfs/42659420.pdf","cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Clinical effectiveness of PBM depends on appropriate dosimetry and irradiation parameters according to the biological characteristics of each condition and therapeutic target. Therefore further well-designed randomized clinical trials and…","kw":"Humans Low-Level Light Therapy Mouth Diseases Treatment Outcome Evidence-Based Dentistry Stomatitis"},{"pmid":"42629521","title":"Photobiomodulation to minimize talquetamab-associated dysgeusia and xerostomia in multiple myeloma: a brief report of four cases.","journal_abbr":"Support Care Cancer","authors":["Ferreira MH","de Paula Eduardo F","Menti LD","et al."],"date":"2026-08-21","year":2026,"doi":"10.1007/s00520-026-11133-8","pmcid":"PMC13498624","license":"cc by","oa":true,"pdf":"pdfs/42629521.pdf","pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"nm":[660,808],"l1":"This series demonstrates the feasibility and tolerability of PBM delivered alongside talquetamab in four patients. Given the small, uncontrolled sample and concurrent supportive interventions, no conclusion can be drawn regarding the…","kw":"Dysgeusia Multiple myeloma Photobiomodulation Supportive care Talquetamab Xerostomia Aged Female Humans Middle Aged Antineoplastic Agents Dysgeusia"},{"pmid":"42616170","title":"Photobiomodulation for salivary gland dysfunction: aligning clinical expectations with etiology-dependent treatment responsiveness.","journal_abbr":"Lasers Med Sci","authors":["Calarga CC","de Brito CBT","Cotomácio CC","et al."],"date":"2026-08-19","year":2026,"doi":"10.1007/s10103-026-04991-5","pmcid":"PMC13490257","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Instead, therapeutic outcomes likely depend on several factors. Biologically informed and individualized approaches may contribute to more realistic therapeutic expectations and more personalized management strategies.","kw":"Chemotherapy Hyposalivation Photobiomodulation Radiotherapy Sjögren Xerostomia Humans Low-Level Light Therapy Xerostomia Salivary Glands Sjogren's Syndrome Sali"},{"pmid":"42703852","title":"Comparing the Values of Tissue Fluid Accumulation Using Tissue Dielectric Constant and Bioimpedance Analysis in Healthy Volunteers.","journal_abbr":"Ann Rehabil Med","authors":["Park MK","Lee CH","Choi SH","et al."],"date":"2026-08-12","year":2026,"doi":"10.5535/arm.250143","pmcid":"PMC13554919","license":"cc by-nc","oa":true,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Although TDC and BIA both detected small intervention-associated changes in healthy volunteers, the limited correlations between the two modalities suggest that they are not interchangeable. TDC reflects localized superficial tissue…","kw":"Electric impedance Extracellular fluid Lymphedema Skin Upper extremity"},{"pmid":"42560105","title":"Case series on photobiomodulation in wound care: hard-to-heal leg ulcers and radiation-induced fibrosis.","journal_abbr":"Br J Nurs","authors":["Wild J","Townsend J","Crozier D","et al."],"date":"2026-08-06","year":2026,"doi":"10.12968/bjon.2026.0266","pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"PBM was well tolerated with no adverse effects and integrated readily into existing care pathways. These cases support PBM as a practical adjunct across complex wound presentations.","kw":"photobiomodulation radiation-induced fibrosis venous leg ulcer wound healing Humans Low-Level Light Therapy Wound Healing Leg Ulcer Fibrosis Radiation Injuries"},{"pmid":"42560106","title":"Biological mechanisms and applications of photobiomodulation in wound care.","journal_abbr":"Br J Nurs","authors":["Hallam E"],"date":"2026-08-06","year":2026,"doi":"10.12968/bjon.2026.0265","curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"Further studies are needed to establish a therapeutic window and standardise treatment guidelines for patient safety. Such studies will also provide data regarding large-scale cost-effectiveness and longevity of antifibrotic effects.","kw":"chronic wounds diabetic foot ulcer photobiomodulation pressure injury radiation-induced fibrosis Humans Chronic Disease Diabetic Foot Fibrosis Low-Level Light T"},{"pmid":"42474921","title":"Effectiveness of photobiomodulation in the treatment of xerostomia in type II diabetic patients.","journal_abbr":"Odontology","authors":["Ali HA","Attia NS","Zaki AM","et al."],"date":"2026-07-20","year":2026,"doi":"10.1007/s10266-026-01493-2","curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[980],"l1":"Subjective xerostomia scores also improved in the test group, decreasing from 12.19 ± 2.02 to 8.48 ± 1.83 (p < 0.001), while no significant change was noted in the control group. Photobiomodulation with a 980 nm diode laser might be an…","kw":"Diabetes Photobiomodulation Salivary flow Xerostomia"},{"pmid":"42351382","title":"Non-Invasive Approaches to Internal Lymphedema in Head and Neck Cancer Survivors: A Scoping Review.","journal_abbr":"Head Neck","authors":["Liu V","Martinez J","Yip HT","et al."],"date":"2026-06-25","year":2026,"doi":"10.1002/hed.70374","curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Current evidence on non-invasive therapies for internal HNL is heterogeneous and sparse. Despite suggestions of benefit in small-scale studies, further research is necessary to guide clinical integration.","kw":"dysphagia head and neck cancer lymphedema rehabilitation survivorship care"},{"pmid":"42228167","title":"Photobiomodulation for hormone therapy-induced sexual dysfunction in women with breast cancer: a prospective quasi-experimental clinical study with a parallel observational group.","journal_abbr":"Support Care Cancer","authors":["Vieira LR","Rezende LF"],"date":"2026-06-02","year":2026,"doi":"10.1007/s00520-026-10846-0","pub_types":["Clinical Study","Observational Study"],"curated":false,"type":"cohort","level":4,"ctx":[],"nm":[440,660],"l1":"PBM proved to be safe, well tolerated, and clinically effective in reducing vaginal pain and improving sexual function in women with breast cancer undergoing hormone therapy, representing a promising therapeutic alternative.","kw":"Breast cancer Female sexual dysfunction Genitopelvic pain Hormone therapy Non-hormonal therapies Photobiomodulation Adult Aged Female Humans Middle Aged Antineo"},{"pmid":"42662303","title":"Evaluation of post-operative pain, edema, trismus following third molar surgery using low level laser therapy: A randomised clinical trial.","journal_abbr":"Bioinformation","authors":["Sharma K","Uikey G","Gottipati A","et al."],"date":"2026-05-31","year":2026,"doi":"10.6026/973206300223010","pmcid":"PMC13519442","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"The LLLT group demonstrated significantly lower pain scores; reduced facial edema and improved mouth opening compared to the control side at all evaluated time points. Thus, we show that LLLT is an effective noninvasive adjunctive…","kw":"Low-level laser therapy (LLLT) edema post-operative pain third molar surgery trismus"},{"pmid":"42071320","title_fr":"PBM dans le lymphœdème chronique des cancers ORL : essai pilote randomisé","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Dans le lymphœdème chronique cervico-facial après cancer ORL, la PBM améliore le lymphœdème externe, les symptômes et la mobilité du cou.","l2":"Essai pilote randomisé avec liste d'attente.","l3":{"points":["Lymphœdème de la tête et du cou."],"limites":["Pilote."],"pratique":"Prometteur."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation in Treatment of Head and Neck Cancer-Related Chronic Lymphedema: A Pilot Randomized Controlled Trial.","journal":"Integrative cancer therapies","journal_abbr":"Integr Cancer Ther","authors":["Deng J","Lukens JN","Murphy BA","et al."],"date":"2026-05-03","year":2026,"week":"2026-S18","doi":"10.1177/15347354261439138","pmcid":"PMC13153496","license":"cc by-nc","oa":true,"pdf":"pdfs/42071320.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Chronic lymphedema is a common late effect after completion of head and neck cancer (HNC) treatment, contributing to substantial symptom burden and negatively impacting quality of life. No effective approaches are available to treat this progressive condition. This study aimed to evaluate the preliminary efficacy of photobiomodulation (PBM) therapy for chronic lymphedema in HNC survivors."},{"label":"METHODS","text":"This was a pilot, randomized, wait-list controlled trial. Eligible HNC survivors included those with chronic lymphedema after completion of complete decongestive therapy. Participants were randomized (1:1) to 1 of 2 arms: intervention group (active) or wait-list control group (control). The active group received 12 PBM therapy sessions (twice a week for 6 weeks). The control group completed the study assessments and was then offered the same dose of PBM therapy as the active group. Lymphedema and fibrosis (LEF), symptom burden, jaw range of motion, and neck range of motion were measured at baseline, end-of-intervention, 4-week, and 8-week post-intervention."},{"label":"RESULTS","text":"Twenty five HNC survivors were randomized to the active group (n = 12) and the control group (n = 13). About 91.7% planned PBM treatment sessions were completed. No adverse events were reported. Compared to the control group, the active group demonstrated improvements at 8-week post-intervention in the severity of external LEF (P < .001), symptom burden (eg, Soft Tissue and Neurologic Toxicity subscale, Cohen's d = - 0.47), and neck range of motion (eg, extension, Cohen's d = 0.65)."},{"label":"CONCLUSION","text":"PBM therapy may improve chronic lymphedema-associated outcomes. Future large randomized controlled trials are warranted to examine the efficacy of PBM therapy for HNC-related chronic lymphedema."}],"keywords":["chronic lymphedema","head and neck cancer","photobiomodulation (PBM)","survivorship"]},{"pmid":"42082093","title_fr":"Complications bucco-dentaires des cancers ORL : revue parapluie","type":"umbrella","level":5,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Autres","l1":"Dans les cancers ORL, la PBM est associée à moins de mucite, et la radiothérapie conformationnelle à moins de xérostomie et d'ostéoradionécrose ; les preuves sont de faible confiance.","l2":"Revue parapluie de revues systématiques (J Dent, 2026).","l3":{"points":["Vue d'ensemble."],"limites":["Preuves fragmentées."],"pratique":"La PBM est surtout étayée contre la mucite."},"em":[],"pre":"","topic":"oncologie-support","title":"Oral and dental complications and management in head and neck cancer patients: An umbrella review.","journal":"Journal of dentistry","journal_abbr":"J Dent","authors":["Craig R","O'Kane R","Rodriguez J","et al."],"date":"2026-05-03","year":2026,"week":"2026-S18","doi":"10.1016/j.jdent.2026.106731","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"To synthesise evidence on oral and dental side-effects experienced by head and neck cancer (HNC) patients, assess the strength and quality of existing systematic reviews, evaluate the evidence for prevention and management interventions and identify key gaps to inform future research."},{"label":"DATA","text":"Systematic reviews (with/without meta-analysis) published from 2015 onwards involving adults with HNC reporting oral/dental complications and/or interventions were included."},{"label":"SOURCES","text":"MEDLINE (OVID), Embase, Cochrane Database of Systematic Reviews and Scopus were searched (19 June 2025). Two reviewers screened and extracted data independently."},{"label":"STUDY SELECTION","text":"An umbrella review (PROSPERO CRD420251063188) was conducted following JBI/Cochrane guidance and reported in line with PRISMA 2020. Methodological quality was assessed using AMSTAR-2 and primary-study overlap quantified using corrected-covered-area (CCA). Owing to heterogeneity, findings were synthesised narratively by domain."},{"label":"CONCLUSIONS","text":"A total of 131 systematic reviews were included, with most rated as low or critically low confidence. Oral mucositis was the most frequently reported complication, followed by xerostomia, dysphagia, trismus, dental caries, and dysgeusia; osteoradionecrosis was less common. Preventive and therapeutic interventions are widely studied but largely supported by low-quality evidence. Photobiomodulation was associated with reduced oral mucositis, while intensity-modulated radiotherapy was associated with reduced xerostomia and mandibular osteoradionecrosis. Overall, the evidence base is fragmented and of low confidence. Standardised outcome measures and high-quality prospective studies are needed to strengthen the evidence base and improve survivorship care."},{"label":"CLINICAL SIGNIFICANCE","text":"Head and neck cancer patients experience a high burden of oral complications, yet dental management strategies are supported by limited high-quality evidence. This review highlights key areas of uncertainty and reinforces the need for multidisciplinary, evidence-based care, while identifying priorities for research to improve long-term oral health and quality of life."}],"keywords":["Cancer survivorship","Chemoradiotherapy","Dental care","Dental complications","Dysgeusia","Dysphagia","Head and neck cancer/neoplasms","Oral complications","Oral health-related quality of life","Oral mucositis"]},{"pmid":"42010907","title_fr":"Laser-acupuncture contre la xérostomie de la maladie de Sjögren : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser-acupuncture"],"nm":[],"n":50,"effect":"mitigé","theme":"Xérostomie","l1":"Dans la maladie de Sjögren, la PBM sur points d'acupuncture apporte un léger bénéfice sur la sécheresse et le débit salivaire à 8 semaines, qui disparaît à 12 semaines.","l2":"Essai randomisé en double aveugle contre sham, 50 patients.","l3":{"points":["Effet transitoire."],"limites":["Effet modeste."],"pratique":"Bénéfice limité."},"em":[],"pre":"","topic":"oncologie-support","title":"Laser Acupuncture on the Management of Xerostomia in Sjögren's Disease: A Randomized Clinical Trial.","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Linares MF","Dos Santos França TD","Ferreira MCBM","et al."],"date":"2026-04-20","year":2026,"week":"2026-S17","doi":"10.1111/odi.70241","pmcid":"PMC13590897","license":"cc by","oa":true,"pdf":"pdfs/42010907.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"This study evaluated the efficacy of photobiomodulation (PBM) at acupuncture points for managing xerostomia in patients with Sjögren's Disease."},{"label":"MATERIAL AND METHODS","text":"In this randomized, double-blind clinical trial, 50 patients were assigned to PBM group (n = 22) or sham-PBM group (n = 28). The primary outcome was xerostomia symptoms assessed using a visual analogue scale (VAS). Secondary outcomes included Xerostomia Inventory, resting salivary flow rate (RSFR), and EULAR Sjögren's Syndrome Patient Reported Index score. Participants received weekly PBM sessions for four consecutive weeks, and evaluations were conducted at baseline, week 8 and 12."},{"label":"RESULTS","text":"PBM showed a marginal tendency toward improvement on VAS (p = 0.0974) (OR = 1.929 95% CI 0.8939-4.525) and in the RSFR (p = 0.09996) (OR = +infinity 95% CI 0.9363-infinity) at week 8 compared with sham-PBM. However, no statistically significant differences were observed between groups at week 12 for any of the assessed outcomes."},{"label":"CONCLUSION","text":"PBM at acupuncture points demonstrated a slight short-term benefit at week 8 in improving xerostomia symptoms and RSFR, although these effects did not persist at 12 weeks. These preliminary results suggest a potential role for PBM at acupuncture points as a safe, noninvasive adjunctive therapy for xerostomia in patients with SjD, warranting further validation in larger, long-term trials."},{"label":"TRIAL REGISTRATION","text":"This study was registered in The Brazilian Registry of Clinical Trials (U1111-1298-9891)."}],"keywords":["Sjögren's syndrome","acupuncture","phtotobiomodulation","xerostomia"]},{"pmid":"42041684","title":"Clinical Efficacy and Safety of Photobiomodulation Therapy for Orofacial Conditions in Older Adults: A Systematic Review of Randomized Controlled Trials.","journal_abbr":"Dent J (Basel)","authors":["Tanya S","Srisilapanan P"],"date":"2026-04-13","year":2026,"doi":"10.3390/dj14040231","pmcid":"PMC13114592","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"These findings support its integration into geriatric oral care. Standardized protocols and well-designed RCTs are needed to determine optimal treatment parameters and long-term effectiveness.","kw":"geriatric dentistry older adults oral conditions photobiomodulation therapy"},{"pmid":"41880047","title_fr":"PBM, mucite, douleur, xérostomie et qualité de vie dans les cancers ORL : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"Dans les cancers ORL, la PBM réduit la mucite sévère et la douleur buccale et pourrait améliorer le débit salivaire, avec une certitude faible à très faible.","l2":"Méta-analyse d'essais randomisés (six bases, jusqu'en avril 2025) des effets de la PBM chez les patients traités pour un cancer ORL.\n\nMucite sévère réduite (RR 0,46 ; IC 0,29–0,71) et douleur buccale sévère réduite (RR 0,35 ; IC 0,23–0,53). Débit salivaire amélioré (DMS 0,75 ; IC 0,03–1,46). Pas d'effet significatif sur la xérostomie ressentie (DMS −0,07) ni sur la qualité de vie (DMS 1,06 ; p = 0,06). Résultats cohérents quel que soit le protocole.","l3":{"points":["Confirme l'effet sur la mucite sévère avec un RR proche des méta-analyses précédentes.","Évalue aussi la salive et la qualité de vie."],"limites":["Certitude faible à très faible ; risque de biais élevé dans la plupart des essais."],"pratique":"Le bénéfice sur la mucite et la douleur justifie la PBM ; ne pas en attendre un effet net sur la sécheresse buccale."},"em":[],"pre":"","topic":"oncologie-support","title":"Effects of photobiomodulation on oral mucositis, oral pain, xerostomia, salivary flow rate, and quality of life in patients with head and neck cancer: a systematic review and meta-analysis.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Pedroso MNM","Rech A","Casagrande N","et al."],"date":"2026-03-25","year":2026,"week":"2026-S13","doi":"10.1007/s00520-026-10575-4","pmcid":"PMC13018037","license":"cc by","oa":true,"pdf":"pdfs/41880047.pdf","cited_by":2,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":2,"abstract":[{"label":"PURPOSE","text":"To systematically review and analyze the effects of photobiomodulation on oral mucositis, xerostomia, salivary flow rates, oral pain, and quality of life in patients with head and neck cancer."},{"label":"METHODS","text":"A systematic search of six databases was conducted up to April 2025. Eligible randomized controlled trials (RCTs) examined the effects of photobiomodulation on the specified outcomes in patients with head and neck cancer. Pooled estimates (risk ratio [RR] and standardized mean difference [SMD]) were calculated using a three-level mixed-effects meta-analysis."},{"label":"RESULTS","text":"Thirty-three articles describing 30 RCTs (n = 1748) were included. Photobiomodulation significantly reduced the risk of severe oral mucositis (RR 0.46, 95% CI: 0.29-0.71, P < 0.001) and severe oral pain (RR 0.35, 95% CI: 0.23-0.53, P < 0.001) compared with controls. Significant improvements were also observed for salivary flow rate (SMD 0.75, 95% CI: 0.03-1.46, P = 0.044). No significant effects were observed on xerostomia (SMD -0.07, 95% CI: -0.47-0.33, P = 0.646) and quality of life (SMD 1.06, 95% CI: -0.03-2.14, P = 0.060). The benefits were consistent across different photobiomodulation protocols for oral mucositis and quality of life."},{"label":"CONCLUSIONS","text":"Photobiomodulation appears to be a promising supportive care intervention, reducing the risk of severe mucositis and oral pain, while potentially improving salivary flow rates and preserving quality of life in patients with head and neck cancer. However, the certainty of the evidence ranged from very low to low and most included studies presented a high risk of bias; therefore, these findings should be interpreted with caution."}],"keywords":["Head and neck neoplasms","Low-level light therapy","Mouth dryness","Quality of life"]},{"pmid":"41881503","title":"Oral wound healing in the elderly: Mechanisms, challenges, and innovations.","journal_abbr":"Periodontol 2000","authors":["Decker AM","Stuhr SH","Avila-Ortiz G","et al."],"date":"2026-03-25","year":2026,"doi":"10.1111/prd.70027","cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Effective oral wound healing in older adults demands a multidisciplinary, personalized approach that integrates meticulous perioperative care with novel regenerative modalities. Standardization and clinical validation of emerging…","kw":"aging elderly frailty inflammaging inflammation local and systemic factors"},{"pmid":"41948502","title":"Effects of photobiomodulation therapy on upper limb lymphedema secondary to breast cancer: a systematic review and meta-analysis.","journal_abbr":"Front Oncol","authors":["Qian C","He Z","Liu C","et al."],"date":"2026-03-23","year":2026,"doi":"10.3389/fonc.2026.1802643","pmcid":"PMC13050686","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"PBM therapy is associated with significant improvements in limb volume, circumference, grip strength, and pain in patients with BCRL. Despite these favorable findings, the overall certainty of evidence is moderate, and safety conclusions…","kw":"breast cancer function lymphoedema pain photobiomodulation"},{"pmid":"41866508","title":"Diode-laser-assisted biopsy and photobiomodulation therapy in the management of Sjögren's disease: a case report.","journal_abbr":"J Med Case Rep","authors":["Sanchez-Ramirez C","Bernotti AL","De Jesús E","et al."],"date":"2026-03-22","year":2026,"doi":"10.1186/s13256-026-05931-1","pmcid":"PMC13130530","license":"cc by-nc-nd","oa":true,"cited_by":1,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"l1":"This case highlights the use of laser for safe biopsy of minor salivary glands in Sjögren's disease and the potential of intraoral and extraoral photobiomodulation therapy, including lymphatic node stimulation, combined with active…","kw":"Active oxygen Diode laser Lactoferrin Photobiomodulation Sjögren’s disease Sjögren’s syndrome Humans Female Sjogren's Syndrome Middle Aged Low-Level Light Thera"},{"pmid":"41826477","title_fr":"PBM pour prévenir le trismus pendant la radiothérapie ORL : essai en triple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["trismus"],"aim":"prévention","mode":["laser","LED"],"nm":[808],"n":null,"effect":"favorable","theme":"Trismus & fibrose radio-induite","l1":"Pendant la radiothérapie ORL (IMRT ou VMAT), la PBM prévient le trismus et la douleur des muscles masticateurs.","l2":"Essai randomisé en triple aveugle contre placebo.","l3":{"points":["Effet préventif."],"limites":["Pas de différence d'ouverture à 6 mois."],"pratique":"Prévention possible."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Effects of photobiomodulation on trismus in head and neck cancer patients after radiotherapy: a prospective, randomized, triple-blind, placebo-controlled clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Borges Franco MMF","Crispim AA","Costa GAJ","et al."],"date":"2026-03-14","year":2026,"week":"2026-S11","doi":"10.1007/s10103-026-04834-3","pmcid":"PMC12987853","license":"cc by","oa":true,"pdf":"pdfs/41826477.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To evaluate the effectiveness of photobiomodulation therapy (PBMT) in the prevention of trismus in patients undergoing Intensity-Modulated Radiotherapy (IMRT) and Volumetric Modulated Arc Therapy (VMAT), through a randomized, triple-blind, placebo-controlled clinical trial. A total of 46 patients undergoing radiotherapy (RT) for head and neck cancer (HNC) were included. Patients were equally and randomly allocated to PBMT and PBMT placebo groups and were evaluated daily by measuring mouth opening, pain during mouth opening, and pain on palpation of the masticatory muscles using the Visual Analog Scale (VAS). An extraoral infrared laser (~ 808 nm), power of 0.1 W, energy of 3 J, 30 s (107 J/cm²) per point was used, applied extraorally to the anterior temporalis (AT), masseter (MM), and temporomandibular joints (TMJ), and intraorally to the medial pterygoid muscle (MP). The Food Quality Inventory (ASGP) and quality of life analysis (QoL) (OHIP-14) were also applied. Statistical analysis included Student’s t-test, Mann-Whitney test, and linear regression models (p < 0.05). Patients in the PBMT group showed a significantly smaller reduction in mouth opening during radiotherapy compared to the placebo group (p = 0.005), as well as a lower prevalence of masticatory muscle pain and grade 1 trismus (p = 0.002). No significant differences were observed between the groups regarding the decayed, missing, and filled teeth index (DMFT), the Oral Health Impact Profile-14 (OHIP-14), or the Anderson Symptom and Overall Performance scores (p > 0.05). Mouth opening did not differ between the groups at the six-month follow-up. Photobiomodulation therapy was effective in preventing trismus and masticatory muscle pain during radiotherapy.Clinical Trial RegistrationClinical trial number: RBR-67qxnt9 (registered on 16/04/2025)."}],"keywords":["Head and neck cancer","Low-level light therapy","Radiotherapy","Trismus","photobiomodulationd"]},{"pmid":"41836099","title":"Evaluation of Treatment Modalities for Radiation Therapy-Induced Trismus, Considering the Timing and Adherence to Progress in Mouth Opening and Oral Health-Related Quality of Life: A Systematic Review.","journal_abbr":"Patient Prefer Adherence","authors":["Meidarlina I","Rikmasari R","Wicaksono S","et al."],"date":"2026-03-09","year":2026,"doi":"10.2147/PPA.S585596","pmcid":"PMC12987709","license":"cc by-nc","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus"],"l1":"The effectiveness of treatment for radiation-induced trismus is influenced by the therapeutic modality, timing of therapy initiation, and patient adherence, all of which contribute to improvements in MO and OHRQoL. Combination therapy…","kw":"adherence mouth opening oral health–related quality of life radiation therapy treatment modalities trismus"},{"pmid":"41869643","title":"Commentary: Comparative efficacy and safety of non-pharmacological interventions on treatment-induced xerostomia in patients with head and neck cancer: a systematic review and network meta-analysis.","journal_abbr":"Front Oncol","authors":["Shazo S"],"date":"2026-03-06","year":2026,"doi":"10.3389/fonc.2026.1744455","pmcid":"PMC13002399","license":"cc by","oa":true,"pub_types":["Comment"],"curated":false,"type":"letter","level":0,"ctx":["xérostomie"],"l1":"","kw":"meta-analysis photobiomodulation radiotherapy sialagogues xerostomia"},{"pmid":"41893183","title":"Autologous Platelet Concentrates and Photobiomodulation as Biologically Active Modifiers of Hard and Soft Tissue Healing: A Randomised Controlled Trial.","journal_abbr":"J Funct Biomater","authors":["Selahi D","Dominiak M","Niemczyk W","et al."],"date":"2026-03-05","year":2026,"doi":"10.3390/jfb17030127","pmcid":"PMC13027921","license":"cc by","oa":true,"cited_by":4,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Both APCs and PBM positively influenced postoperative healing. Their combined application, particularly CGF with PBM, showed the most consistent regenerative effects, although not all outcomes differed significantly between groups. These…","kw":"bone regeneration photobiomodulation platelet-rich fibrin randomised controlled trial third molar extraction wound healing"},{"pmid":"41622096","title":"Clinical evidence for managing radiotherapy-induced oral mucositis and xerostomia in head and neck cancer patients: a review of Phase III-IV trials.","journal_abbr":"Int J Oral Maxillofac Surg","authors":["Alsahafi E"],"date":"2026-01-31","year":2026,"doi":"10.1016/j.ijom.2026.01.020","cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Although several interventions demonstrated promising clinical efficacy, the heterogeneity in study design, outcome measures, and follow-up duration limits definitive conclusions. Therefore, customized, evidence-driven approaches informed…","kw":"Clinical trial Head and neck neoplasms Oral mucositis Radiotherapy Xerostomia Humans Head and Neck Neoplasms Xerostomia Stomatitis Radiation Injuries Clinical T"},{"pmid":"41491205","title":"Photobiomodulation therapy in breast cancer-related acute radiodermatitis cases in Brazilian women: study protocol for a randomized controlled trial.","journal_abbr":"Trials","authors":["Silva SRRC","da Costa Veloso L","Silva RC","et al."],"date":"2026-01-05","year":2026,"doi":"10.1186/s13063-025-09294-8","pmcid":"PMC12771925","license":"cc by-nc-nd","oa":true,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":[],"em":["cw"],"l1":"5.788.390, registered on 24 August 2022. https://ensaiosclinicos.gov.br/rg/RBR-7gkw3d4 .","kw":"Breast neoplasms Low-level laser therapy Nursing Radiodermatitis Radiotherapy Female Humans Acute Disease Brazil Breast Neoplasms Low-Level Light Therapy"},{"pmid":"41454020","title":"Blue LED photobiomodulation in the prevention of radiodermatitis in breast cancer survivors: a clinical trial.","journal_abbr":"Support Care Cancer","authors":["Pivetta HMF","Kemerich JAP","Piussi JB","et al."],"date":"2025-12-26","year":2025,"doi":"10.1007/s00520-025-10274-6","pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":[],"nm":[470],"l1":"Blue LED may be a sound therapeutic strategy in radiodermatitis management, minimizing radiotherapy negative impacts, consequently improving the quality of life.","kw":"Breast neoplasms Photobiomodulation Quality of life Quality of life related to health Radiodermatitis Humans Female Breast Neoplasms Quality of Life Radiodermat"},{"pmid":"41249567","title_fr":"Laser basse énergie et transport lymphatique chez le volontaire sain : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Chez des volontaires sains, le laser stimule la motricité lymphatique, avec des différences selon la longueur d'onde.","l2":"Essai randomisé chez des sujets sains.","l3":{"points":["Mécanisme lymphatique."],"limites":["Sujets sains."],"pratique":"Base pour choisir le protocole."},"em":[],"pre":"","topic":"oncologie-support","title":"Comparing the direct effect of lymphatic dynamic transport after lower-level laser therapy in healthy volunteers: a randomized controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Bae H","Jeon JY","Choi SH","et al."],"date":"2025-11-17","year":2025,"week":"2025-S47","doi":"10.1007/s10103-025-04744-w","pmcid":"PMC12628450","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41249567.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study is aimed to explore the direct effects of low-level laser therapy (LLLT) at different wavelengths on lymphatic motility int healthy individuals. The goal was to identify the most effective protocol and assess the potential application of LLLT in managing lymphedema. The study included 32 healthy participants (12 males, and 20 females), divided into two groups. Each participant underwent a single session of unilateral upper extremity manual lymphatic drainage (UE MLD), followed by two types of LLLT applied to the ipsilateral axilla region to promote lymphatic drainage. Indocyanine green (ICG) lymphography was used during each treatment session to evaluate the immediate effect of LLLT on lymphatic motility. Additionally, extracellular fluid (ECF) and local tissue water level were assessed before and after the intervention using multiple frequency bioelectrical impedance analysis (MFBIA) and tissue dielectric constant (TDC). The overall reduction in body water content post-intervention was observed across multiple areas in both groups but without consistent statistical significance between groups. After UE MLD, the number of lymph packets significantly increased in both groups (Group A: from 3.20 ± 0.76 to 6.00 ± 1.38; Group B: from 2.80 ± 0.95 to 5.38 ± 1.44). However, during LLLT, the lymph packet count decreased significantly (Group A: to 1.73 ± 0.51; Group B: to 1.96 ± 0.67). Linear mixed model analysis showed that LLLT was associated with a reduction in lymph packet velocity (Estimate = - 1.22, 95% CI: - 2.08 to - 0.36, p = 0.006) and count (Estimate = - 1.11, 95% CI: - 1.57 to - 0.66, p < 0.001), while UE MLD significantly increased packet count (Estimate = 2.73, 95% CI: 2.28 to 3.19, p < 0.001). No significant intergroup differences were observed in lymphatic motility. This study quantitatively assessed lymphatic motility and tissue water content following different types of LLLT in healthy individuals. The findings suggest the need for further clinical studies to evaluate the effect of various LLLT parameters in lymphedema patients.Clinical trial number Not applicable."}],"keywords":["Breast cancer lymphedema","Low-level light therapy","Lymphedema","Upper extremity"]},{"pmid":"41789280","title":"Home-use Photobiomodulation for Pain Management and Recovery after Lower Third Molar Extraction: A Pilot Split-Mouth Study.","journal_abbr":"J Lasers Med Sci","authors":["Altayeb W","Tosun T","Kassem I","et al."],"date":"2025-11-15","year":2025,"doi":"10.34172/jlms.2025.53","pmcid":"PMC12958259","curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[630,660,850,940],"l1":"It offers a practical, non-invasive alternative to clinic-based treatments, enhancing accessibility and adherence. Further studies are recommended to validate these findings and optimize PBM protocols.","kw":"Low-level laser therapy Medication use Photobiomodulation Postoperative pain Swelling Third molar extraction"},{"pmid":"41184061","title":"RE: Is Low-Level Laser Treatment Effective in Reducing Pain, Swelling, and Trismus After Removing Impacted Maxillary and Mandibular Third Molars?","journal_abbr":"J Oral Maxillofac Surg","authors":["Faizan M"],"date":"2025-11-03","year":2025,"doi":"10.1016/j.joms.2025.06.230","pub_types":["Letter"],"curated":false,"type":"letter","level":0,"ctx":["trismus"],"l1":"","kw":""},{"pmid":"41253620","title_fr":"Traitements de la xérostomie radio-induite des cancers ORL : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Aucun traitement de la xérostomie radio-induite ne s'impose ; les données sur la PBM restent non concluantes.","l2":"Méta-analyse d'essais randomisés (PubMed, Google Scholar) comparant les traitements de la xérostomie radio-induite des cancers ORL.\n\nPas de réduction significative de la sévérité de la xérostomie à 3, 4 ou 6 semaines ni à 6 mois. Le débit salivaire non stimulé augmente (DM 0,13 ; IC 0,09–0,17), pas le débit stimulé (DM 0,22 ; p = 0,15). La douleur buccale diminue (DM −2,25). Pas d'effet sur la mucite, la dysphagie ou la fatigue. Hétérogénéité importante.","l3":{"points":["Compare l'ensemble des options disponibles."],"limites":["Deux bases interrogées seulement.","Aucune intervention n'a d'efficacité constante."],"pratique":"Ne pas présenter la PBM comme un traitement établi de la xérostomie installée."},"em":[],"pre":"","topic":"oncologie-support","title":"Treatment options for radiation-induced xerostomia in patients with head and neck cancer: a systematic review and meta-analysis.","journal":"The British journal of oral & maxillofacial surgery","journal_abbr":"Br J Oral Maxillofac Surg","authors":["Shrateh ON","Habib A","Ur Rehman Shamsi H","et al."],"date":"2025-10-28","year":2025,"week":"2025-S44","doi":"10.1016/j.bjoms.2025.10.003","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":2,"abstract":[{"label":"","text":"Radiation-induced xerostomia is a frequent and debilitating complication in patients undergoing radiotherapy for head and neck cancer. This study aimed to compare the effectiveness of available treatment modalities in preventing or managing radiation-induced xerostomia and associated complications in head and neck cancer patients. A detailed search of PubMed and Google Scholar was conducted. Only randomised controlled trials (RCTs) involving radiotherapy-treated head and neck cancer patients were included. The interventions that were analysed encompassed pharmacological agents (for example, pilocarpine, and amifostine), antioxidants, herbal formulations, acupuncture, low-level laser therapy (LLLT), and regenerative approaches. Primary outcomes included severity of xerostomia, rates of salivary flow, mucositis, oral pain, dysphagia, and fatigue. Thirty-one randomised clinical trials met the inclusion criteria. Pooled analysis showed no significant reduction in severity of xerostomia at weeks 3, 4, or 6, or 6 months. Stimulated salivary flow did not significantly improve (mean difference (MD): 0.22; p = 0.15), while unstimulated salivary flow showed a significant benefit (MD: 0.13; 95% CI: 0.09 to 0.17; p < 0.00001). A significant reduction in the severity of oral pain was also noted (MD: -2.25; p < 0.0001). No significant differences were found for the incidence or duration of mucositis, dysphagia, or fatigue. Considerable heterogeneity was observed across the studies and no single intervention demonstrated consistent efficacy in managing radiation-induced xerostomia. Some therapies have shown promise in improving unstimulated salivary flow and reducing oral pain; however, the overall evidence remains inconclusive. To address this persistent clinical challenge, future trials should adopt standardised outcome measures, assess combination therapies, and investigate novel regenerative strategies."}],"keywords":["head and neck cancer","radiotherapy","salivary gland dysfunction","xerostomia"]},{"pmid":"41123652","title":"Long-pulsed 1064-nm neodymium: yttrium-aluminum-garnet laser alleviates rosacea by improving lymphatic vessel dysfunction.","journal_abbr":"Inflamm Res","authors":["Gu D","Pan R","Liu T","et al."],"date":"2025-10-22","year":2025,"doi":"10.1007/s00011-025-02117-1","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"em":["pulse"],"l1":"We elucidated the abnormalities of lymphatic vessels in rosacea and provided evidence supporting the targeted lymphatic vessel therapies.","kw":"Etiology Laser therapy Lymphatic vessels Lymphedema Rosacea Animals Female Rosacea Lasers, Solid-State Humans Mice, Inbred BALB C"},{"pmid":"41108777","title":"Multimodal physiotherapeutic management of postoperative complications in orthognathic surgery: A literature review and institutional protocol proposal.","journal_abbr":"Med Oral Patol Oral Cir Bucal","authors":["Fernández-de-la-Reguera A","Muñoz A","Sotelo O","et al."],"date":"2025-10-18","year":2025,"doi":"10.4317/medoral.27687","pmcid":"PMC12981635","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Early, structured physiotherapeutic management is fundamental to postoperative care in OS. The proposed protocol offers a replicable, evidence-based framework to facilitate optimal recovery and functional reintegration.","kw":"Humans Orthognathic Surgical Procedures Postoperative Complications Physical Therapy Modalities Clinical Protocols Combined Modality Therapy"},{"pmid":"41013422","title_fr":"PBM pour restaurer le débit salivaire après radiothérapie ORL : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[830],"n":31,"effect":"favorable","theme":"Xérostomie","l1":"Chez des patients en rémission avec xérostomie chronique, la PBM augmente objectivement le débit salivaire, signe d'un possible effet régénérateur.","l2":"Essai randomisé en double aveugle contre placebo, 31 patients.","l3":{"points":["Xérostomie chronique, plus de 3 mois après la radiothérapie."],"limites":["Autres critères moins nets."],"pratique":"Prometteur."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Photobiomodulation for restoring salivary flow after radiotherapy in head and neck cancer: a randomised placebo-controlled trial.","journal":"BMC oral health","journal_abbr":"BMC Oral Health","authors":["Lopez-Garzon M","Plata-Peregrina MDC","Perez-Sanchez EI","et al."],"date":"2025-09-26","year":2025,"week":"2025-S39","doi":"10.1186/s12903-025-06735-3","pmcid":"PMC12465775","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41013422.pdf","cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Head and neck cancer (HNC) treatment modalities, especially radiotherapy (RT), often lead to salivary gland dysfunction, resulting in hyposalivation and xerostomia, which impair patients' quality of life. Photobiomodulation (PBM) therapy, a noninvasive approach using nonthermal red/near-infrared light, has shown promise in mitigating these side effects. This study evaluated the impact of PBM therapy on salivary flow, biochemical biomarkers, patient-reported outcome measures and mouth opening in patients with HNC suffering from chronic xerostomia after RT."},{"label":"METHODS","text":"In a prospective, two-arm, randomised, placebo-controlled, double-blinded trial, 31 adult patients with HNC in complete remission and chronic xerostomia (> 3 months after RT) were enrolled. Participants were randomised (1:1) to receive either active PBM therapy or a sham intervention. The PBM protocol employs an 830 nm diode device applied intra- and extraorally over 24 sessions (twice weekly for 3 months) targeting the major salivary glands. The outcome measures assessed at baseline, 3 months (postintervention), and 6 months included the unstimulated salivary flow rate (SFR) by sialometry, total protein and IgA (sialochemistry), quality of life via European Organisation for Research and Treatment of Cancer (EORTC) questionnaires, severity of xerostomia, dysphagia, and mouth opening. Data were analysed using repeated measures analysis of covariance (ANCOVA) (adjusting for relevant covariates) and nonparametric tests, as appropriate."},{"label":"RESULTS","text":"Compared with the placebo group, the PBM group presented a nearly significant increase in the SFR (0.22 ± 0.29 vs. 0.05 ± 0.15 ml/min, p = 0.051; effect size d = 0.75) after the intervention. A responder analysis revealed that five patients in the PBM group shifted from hyposalivation (SFR < 0.25 ml/min) to normal salivary flow, whereas no such change was observed in the placebo group (p = 0.048). Both groups reported similar levels of satisfaction and adherence, and no adverse events were recorded."},{"label":"CONCLUSIONS","text":"PBM therapy demonstrated potential benefits in improving salivary flow among oncological patients with chronic RT-induced xerostomia, suggesting possible regenerative effects on the salivary glands. Despite the objective improvements in the SFR, changes in biochemical markers and the remaining outcome measures were less definitive in patients with HNC. Further studies with larger sample sizes are needed to confirm these preliminary findings and better delineate the clinical utility of this therapy."},{"label":"TRIAL REGISTRATION","text":"This trial was registered on ClinicalTrials.gov (NCT05614843) and First Posted date [2022-11-14]."}],"keywords":["Head and neck neoplasms","Low-level light therapy","Quality of life","Xerostomia"]},{"pmid":"40973840","title_fr":"Laser ou TENS sur les glandes salivaires dans le diabète de type 2 : analyse intermédiaire","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":8,"effect":"—","theme":"Xérostomie","l1":"Chez huit diabétiques, la stimulation des glandes salivaires par laser ou TENS pourrait modifier le microbiote buccal ; résultats exploratoires.","l2":"Analyse intermédiaire d'un essai randomisé.","l3":{"points":["Microbiote."],"limites":["Huit participants."],"pratique":"Exploratoire."},"em":[],"pre":"","topic":"oncologie-support","title":"Low-level laser and transcutaneous electrical nerve stimulation on salivary glands impact type 2 diabetes mellitus oral microbiome: an interim analysis of a randomized trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Melo JLMA","Nunes FPES","Coelho CPES","et al."],"date":"2025-09-20","year":2025,"week":"2025-S38","doi":"10.1007/s10103-025-04609-2","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Diabetes Mellitus (DM) can lead to significant reduction of saliva production, which increases the risk of oral diseases. Managing reduced salivary flow becomes indispensable for restoring microbial balance in this condition. This study aimed to investigate the effects of physical stimulation methods on salivary secretion rate and microbiome composition in individuals with type 2 DM (T2DM) having reduced salivary flow using an exploratory interim analysis of a randomized clinical trial."},{"label":"METHODS","text":"Eight individuals provided a total of 15 stimulated or rest saliva samples and were randomly assigned to the following groups: low-level laser therapy (LLLT) (G1), transcutaneous electrical nerve stimulation (TENS)(G2), and a combination of both methods(G3), administered twice a week over a span of 10 sessions. Salivary flow was evaluated at three time points: recruitment, before the 1st session (baseline) and after the 10th session. Subjective dry mouth was evaluated using the TESS scale at baseline and after the final session. DNA was extracted from whole saliva immediately before treatment (baseline) and after the final stimulation session, 16 S rRNA gene amplified and sequenced (Illumina MiSeq)."},{"label":"RESULTS","text":"N = 7 individuals showed improvement in stimulated salivary flow (SSF), achieving or maintaining normal range (SSF > 0.7 ml/min). Bacterial diversity was significantly higher in saliva after stimuli with laser(G1) when compared to TENS(G2). The relative abundance of Firmicutes and Fusobacteriota increased after all treatments, while Actinobacteriota and Proteobacteria decreased. The abundance of minority taxa was reduced after stimulation."},{"label":"CONCLUSION","text":"This exploratory study provides initial indications that physical stimulation may help manage T2DM-related reduced salivary flow and could be associated with subtle changes in low-abundance taxa suggesting a potential \"clearance\" effect. These preliminary observations require confirmation through larger, long-term studies."},{"label":"TRIAL REGISTRATION NUMBER","text":"RBR-3tqv8r3. Date of registration: 13th April 2023."}],"keywords":["Diabetes mellitus","Low-level light therapy","Microbiota","Transcutaneous electric nerve stimulation","Xerostomia"]},{"pmid":"40785030","title":"Increased Salivary Flow Using Photobiomodulation Therapy in a Patient With Sjögren's Syndrome: A Case Report.","journal_abbr":"Lasers Surg Med","authors":["Grossmann SMC","Lopes LC","Grossmann de Almeida L","et al."],"date":"2025-08-10","year":2025,"doi":"10.1002/lsm.70053","cited_by":1,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"l1":"PBMT with a low-level laser proved to be an effective nonpharmacological therapeutic option for conditions of xerostomia in SS, particularly in young patients. Further studies with larger patient samples are necessary to validate the…","kw":"low level laser therapy photobiomodulation xerostomia Humans Female Sjogren's Syndrome Low-Level Light Therapy Adolescent Xerostomia"},{"pmid":"40809028","title_fr":"Interventions non médicamenteuses contre la xérostomie des cancers ORL : méta-analyse en réseau","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Contre la xérostomie, le gel hydratant et la stimulation électrique sont les mieux classés ; la PBM est une option complémentaire prometteuse.","l2":"Revue systématique et méta-analyse en réseau.","l3":{"points":["Classement des options."],"limites":["Comparaisons indirectes."],"pratique":"La PBM en complément."},"em":[],"pre":"","topic":"oncologie-support","title":"Comparative efficacy and safety of non-pharmacological interventions on treatment-induced xerostomia in head and neck cancer patients: a systematic review and network meta-analysis.","journal":"Frontiers in oncology","journal_abbr":"Front Oncol","authors":["Tai J","Guo A","Chen J","et al."],"date":"2025-07-30","year":2025,"week":"2025-S31","doi":"10.3389/fonc.2025.1644178","pmcid":"PMC12343224","license":"cc by","oa":true,"pdf":"pdfs/40809028.pdf","cited_by":3,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"AIM","text":"To comprehensively evaluate the efficacy and safety of non-pharmacological interventions for radiotherapy-induced xerostomia in patients with head and neck cancer."},{"label":"METHODS","text":"A systematic literature search was conducted in PubMed, Embase, the Cochrane Library, and Web of Science for articles published up to March 1, 2025. Three outcome measures were utilized to assess treatment effectiveness: xerostomia, saliva flow rate, and xerostomia-related quality of life. A Bayesian network meta-analysis was employed to synthesize the comparative performance of different non-pharmacological interventions. The study protocol was registered in the PROSPERO database (CRD420251027019)."},{"label":"RESULTS","text":"A total of 30 RCTs encompassing 1,595 participants and nine distinct non-pharmacological treatment modalities were included. Compared with the SOC, mouthwash demonstrated the most pronounced improvement in XQ (SMD = -0.70; 95% CI: -1.38 to -0.01) and XI scores (SMD = -0.68; 95% CI: -1.09 to -0.26). Oral moisturizing gel exhibited the greatest reduction in VAS scores (SMD = -1.55; 95% CI: -2.31 to -0.80). Regarding salivary flow enhancement, oral moisturizing gel was most effective in increasing USFR (SMD = 3.83; 95% CI: 0.56 to 7.09), while chewing gum provided the highest gain in SSFR (SMD=3.66; 95%CI: -0.08 to 7.41). Among safety outcomes, electrical stimulation therapy was associated with the most favorable profile relative to SOC (SMD = -1.82; 95% CI: -3.96 to 0.33)."},{"label":"CONCLUSIONS","text":"Non-pharmacological interventions appear to offer superior efficacy with comparable safety to SOC in care of radiotherapy-induced xerostomia among patients with head and neck cancer. Mouthwash is likely the most effective option for alleviating subjective xerostomia symptoms, with oral moisturizing gel as a valuable alternative. For salivary flow enhancement, oral moisturizing gel is preferred for unstimulated flow, whereas chewing gum is optimal for stimulated flow. Electrical stimulation therapy may yield the most substantial improvement in quality of life, with photobiomodulation therapy representing a promising adjunctive strategy."},{"label":"SYSTEMATIC REVIEW REGISTRATION","text":"Prospective Register of Systematic Reviews (PROSPERO), identifier CRD420251027019."}],"keywords":["Xerostomia","evidence-based","head and neck cancer","network meta-analysis","non-pharmacological intervention"]},{"pmid":"40673647","title":"Talquetamab-Induced Dysgeusia Successfully Treated With Photobiomodulation Therapy.","journal_abbr":"Laryngoscope","authors":["Kayahara GM","Espinhosa RB","da Silva SN","et al."],"date":"2025-07-17","year":2025,"doi":"10.1002/lary.32445","cited_by":2,"pub_types":["Case Reports","Research Support, Non-U.S. Gov't"],"curated":false,"type":"cases","level":4,"ctx":[],"nm":[660,808],"l1":"The current clinical report demonstrated the potential effectiveness of a PBM protocol developed for the treatment of talquetamab-related dysgeusia. The management of this oral side effect using PBM could prevent treatment interruption…","kw":"dysgeusia multiple myeloma photobiomodulation talquetamab Humans Male Middle Aged Low-Level Light Therapy Dysgeusia Multiple Myeloma"},{"pmid":"40554095","title":"Photobiomodulation in major and minor salivary glands in Sjögren's Syndrome.","journal_abbr":"J Stomatol Oral Maxillofac Surg","authors":["Reia VCB","de Alencar JCG","Dos Santos Sobrinho O","et al."],"date":"2025-06-17","year":2025,"doi":"10.1016/j.jormas.2025.102437","pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"l1":"However, the inconsistent findings indicate that more studies and established practices are required. Despite these, the letter contributes significantly by offering details that could guide future research and improve patient outcomes.","kw":"Hyposalivation Low-level laser therapy Sjogren's syndrome Humans Sjogren's Syndrome Low-Level Light Therapy Salivary Glands, Minor Salivary Glands"},{"pmid":"40498366","title":"Photobiomodulation in the parotid and submandibular glands: a Monte Carlo simulation of photon penetration using 525-nm, 660-nm, and 850-nm wavelengths.","journal_abbr":"Lasers Med Sci","authors":["Correa L","Meirelles L","Carneiro RCG","et al."],"date":"2025-06-11","year":2025,"doi":"10.1007/s10103-025-04507-7","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[525,660,850],"l1":"The increased salivary flow observed in rats following treatment with 850 nm suggests a beneficial effect of this wavelength on salivary gland function. Clinical trial number: Not applicable.","kw":"Monte Carlo simulation Photobiomodulation Salivary glands Xerostomia Monte Carlo Method Submandibular Gland Parotid Gland Animals Low-Level Light Therapy Rats"},{"pmid":"40488944","title":"Photobiomodulation therapy for salivary gland hypofunction: a preliminary human study.","journal_abbr":"Lasers Med Sci","authors":["Colares DF","de Souto Medeiros MR","de Araújo ACG","et al."],"date":"2025-06-09","year":2025,"doi":"10.1007/s10103-025-04512-w","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"l1":"Thus, our study demonstrates the efficacy of PBMT in treating salivary gland hypofunction, with a significant and sustained increase in UWSF rate even after the end of treatment. These findings suggest that PBMT may effectively improve…","kw":"Low-level light therapy Photobiomodulation Saliva Salivary glands Salivary hypofunction Humans Low-Level Light Therapy Male Female Middle Aged Quality of Life"},{"pmid":"40475300","title":"Potential role of photobiomodulation as a prevention and treatment strategy for radiation induced fibrosis: a review of effectiveness and mechanisms.","journal_abbr":"PeerJ","authors":["Gururaj R","Thomas B","Janaki MG","et al."],"date":"2025-06-02","year":2025,"doi":"10.7717/peerj.19494","pmcid":"PMC12139614","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus"],"l1":"PBMT offers a promising intervention for managing RIF, with potential to enhance body image, self-confidence, functional abilities, and overall quality of life for cancer survivors. This review underscores the need for further research to…","kw":"LED Low level LASER therapy Radiation fibrosis syndrome Radiation therapy Survivorship Humans Low-Level Light Therapy Fibrosis Animals Radiation Injuries"},{"pmid":"40486300","title":"Global Preventive and Management Strategies and Their Effectiveness in Patients With Secondary Lymphedema: A Scoping Review.","journal_abbr":"Cureus","authors":["Mwesigye V","Atwine D","Munguciada EF","et al."],"date":"2025-05-07","year":2025,"doi":"10.7759/cureus.83627","pmcid":"PMC12142275","license":"cc by","oa":true,"cited_by":3,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Knowledge gaps and misconceptions among patients, healthcare workers, and communities hinder effective disease management, with stigma and misinformation remaining key barriers despite educational efforts. While microsurgical…","kw":"filariasis kamwenge lymphedema neglected tropical diseases podoconiosis uganda"},{"pmid":"40510703","title":"Effects of low-level laser therapy and intramasseteric triamcinolone on postoperative sequelae following mandibular third molar surgery: A comparative study.","journal_abbr":"Natl J Maxillofac Surg","authors":["Tiwari RS","Deshpande N","Mundada B","et al."],"date":"2025-04-28","year":2025,"doi":"10.4103/njms.njms_67_23","pmcid":"PMC12156854","license":"cc by-nc-sa","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"nm":[650],"em":["cw"],"l1":"In its limitations, the study concluded that triamcinolone acetonide acts as a better treatment modality than laser treatment during an assessment.","kw":"Corticotherapy impacted third molar laser therapy"},{"pmid":"40259459","title":"From molecular mechanisms to clinical applications: A comprehensive review of photobiomodulation in cancer treatment.","journal_abbr":"Photochem Photobiol","authors":["Wang Q","Oh PS","Jeong HJ"],"date":"2025-04-21","year":2025,"doi":"10.1111/php.14107","cited_by":3,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Furthermore, the ability of PBM to inhibit cancer cell proliferation and induce apoptosis, and discusses safety concerns of PBM in clinical applications, presenting existing research that emphasizes its significant potential in cancer…","kw":"cancer clinical treatment photobiomodulation phototherapy Humans Neoplasms Low-Level Light Therapy Animals Apoptosis Cell Proliferation"},{"pmid":"40219929","title":"Efficacy of photobiomodulation therapy on pain, swelling, and trismus following fixation of mandibular fractures.","journal_abbr":"Wound Repair Regen","authors":["Nayak SS","Varshney S","Maiya GA","et al."],"date":"2025-04-12","year":2025,"doi":"10.1111/wrr.70026","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[660,905],"em":["pulse"],"l1":"-1.31; p < 0.001). In summary, a specific PBM protocol can effectively reduce trismus during recovery from mandibular fractures, with the potential for future optimization to address pain and edema.","kw":"mandibular fracture pain photobiomodulation therapy swelling trismus Humans Trismus Mandibular Fractures Edema Male Female"},{"pmid":"40184883","title_fr":"PBM pour prévenir les effets buccaux des traitements des cancers ORL : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Pendant le traitement des cancers ORL, la PBM retarde et réduit la mucite et l'hyposialie, mais n'a pas d'effet sur la xérostomie ressentie ni sur le trismus.","l2":"Essai randomisé en simple aveugle (Oral Oncol).","l3":{"points":["Effet sur l'hyposialie objective."],"limites":["Pas d'effet sur le trismus."],"pratique":"Bénéfice partiel."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation for the prevention of oral side effects secondary to head and neck cancer therapy: results of a randomised, single-blind clinical trial.","journal":"Oral oncology","journal_abbr":"Oral Oncol","authors":["Vianna Camolesi GC","Prado-Pena IB","Gómez-Caamaño A","et al."],"date":"2025-04-03","year":2025,"week":"2025-S14","doi":"10.1016/j.oraloncology.2025.107266","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"INTRODUCTION","text":"A significant increase of 61.6 % in new cases of head and neck cancer (HNC) worldwide is projected by 2050. Multimodal treatments for HNC often result in debilitating oral side effects like oral mucositis (OM). Photobiomodulation (PBM) therapy shows promise in managing these side effects, yet standardized protocols are lacking. This randomized clinical trial aims to evaluate PBM's effectiveness in preventing and treating oral side effects and related symptoms in HNC patients."},{"label":"METHODS","text":"We compared PBM with standard treatment in HNC patients at a single centre. PBM efficacy was evaluated on OM, pain, dysgeusia, hyposalivation, dry mouth, and trismus. Additionally, we controlled for analgesic use and fungal infection presence. The study adhered to the CONSORT checklist, is registered on the ClinicalTrials platform, and statistical analysis was performed using SPSS."},{"label":"RESULTS","text":"The study included 53 patients. The PBM group experienced a significant reduction in OM progression, better salivary function preservation, and lower severity of pain and dysgeusia by the end of treatment. However, no significant differences were found between the PBM and standard treatment groups regarding xerostomia, trismus, analgesic use, or oral candidiasis incidence."},{"label":"CONCLUSION","text":"PBM showed effectiveness in delaying onset and reducing the severity of oral mucositis and hyposalivation, as well as alleviating pain and dysgeusia at critical moments. However, it had no significant impact on xerostomia, trismus, analgesic use, or oral candidiasis."}],"keywords":["Dysgeusia","Hyposalivation","Oral mucositis","Photobiomodulation therapy","Supportive cancer care","Toxicity"]},{"pmid":"40765879","title":"Efficacy of Low-level Laser Therapy in Minimising Morbidity Associated with Removal of Impacted Mandibular Third Molar - A Comparative Study.","journal_abbr":"Ann Maxillofac Surg","authors":["Jha M","Marimallappa TR","Kumar RM","et al."],"date":"2025-03-07","year":2025,"doi":"10.4103/ams.ams_247_23","pmcid":"PMC12321191","license":"cc by-nc-sa","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"em":["cw"],"l1":"The results showed a statistically significant (P = 0.05) decrease in the level of pain, facial swelling and trismus in the study group. LLLT, in continuous mode, has a significant effect in reducing post-extraction morbidities and…","kw":"Efficacy low-level laser therapy morbidity third molar extraction"},{"pmid":"40038715","title_fr":"Traitements du trismus radio-induit : essai randomisé à trois bras","type":"rct","level":2,"pop":"adulte","ctx":["trismus"],"aim":"traitement","mode":["laser"],"nm":[],"n":36,"effect":"favorable","theme":"Trismus & fibrose radio-induite","l1":"Dans le trismus radio-induit, l'association d'un dispositif d'ouverture et du laser donne l'amélioration la plus rapide et la plus importante.","l2":"Essai randomisé, 36 patients.","l3":{"points":["Effet à 3 et 6 mois."],"limites":["Petit effectif."],"pratique":"Associer laser et rééducation de l'ouverture."},"em":[],"pre":"","topic":"oncologie-support","title":"Efficiency of different treatment modalities on radiation induced trismus for maxillofacial cases: a parallel randomized clinical trial.","journal":"BMC oral health","journal_abbr":"BMC Oral Health","authors":["Aboelez MA","Ibrahim AM","ElSawy MA","et al."],"date":"2025-03-04","year":2025,"week":"2025-S10","doi":"10.1186/s12903-025-05600-7","pmcid":"PMC11877843","license":"cc by","oa":true,"pdf":"pdfs/40038715.pdf","cited_by":4,"pub_types":["Randomized Controlled Trial","Comparative Study"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"For more than 80% of patients with head and neck cancer, radiation therapy (RT) is a crucial component of their treatment plane which causes impairment for the masticatory apparatus functions leading to trismus. The study objective was to compare the efficacy of different treatment modalities for patients with RT-induced trismus on maximum mouth opening (MMO), visual analogue scale (VAS) (primary outcomes) patient satisfaction (secondary outcome)."},{"label":"METHODS","text":"Thirty-six patients with trismus after radiation therapy were classified equally and randomly into three groups (n = 12 per group): Group A was given threaded tapered screw appliance therapy (TTSA), Group B was given low-level laser therapy (LLLT), and Group C was given both threaded tapered screw appliance and low-level laser therapy (LLLT + TTSA). Maximum mouth opening (MMO), visual analogue scale (VAS) and Gothenburg Trismus Questionnaire (GTQ) scores and time required to achieve normal state were evaluated at baseline, 1, 2, 4 weeks, 3 and 6 months after the intervention. Data were collected and analysed using SPSS software."},{"label":"RESULTS","text":"Regarding VAS and MMO, there was a statistically significant difference at different times of evaluation within all groups where (P <.0001). Regarding GTQ, group C recorded the least values for GTQ symptoms followed by group B followed by group A. Between groups A, B, and C at six months, there was a statistically significant difference for VAS. At three and six months, there was a statistically significant difference between all groups for MMO. At three and six months, there was a statistically significant difference between groups for all GTQ domains."},{"label":"CONCLUSION","text":"All available therapy modalities have the potential to effectively improve radiation induced trismus; however, the combination of TTSA and LLLT group appears to yield the most rapid and optimal enhancement."},{"label":"CLINICAL TRIAL REGISTRY NUMBER","text":"(NCT06413628) (05/12/2024) Retrospectively registered."}],"keywords":["Low-level laser","Radiation therapy","Threaded tapered screw appliance","Trismus"]},{"pmid":"40011868","title":"The effect of preoperative low-level laser therapy on pain, swelling, and trismus associated with mandibular third molar extraction.","journal_abbr":"BMC Oral Health","authors":["Karşıcı S","Balaban E"],"date":"2025-02-26","year":2025,"doi":"10.1186/s12903-025-05589-z","pmcid":"PMC11866568","license":"cc by-nc-nd","oa":true,"cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"Within the limitations of this study, preoperative LLLT showed clinically acceptable effects on postoperative pain, swelling, and trismus. Further clinical studies are needed to evaluate the long-term success of LLLT.","kw":"Impacted tooth LLLT Laser Pain Swelling Third molar Humans Molar, Third Trismus Tooth Extraction Female Male"},{"pmid":"39833441","title":"Management of radiotherapy-induced hyposalivation using photobiomodulation therapy: a case series.","journal_abbr":"Lasers Med Sci","authors":["Alsoghier A","Mutaieb S","Bukhari A","et al."],"date":"2025-01-20","year":2025,"doi":"10.1007/s10103-025-04292-3","cited_by":2,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["xérostomie"],"l1":"The findings showed the usefulness of PBMT in reducing xerostomia and taste changes and possibly increasing salivary flow over a 4-week duration. However, randomised clinical trials are needed to assess the long-term effectiveness of PBMT…","kw":"Head and neck neoplasms Low-level light therapy Quality of life Radiotherapy Taste disorders Xerostomia Adult Aged Female Humans Male Middle Aged"},{"pmid":"40330510","title":"Photobiomodulation Therapy in Improving Quality of Life in Kindler Syndrome: A Case Study.","journal_abbr":"J Lasers Med Sci","authors":["Khatoon F","Surendraprasad Mishra S","Shailesh Sawant V","et al."],"date":"2025-01-18","year":2025,"doi":"10.34172/jlms.2025.02","pmcid":"PMC12049579","pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"It offers significant improvements in mouth opening, which can enhance oral hygiene, nutritional intake, and overall quality of life. This non-invasive approach provides a viable option for patients with KS who require prosthetic…","kw":"Hereditary acrokeratotic Kindler syndrome Photobiomodulation therapy Poikiloderma Trismus"},{"pmid":"39825016","title":"Effects of photobiomodulation and bethanechol chloride treatment on salivary composition and flow rate in head and neck cancer patients undergoing radiotherapy: longitudinal interventional experimental clinical study.","journal_abbr":"Support Care Cancer","authors":["Schepanski N","da Silva Liebl BM","Mendes RT","et al."],"date":"2025-01-17","year":2025,"doi":"10.1007/s00520-024-09120-y","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"l1":"The results suggest that both PBMT and BC treatments can effectively mitigate the impacts of RT, since quality and quantity of saliva were maintained.","kw":"Photobiomodulation Radiotherapy Saliva Trace elements Xerostomia Humans Saliva Head and Neck Neoplasms Male Female Xerostomia"},{"pmid":"40224121","title":"A scientometric study on research trends and characteristics of burning mouth syndrome.","journal_abbr":"J Dent Sci","authors":["Liu W","Zhang Y","Zhu Q","et al."],"date":"2025-01-17","year":2025,"doi":"10.1016/j.jds.2025.01.009","pmcid":"PMC11993054","license":"cc by-nc-nd","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"This scientometric study elucidated the current scenario and research trends of BMS, and would help in improving in reciprocal collaboration and communication for investigations on this condition.","kw":"Bibliometrics Burning mouth syndrome Neurological factors Psychological factors Therapy strategy"},{"pmid":"39792256","title_fr":"Prévention de l'hyposialie et de la xérostomie des traitements non chirurgicaux du cancer : revue","type":"sr","level":1,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Pour prévenir l'hyposialie, limiter la dose de radiothérapie aux glandes salivaires est le plus efficace ; la PBM n'est qu'une option parmi d'autres.","l2":"Mise à jour de la revue systématique MASCC/ISOO de 2010 (Medline, Embase, Cochrane) sur la prévention de l'hyposialie et de la xérostomie induites par les traitements non chirurgicaux du cancer, limitée aux essais randomisés.\n\nLes techniques d'épargne des glandes salivaires et la radiothérapie avec modulation d'intensité restent les seules mesures bien étayées. Les preuves sont limitées pour la vitamine E, l'amifostine, l'acupuncture, le béthanéchol et la photobiomodulation. Aucune donnée pour les immunothérapies.","l3":{"points":["Revue de société savante (MASCC/ISOO).","Essais randomisés uniquement."],"limites":["La PBM n'y est qu'une intervention parmi d'autres, peu étudiée en prévention."],"pratique":"En prévention, la priorité reste de limiter la dose reçue par les glandes salivaires ; la PBM n'est pas recommandée dans cette indication."},"em":[],"pre":"","topic":"oncologie-support","title":"A systematic review of salivary gland hypofunction and/or xerostomia induced by non-surgical cancer therapies: prevention strategies.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Mercadante V","Smith DK","Abdalla-Aslan R","et al."],"date":"2025-01-10","year":2025,"week":"2025-S02","doi":"10.1007/s00520-024-09113-x","pmcid":"PMC11723892","license":"cc by","oa":true,"pdf":"pdfs/39792256.pdf","cited_by":11,"pub_types":["Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"PURPOSE","text":"This systematic review aimed to assess the updated literature for the prevention of salivary gland hypofunction and xerostomia induced by non-surgical cancer therapies."},{"label":"METHODS","text":"Electronic databases of MEDLINE/PubMed, EMBASE, and Cochrane Library were searched for randomized controlled trials (RCT) that investigated interventions to prevent salivary gland hypofunction and/or xerostomia. Literature search began from the 2010 systematic review publications from the Multinational Association of Supportive Care in Cancer/International Society of Oral Oncology (MASCC/ISOO) up to February 2024. Two independent reviewers extracted information regarding study design, study population, cancer treatment modality, interventions, outcome measures, methods, results, risk of bias (RoB version 2), and conclusions for each article."},{"label":"RESULTS","text":"A total of 51 publications addressing preventive interventions were included. Eight RCTs on tissue-sparing radiation modalities were included showing significant lower prevalence of xerostomia, with unclear effect on salivary gland hypofunction. Three RCTs on preventive acupuncture showed reduced prevalence of xerostomia but not of salivary gland hypofunction. Two RCTs on muscarinic agonist stimulation with bethanechol suggested a preventive effect on saliva flow rate and xerostomia in patients undergoing head and neck radiation or radioactive iodine therapy. Two studies on submandibular gland transfer showed higher salivary flow rates compared to pilocarpine and lower prevalence of xerostomia compared to no active intervention. There is insufficient evidence on the effectiveness of vitamin E, amifostine, photobiomodulation, and miscellaneous preventive interventions."},{"label":"CONCLUSION","text":"This systematic review continues to support the potential of tissue-sparing tecniques and intensity-modulated radiation therapy (IMRT) to preserve salivary gland function in patients with head and neck cancer, with limited evidence on other preventive strategies, including acupuncture and bethanecol. Preventive focus should be on optimized and new approaches developed to further reduce radiation dose to the parotid, the submandibular, and minor salivary glands. As these glands are major contributors to moistening of the oral cavity, limiting the radiation dose to the salivary glands through various modalities has demonstrated reduction in prevalence and severity of salivary gland hypofunction and xerostomia. There remains no evidence on preventive approaches for checkpoint inhibitors and other biologicals due to the lack of RCTs."}],"keywords":["Checkpoint inhibitors","Chemotherapy","Radiotherapy","Salivary gland hypofunction","Xerostomia"]},{"pmid":"39744416","title":"The immediate pain relief of low-level laser therapy for burning mouth syndrome: a retrospective study of 94 cases.","journal_abbr":"Front Oral Health","authors":["Mu W","Li S","Lu Q","et al."],"date":"2024-12-18","year":2024,"doi":"10.3389/froh.2024.1458329","pmcid":"PMC11688308","license":"cc by","oa":true,"cited_by":4,"curated":false,"type":"autre","level":0,"ctx":[],"nm":[635],"l1":"LLLT may provide non-pharmacological, non-invasive, side-effect-free, and rapid pain relief for painful BMS patients. No baseline characteristics affecting overall efficiency were found except for VAS before treatment, history of smoking…","kw":"burning mouth syndrome low-level laser therapy pain management retrospective study visual analogue scale"},{"pmid":"39768334","title":"Evaluation of the Low-Level Laser Therapy in Pain, Bite Force, and Mouth Opening Following Midfacial Trauma.","journal_abbr":"Life (Basel)","authors":["Pavelski MD","Pavelski MD","Oliveira LF","et al."],"date":"2024-12-09","year":2024,"doi":"10.3390/life14121626","pmcid":"PMC11677420","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"In the evaluation of paresthesia, on days 7 and 14, there were better results in the LASER group with p = 0.012 and p = 0.001. The laser acted as a moderator of the healing process, having a considerable effect on the aspects of trismus,…","kw":"low-level light therapy maxillofacial injuries pain management zygomatic fractures"},{"pmid":"39614391","title":"Cancer treatment-related xerostomia: basics, therapeutics, and future perspectives.","journal_abbr":"Eur J Med Res","authors":["Hosseini MS","Sanaie S","Mahmoodpoor A","et al."],"date":"2024-11-29","year":2024,"doi":"10.1186/s40001-024-02167-x","pmcid":"PMC11607820","license":"cc by-nc-nd","oa":true,"cited_by":20,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Moreover, the evidence supporting the efficacy of proposed interventions remains limited and subject to controversy in terms of safety, efficacy, and optimal protocol. This review provides a comprehensive insight into cancer…","kw":"Cancer treatment-associated xerostomia Cancer-related salivary dysfunction Head and neck cancer Muscarinic agonists Palliative care Radiotherapy Humans Antineop"},{"pmid":"39611899","title_fr":"Laser, Kinesio taping et endermologie dans le lymphœdème après mastectomie : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Le laser et l'endermologie réduisent mieux le volume du bras que la thérapie conventionnelle, sans différence sur la circonférence ni la douleur.","l2":"Méta-analyse de 18 essais randomisés, de bonne qualité selon l'outil Cochrane, comparant le laser basse énergie, le Kinesio taping et l'endermologie à la prise en charge conventionnelle du lymphœdème après mastectomie.\n\nRéduction du volume du bras plus importante avec le laser (DM 91,98 mL ; IC 41,99–141,97) et l'endermologie (DM 34,61 mL), ainsi que pour l'ensemble des interventions (DM 76,27 mL). Pas de différence sur la circonférence du bras ni sur la douleur.","l3":{"points":["18 essais randomisés.","Effet chiffré en millilitres."],"limites":["Critères discordants : volume amélioré, circonférence non.","Interventions hétérogènes."],"pratique":"Le laser est l'option complémentaire la mieux étayée pour réduire le volume du bras."},"k":18,"em":[],"pre":"","topic":"oncologie-support","title":"The Effication of Low-Level Laser Therapy, Kinesio Taping, and Endermology on Post-Mastectomy Lymphedema: A Systematic Review and Meta-Analysis.","journal":"Asian Pacific journal of cancer prevention : APJCP","journal_abbr":"Asian Pac J Cancer Prev","authors":["Wahid DI","Wahyono RA","Setiaji K","et al."],"date":"2024-11-01","year":2024,"week":"2024-S44","doi":"10.31557/APJCP.2024.25.11.3771","pmcid":"PMC11996114","license":"cc by-nc","oa":true,"pdf":"pdfs/39611899.pdf","cited_by":5,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":2,"abstract":[{"label":"BACKGROUND","text":"Post-mastectomy lymphedema is a common complication following breast cancer surgery, characterized by the accumulation of lymphatic fluid, causing swelling, discomfort, and functional limitations in the affected arm. Traditional treatments for lymphedema include manual lymphatic drainage and compression garments, but their effectiveness is variable, and many patients do not achieve satisfactory outcomes. Emerging therapeutic modalities such as Low-Level Laser Therapy (LLLT), Kinesio Taping, and Endermology offer potential non-invasive treatment alternatives. However, the relative efficacy of these approaches in reducing lymphedema, improving limb function, and enhancing quality of life in post-mastectomy patients remains unclear."},{"label":"OBJECTIVE","text":"This study aims to determine the effects of low-level laser therapy, kinesio taping, and endermology on breast cancer patients post-mastectomy with lymphedema."},{"label":"METHODS","text":"A systematic review and meta-analysis were conducted based on PRISMA guidelines. Searches were carried out in databases using keywords. Inclusion and exclusion criteria were applied to select the studies to be included. The selected studies were critically appraised using Cochrane's critical appraisal tool. The chosen studies were extracted and analysed both qualitatively and quantitatively. Quantitative analysis was performed using both fixed-effects and random-effects approaches."},{"label":"RESULTS","text":"Eighteen studies were included in this analysis. All studies were randomized trials with good quality based on critical appraisal. The analysis found a significantly greater reduction in arm volume in the combined intervention group (MD = 76.27; 95% CI = 33.84-118.69) and in each therapy group: low-level laser therapy (MD = 91.98; 95% CI = 41.99-141.97) and endermology (MD = 34.61; 95% CI = 20.81-48.41). However, there were no significant differences in the reduction of arm circumference or pain scale, either overall or for each therapy individually."},{"label":"CONCLUSION","text":"Low-level laser therapy and endermology provide better outcomes for breast cancer patients with post-mastectomy lymphedema compared to conventional therapy."}],"keywords":["Endermology","Kinesio Taping","Low-Level Laser Therapy","Post-mastectomy lymphedema","systematic review and meta-Analysis"]},{"pmid":"39664992","title":"Comparative efficacy of non-pharmacological interventions on xerostomia and salivary flow rate among haemodialysis patients: A systematic review and network meta-analysis.","journal_abbr":"Clin Kidney J","authors":["Sharifnia AM","Chu G","Zhang X","et al."],"date":"2024-10-26","year":2024,"doi":"10.1093/ckj/sfae334","pmcid":"PMC11631358","license":"cc by-nc","oa":true,"cited_by":4,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Several non-pharmacological interventions have demonstrated effectiveness in relieving xerostomia and enhancing saliva flow rate. While further research may be needed to confirm and refine these findings, the interventions used in this…","kw":"chronic kidney disease non-pharmacological intervention salivary flow rate systematic review xerostomia"},{"pmid":"39422592","title":"Underexplored Areas of Photobiomodulation in Oral Oncology: An Expert Analysis.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Gueiros LA","Gobbo M","Santos-Silva AR","et al."],"date":"2024-10-18","year":2024,"doi":"10.1089/photob.2023.0155","cited_by":3,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus","xérostomie"],"l1":"However, the primary studies are often small and may have biases that require further evaluation, particularly regarding treatment safety. Conclusion: Despite the overall positive impression of PBM therapy for oral adverse events of…","kw":"dysgeusia odynophagia oral mucositis photobiomodulation trismus xerostomia Humans Low-Level Light Therapy Trismus Mouth Neoplasms Xerostomia Stomatitis"},{"pmid":"39417951","title":"The effect of compression therapies and therapeutic modalities on lymphedema secondary to cancer: a rapid review and evidence map.","journal_abbr":"Med Oncol","authors":["McNeely ML","Shallwani SM","Al Onazi MM","et al."],"date":"2024-10-17","year":2024,"doi":"10.1007/s12032-024-02447-w","pmcid":"PMC11486789","license":"cc by","oa":true,"cited_by":11,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Evidence mapping suggests potential for benefit from (1) compression garments for the prevention of lymphedema, (2) interventions added to CDT in the intensive reduction phase, and (3) nighttime compression and compression pump treatments…","kw":"Cancer Compression pumps Compression therapies Extracorporeal shockwave therapy Low-level laser therapy Lymphedema Humans Lymphedema Compression Bandages Neopla"},{"pmid":"39439950","title":"Reviewing the efficiency of photobiomodulation therapy in oncological treatment.","journal_abbr":"Front Oncol","authors":["Luitel B","Duggisani T","Luitel A","et al."],"date":"2024-10-08","year":2024,"doi":"10.3389/fonc.2024.1447653","pmcid":"PMC11493773","license":"cc by","oa":true,"pdf":"pdfs/39439950.pdf","cited_by":4,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Both modalities mitigated treatment side effects like oral mucositis, xerostomia, peripheral neuropathy, and improved quality of life. While promising, the outcomes varied based on light parameters, cancer type, and experimental setting,…","kw":"low level light therapy (LLLT) oncology photobiomoduation photobiomodulation therapy radiation therapy"},{"pmid":"39449921","title":"Optimizing the Synergistic Role of Diode Laser and Drug Therapies in the Management of Oral Submucous Fibrosis: A Case Report.","journal_abbr":"Cureus","authors":["Varma S","Karambelkar MV","Suragimath G","et al."],"date":"2024-09-23","year":2024,"doi":"10.7759/cureus.70028","pmcid":"PMC11499076","license":"cc by","oa":true,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"Photobiomodulation (PBM) is an emerging minimally invasive therapy that can be utilized to treat OSMF through its anti-inflammatory and analgesic effects. With the advent of dual-wavelength diode lasers, the current case report focuses on…","kw":"areca nut diode laser therapy osmf pbm smokeless tobacco(st)"},{"pmid":"39150379","title":"The Mechanism of 540 nm Green Light in Promoting Salivary Secretion.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Qi W","Min SN","Mao XD","et al."],"date":"2024-08-16","year":2024,"doi":"10.1089/photob.2024.0054","cited_by":1,"curated":false,"type":"preclinical","level":5,"ctx":["xérostomie"],"nm":[540],"pre":"vivo","l1":"Through in-depth bioinformatics analysis and expression verification, ERK1/2 and EphA2 served as potential canonical and noncanonical signals underlying 540 nm green light. Conclusions: Our findings uncovered the novel therapeutic effects…","kw":"green light low level laser therapy salivary secretion tight junction xerostomia Animals Mice Low-Level Light Therapy Submandibular Gland Saliva Xerostomia"},{"pmid":"39061982","title":"Efficacy of Photobiomodulation Therapy in Older Adults: A Systematic Review.","journal_abbr":"Biomedicines","authors":["Godaert L","Dramé M"],"date":"2024-06-25","year":2024,"doi":"10.3390/biomedicines12071409","pmcid":"PMC11274037","license":"cc by","oa":true,"cited_by":7,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"em":["pulse"],"l1":"PBMT appears to be a promising complementary treatment. All studies reported good compliance and safety throughout the treatment. In the future, it will be essential to harmonize PBMT parameters. Further studies are warranted to define…","kw":"complementary treatment efficacy older adults photobiomodulation therapy"},{"pmid":"38885236","title":"Assessment of the pre-emptive effect of photobiomodulation in the postoperative period of impacted lower third molar extractions: A randomized, controlled, double-blind study protocol.","journal_abbr":"PLoS One","authors":["Salaberry DR","Bruno LH","Cirisola RWC","et al."],"date":"2024-06-17","year":2024,"doi":"10.1371/journal.pone.0300136","pmcid":"PMC11182519","license":"cc by","oa":true,"cited_by":3,"pub_types":["Clinical Trial Protocol","Research Support, Non-U.S. Gov't"],"curated":false,"type":"protocol","level":0,"ctx":[],"l1":"Adverse effects will be recorded. Data will be presented as means ± SD and a p-value < 0.05 will be indicative of statistical significance.","kw":"Humans Molar, Third Tooth Extraction Low-Level Light Therapy Tooth, Impacted Double-Blind Method"},{"pmid":"40741271","title":"Impact of low-level laser therapy on upper limb lymphoedema secondary to breast cancer: a systematic review and meta-analysis.","journal_abbr":"Arch Med Sci","authors":["Hussein HM","Gabr AMM","Fadulelmulla IA","et al."],"date":"2024-05-13","year":2024,"doi":"10.5114/aoms/186874","pmcid":"PMC12305524","license":"cc by-nc-sa","oa":true,"cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"This review revealed that low-level laser therapy (photobiostimulation) was successful in reducing arm circumference, volume, and pain, as well as enhancing grip strength, life quality, and mobility. However, the meta-analysis did not…","kw":"breast cancer function laser therapy lymphoedema pain"},{"pmid":"38791010","title":"Burning Mouth Syndrome Treated with Low-Level Laser and Clonazepam: A Randomized, Single-Blind Clinical Trial.","journal_abbr":"Biomedicines","authors":["Garcia Martinez A","Lopez-Jornet P","Pardo Marin L","et al."],"date":"2024-05-09","year":2024,"doi":"10.3390/biomedicines12051048","pmcid":"PMC11118462","license":"cc by","oa":true,"cited_by":8,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"The low-level diode laser is a good treatment option in BMS, resulting in a decrease in patient symptoms and in salivary biomarkers. However, standardization of the intervention protocols and laser intensity parameters is needed in order…","kw":"burning mouth syndrome clonazepam interleukins low-level light therapy saliva"},{"pmid":"38657999","title":"Photobiomodulation in the treatment of palmar-plantar erythrodysesthesia: a randomised controlled clinical study protocol.","journal_abbr":"BMJ Open","authors":["Lestido V","Rodríguez F","Rodríguez A","et al."],"date":"2024-04-23","year":2024,"doi":"10.1136/bmjopen-2023-081459","pmcid":"PMC11043708","license":"cc by-nc","oa":true,"cited_by":2,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["main-pied"],"nm":[630],"l1":"V.2, 27 October 2023. ClinicalTrials.gov Registry (NCT05337423).","kw":"Adverse events CHEMOTHERAPY Quality of Life Humans Double-Blind Method Hand-Foot Syndrome Low-Level Light Therapy Randomized Controlled Trials as Topic Fluorour"},{"pmid":"38655042","title":"Evaluation of the Effect of Photobiomodulation on Radiation-Induced Xerostomia in Head and Neck Cancer Patients: A Randomized Clinical Trial.","journal_abbr":"J Lasers Med Sci","authors":["Mosannen Mozaffari P","Delavarian Z","Fekrazad R","et al."],"date":"2024-04-07","year":2024,"doi":"10.34172/jlms.2024.04","pmcid":"PMC11033859","cited_by":4,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[810],"em":["cw"],"l1":"Conclusion: In the present study, PBM had a preventive effect on stimulated saliva and subjective xerostomia and can be recommended as an adjunctive treatment. Further studies with a higher sample size and the use of a low-level laser in…","kw":"Head and neck cancer Hyposalivation Low-level laser Photobiomodulation Xerostomia"},{"pmid":"38608541","title_fr":"PBM et hyposialie induite par les antihypertenseurs : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[808],"n":41,"effect":"favorable","theme":"Xérostomie","l1":"Dans l'hyposialie due aux antihypertenseurs, la PBM à 808 nm (4 J par site, hebdomadaire) augmente le débit salivaire de 75 %.","l2":"Essai randomisé en aveugle contre placebo, 41 patients.","l3":{"points":["Xérostomie médicamenteuse."],"limites":["Un seul centre."],"pratique":"Option hors cancer."},"em":[],"pre":"","topic":"oncologie-support","title":"Evaluation of photobiomodulation in the salivary production of patients with hyposalivation induced by antihypertensive drugs - A blind, randomized, controlled clinical trial.","journal":"Complementary therapies in clinical practice","journal_abbr":"Complement Ther Clin Pract","authors":["Varellis MLZ","Bussadori SK","Pavesi VCS","et al."],"date":"2024-03-22","year":2024,"week":"2024-S12","doi":"10.1016/j.ctcp.2024.101845","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Arterial hypertension is a systemic condition that affects about 35% of the world population. The drugs that are used for its control can produce hyposalivation. This work evaluated the effect of photobiomodulation on salivary flow rate, salivary pH, total protein concentration, and calcium concentration in individuals using antihypertensive medications."},{"label":"MATERIAL AND METHODS","text":"41 subjects were randomly allocated in one of two groups: control (placebo) and photobiomodulation. The subjects had their salivary glands (20 sites) irradiated with a laser emitting at 808 nm, 4J/site once a week for 4 weeks and had their salivary flow measured before and after the whole treatment."},{"label":"RESULTS","text":"The intragroup analysis (before and after treatment) shows a significant difference for both non-stimulated and stimulated salivary flow in the photobiomodulation group (p = 0.0007 and p = 0.0001, respectively). Comparing the placebo with the photobiomodulation group, significant differences were found for both non-stimulated (p = 0.0441) and stimulated salivary flow (p = 0.0441) after the treatment. No significant differences were found in pH, total protein concentration, calcium concentration."},{"label":"CONCLUSION","text":"Despite the usage of drugs that influence the nervous system and typically result in a reduction of saliva production, photobiomodulation demonstrated a remarkable ability to enhance saliva production by a significant 75%."}],"keywords":["Antihypertensive drugs","Hypertension","Hyposalivation","LLLT","Laser","Photobiomodulation","Salivary gland","Xerostomy"]},{"pmid":"42206120","title":"The Effectiveness of Photobiomodulation Using 940-nm Diode Laser for Reducing Pain, Swelling and Trismus After Third Molar Surgery: A Single-Blinded Randomized Control Trial.","journal_abbr":"J Maxillofac Oral Surg","authors":["Pathak R","Kale TP","Pattar V","et al."],"date":"2024-02-04","year":2024,"doi":"10.1007/s12663-023-02104-1","pmcid":"PMC13201785","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[940],"l1":"Photobiomodulation is a promising modality to reduce the post-operative pain and trismus. Patients in the study group returned to normal function sooner than the control group. Photobiomodulation is a newer non-invasive modality to reduce…","kw":"Impacted Low-level light therapy Molar Quality of life Third Tooth"},{"pmid":"38267245","title":"Efficacy of photobiomodulation therapy combined with mobile health education in patients with head and neck cancer suffering from chronic xerostomia after radiotherapy: protocol for a three-arm, randomised, placebo-controlled, double-blinded study.","journal_abbr":"BMJ Open","authors":["Lopez-Garzon M","López-Fernández MD","Ruíz-Martínez AM","et al."],"date":"2024-01-24","year":2024,"doi":"10.1136/bmjopen-2023-078068","pmcid":"PMC10824058","license":"cc by-nc","oa":true,"cited_by":5,"pub_types":["Clinical Trial Protocol","Research Support, Non-U.S. Gov't"],"curated":false,"type":"protocol","level":0,"ctx":["xérostomie"],"l1":"The results of this study will be presented at national and international conferences and published in peer-reviewed journals. ClinicalTrials.gov NCT05106608.","kw":"Head & neck tumours Laser therapy Physical Therapy Modalities Quality of Life Rehabilitation medicine Telemedicine Humans Low-Level Light Therapy Quality of Lif"},{"pmid":"38244087","title_fr":"Laser basse énergie et qualité de vie dans la xérostomie de la radiothérapie ORL : revue","type":"sr","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":126,"effect":"favorable","theme":"Xérostomie","l1":"Le laser améliore la sensation de bouche sèche et le débit salivaire, et donc la qualité de vie des patients irradiés pour un cancer ORL.","l2":"Revue systématique (Embase, Medline, Cochrane, Scopus, Web of Science, LILACS, clinicaltrials.gov ; RoB 2.0 et ROBINS-I) sur le laser basse énergie et la qualité de vie des patients souffrant de xérostomie après radiothérapie ORL.\n\nQuatre études de 2014 à 2023, 126 patients : trois essais randomisés (dont un pilote) et un essai prospectif. Toutes utilisent l'infrarouge, deux y associent le rouge. La sensation de bouche sèche diminue, les débits salivaires stimulé et non stimulé augmentent, la qualité de vie s'améliore.","l3":{"points":["Critère centré sur le patient : la qualité de vie."],"limites":["Quatre études, 126 patients ; une étude non randomisée."],"pratique":"Piste sérieuse pour la bouche sèche après radiothérapie, à confirmer par des essais plus grands."},"k":4,"em":[],"pre":"","topic":"oncologie-support","title":"Impact of low-level laser therapy on the quality of life of patients with xerostomia undergoing head and neck radiotherapy: a systematic review.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Ribeiro LN","de Vasconcelos Carvalho M","de Oliveira Limirio JPJ","et al."],"date":"2024-01-20","year":2024,"week":"2024-S03","doi":"10.1007/s00520-024-08325-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"PURPOSE","text":"To carry out a systematic review to assess whether low-level laser therapy can improve the quality of life of patients with xerostomia undergoing head and neck radiotherapy."},{"label":"METHODS","text":"A systematic search was performed through Embase, Medline/PubMed, Cochrane, Scopus, Web of Science, nonpeer-reviewed clinicaltrials.gov and LILACS. The strategy included clinical studies were selected that prospectively followed or evaluated the quality of life by directly comparing the use of low-level laser therapy for xerostomia induced by head and neck radiotherapy with alternative therapies without the use of a laser. The risk of bias in the studies was assessed by RoB 2.0 and Robins I."},{"label":"RESULTS","text":"After all application of the predetermined criteria, four studies were included, dated between the years 2014 and 2023. Three studies described as randomized clinical trials were included, one of which was a randomized pilot study and only one was a prospective clinical trial. A total of 126 patients were evaluated, all four studies used the infrared wavelength, with two studies using the combination with the red wavelength. It was observed that low-level laser therapy can change the sensation of dry mouth, improving patients' quality of life. In addition, changes related to increased stimulated and unstimulated salivary flow were also identified."},{"label":"CONCLUSION","text":"The use of low-level laser therapy has promising results on xerostomia, consequently improving the quality of life of patients undergoing radiotherapy in the head and neck region."}],"keywords":["Head and neck cancer","Low-level laser therapy","Quality of life","Radiotherapy","Saliva","Xerostomia"]},{"pmid":"38189964","title_fr":"PBM des glandes salivaires : revue narrative et méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[630,830],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"Les paramètres les plus prometteurs sont 630–830 nm, 2 à 10 J/cm², 2 à 3 fois par semaine, dès avant les lésions radiques, sur l'ensemble des glandes ; les LED couvrant de grandes surfaces sont intéressantes.","l2":"Revue narrative et méta-analyse.","l3":{"points":["Repères de dose précis."],"limites":["Études hétérogènes."],"pratique":"Référence pratique."},"em":[],"pre":"","topic":"oncologie-support","title":"The supportive use of photobiomodulation on salivary glands: a narrative review and meta-analysis.","journal":"European archives of oto-rhino-laryngology : official journal of the European Federation of Oto-Rhino-Laryngological Societies (EUFOS) : affiliated with the German Society for Oto-Rhino-Laryngology - Head and Neck Surgery","journal_abbr":"Eur Arch Otorhinolaryngol","authors":["Oliveira SV","Batista JVF","Gutierres GG","et al."],"date":"2024-01-08","year":2024,"week":"2024-S02","doi":"10.1007/s00405-023-08425-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Meta-Analysis","Review"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Radiotherapy is one of the main strategies used in the treatment of cancer patients and it can cause early or late xerostomia and/or hyposalivation. Therapeutic management of xerostomia includes oral hygiene, sialogenic agents among others."},{"label":"METHODS","text":"This study reviews the use of extra-oral salivary glands photobiomodulation in treating xerostomia and/or hyposalivation after radiotherapy and performs a meta-analysis of this data."},{"label":"RESULTS","text":"After a broad search of the literature, eight clinical studies were selected."},{"label":"DISCUSSION","text":"In a safe way, the studies found that extra-oral stimulation of the salivary glands has benefits in the hyposalivation and changes in salivary flow resulting from lesions by radiotherapy. A meta-analysis found significant values in pain comparing the pre- and post-treatment moments (MD - 3.02, I2 95%, IC - 5.56; - 0.48) and for stimulated salivary flow at 30 days after the end of radiotherapy (MD 2.90, I2 95%, IC 1.96; 3.84)."},{"label":"CONCLUSION","text":"The most promising parameters comprise wavelengths between 630 and 830 nm, radiant exposure from 2 to 10 J/cm2, two-to-three times a week, before the radiotherapy damage, and homogeneously in the glands. Therefore, Light-Emitting Diode (LED) stimulation of larger areas than the punctual stimulation of small millimeters of the Low-Level Laser Therapy (LLLT) appears to be promising."}],"keywords":["Cancer","Hyposalivation","Photobiomodulation","Radiotherapy","Xerostomia"]},{"pmid":"38129368","title_fr":"Schémas de PBM dans le lymphœdème lié au cancer du sein : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Dans le lymphœdème lié au cancer du sein, une fréquence de séances plus élevée, une densité adaptée et une cure plus longue donnent de meilleurs résultats.","l2":"Revue systématique avec méta-analyse.","l3":{"points":["Repères de schéma thérapeutique."],"limites":["Suivis courts."],"pratique":"Préférer des cures longues et rapprochées."},"em":[],"pre":"","topic":"oncologie-support","title":"Effect of various photobiomodulation regimens on breast cancer-related lymphedema: A systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Chiu ST","Lai UH","Huang YC","et al."],"date":"2023-12-21","year":2023,"week":"2023-S51","doi":"10.1007/s10103-023-03959-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Breast cancer-related lymphedema (BCRL) is common among patients who have completed their cancer treatment. Although low-level laser therapy (LLLT) has been explored as a treatment option for BCRL, we could not find a regimen that is more effective than others. This meta-analysis aimed to organize existing research and determine the optimal combination of LLLT parameters for BCRL treatment. Studies were collected from four online databases: Embase, Ovid Medline, Cochrane, and Cinahl. The collected studies were reviewed by two of the authors. We focused on the aspects of the treatment area, treatment regimen, and total treatment sessions across the included studies. The comparisons between LLLT and non-LLLT were performed through a meta-analysis. Post-treatment QOL was significantly better in the axillary group. The group treated \"three times/week with a laser density of 1.5-2 J/cm2\" had significantly better outcomes in terms of swelling reduction, both immediately post-treatment and at 1-3 months follow-ups. The group with > 15 treatment sessions had significantly better post-treatment outcomes regarding reduced swelling and improved grip strength. According to these results, LLLT can relieve the symptoms of BCRL by reducing limb swelling and improving QOL. Further exploration found that a treatment approach targeting the axilla, combined with an increased treatment frequency, appropriate laser density, and extended treatment course, yielded better outcomes. However, further rigorous, large-scale studies, including long-term follow-up, are needed to substantiate this regimen."}],"keywords":["Low intensity laser","Low power laser","Lymphoedema","Mammary neoplasm","Photobiomodulation","Postmastectomy"]},{"pmid":"38117359","title":"The Photobiomodulation effect of 980 nm Diode Laser on Patients with Xerostomia.","journal_abbr":"Lasers Med Sci","authors":["Derikvand N","Basirat M","Ghasemi SS","et al."],"date":"2023-12-20","year":2023,"doi":"10.1007/s10103-023-03949-1","cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[980],"l1":"In this study, the volume and weight of the unstimulated saliva in most patients with xerostomia increased with using PBM.","kw":"980 nm diode laser Photobiomodulation Saliva Xerostomia Humans Lasers, Semiconductor Low-Level Light Therapy Xerostomia Saliva Hypertension"},{"pmid":"38218654","title":"Evaluation of photobiomodulation therapy (PBMT) on salivary flow and composition in head and neck cancer patients undergoing radiation therapy.","journal_abbr":"Oral Surg Oral Med Oral Pathol Oral Radiol","authors":["Schepanski N","Costa FS","Machado EFM","et al."],"date":"2023-11-23","year":2023,"doi":"10.1016/j.oooo.2023.11.007","cited_by":2,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"l1":"PBMT prevented a significant reduction in SFR and xerostomia induced by radiation therapy. These findings suggest that PBMT prevents salivary gland damage minimizing the decline in salivary flow.","kw":"Humans Middle Aged Low-Level Light Therapy Parotid Gland Salivary Glands Xerostomia"},{"pmid":"37946598","title_fr":"Interventions non médicamenteuses contre la bouche sèche radio-induite : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Contre la bouche sèche radio-induite, certaines salives artificielles et la TENS sont les plus prometteuses ; les données sur la PBM restent hétérogènes.","l2":"Revue systématique d'essais randomisés (PROSPERO).","l3":{"points":["Comparaison large."],"limites":["Hétérogénéité."],"pratique":"La PBM n'est pas en tête."},"em":[],"pre":"","topic":"oncologie-support","title":"Non-pharmacologic interventions for management of radiation-induced dry mouth: A systematic review.","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Khamdi S","Matangkasombut O","Lam-Ubol A"],"date":"2023-11-09","year":2023,"week":"2023-S45","doi":"10.1111/odi.14804","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":7,"pub_types":["Systematic Review","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"Radiation-induced dry mouth negatively impacts patients' oral health and quality of life. Currently, evidence-based recommendation for non-pharmacologic interventions is still lacking. This study aimed to systematically review clinical trials evaluating the efficacy of non-pharmacologic interventions in cancer patients with radiation-induced dry mouth."},{"label":"METHODS","text":"Randomized controlled trials from 2000 were searched from 4 databases, including MEDLINE, Cochrane, Embase via OVID, and SCOPUS, up to December 16th, 2022 (PROSPERO registration CRD42022378405). The risk of bias was assessed using the revised Cochrane risk of bias assessment tool."},{"label":"RESULTS","text":"Twenty-one studies were included: 11 on artificial saliva, 4 on electrical nerve stimulation (TENS), 2 on acupuncture, and one study each on low-level laser therapy, stem cells, chewing gum, and probiotics. Overall bias was low, medium, and high in 33%, 48%, and 19% of the studies, respectively. Certain artificial saliva products and TENS were shown to improve dry mouth symptoms and salivary flow rate (SFR). One study showed that stem cell transplantation significantly increased SFR."},{"label":"CONCLUSIONS","text":"The evidence suggested that certain artificial saliva products and TENS are promising management. However, the evidence was still limited due to heterogeneity of interventions and outcome measurements. Thus, future studies using standard measurements and long-term follow-up are warranted."}],"keywords":["dry mouth","hyposalivation","management","non‐pharmacologic","radiotherapy","xerostomia"]},{"pmid":"37935876","title":"Photobiomodulation therapy in the treatment of radiotherapy-related trismus of the head and neck.","journal_abbr":"Lasers Med Sci","authors":["Borges MMF","Malta CEN","Carlos ACAM","et al."],"date":"2023-11-07","year":2023,"doi":"10.1007/s10103-023-03920-0","cited_by":11,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[808],"l1":"PBMT controls muscular pain and reduced mouth opening limitation in HNC during radiotherapy. Further studies are needed to evaluate the preventive capacity of PBMT protocols for RT trismus-related HNC.","kw":"Head and neck cancer Low-level light therapy Radiotherapy Trismus Male Humans Female Trismus Low-Level Light Therapy Head and Neck Neoplasms"},{"pmid":"37858427","title":"[Photobiomodulation in the prevention and the management of side effects of cancer treatments: Bases, results and perspectives].","journal_abbr":"Bull Cancer","authors":["Lairedj K","Klausner G","Robijns J","et al."],"date":"2023-10-17","year":2023,"doi":"10.1016/j.bulcan.2023.08.011","cited_by":3,"pub_types":["English Abstract","Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Published data suggest that PBM could therefore be considered as supportive care in its own right for patients treated with radiation, chemotherapy, immunotherapy, hormone therapy or targeted therapies, whether in clinical practice or…","kw":"Chemotherapy Effets secondaires des anticancéreux Low-level light therapy Mucite Neoplasms Neuropathies périphériques post-chimiothérapie Humans Low-Level Light"},{"pmid":"37480103","title":"A scoping review on hyposalivation associated with systemic conditions: the role of physical stimulation in the treatment approaches.","journal_abbr":"BMC Oral Health","authors":["Melo JLMA","Coelho CPES","Nunes FPES","et al."],"date":"2023-07-21","year":2023,"doi":"10.1186/s12903-023-03192-8","pmcid":"PMC10360219","license":"cc by","oa":true,"cited_by":12,"pub_types":["Research Support, Non-U.S. Gov't","Scoping Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Among the different patient groups, individuals with Sjögren's syndrome (SS) exhibited the poorest responses, while those with medication-induced hyposalivation demonstrated the most favorable treatment outcomes, independently of the…","kw":"Acupuncture Autoimmune disease Hyposalivation Low power laser Salivary stimulation Transcutaneous electrical nerve stimulation Humans Female Sjogren's Syndrome "},{"pmid":"37401988","title":"Editorial Expression of Concern: The effectiveness and safety of low‑level laser therapy on breast cancer-related lymphedema: An overview and update of systematic reviews.","journal_abbr":"Lasers Med Sci","authors":["Wang Y","Ge Y","Xing W","et al."],"date":"2023-07-04","year":2023,"doi":"10.1007/s10103-023-03815-0","pmcid":"PMC10319684","license":"cc by","oa":true,"pub_types":["Expression of Concern"],"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"","kw":""},{"pmid":"37382963","title_fr":"Rééducation du lymphœdème des cancers ORL : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Dans le lymphœdème des cancers ORL, les interventions de rééducation semblent sûres et bénéfiques ; les données sur la PBM restent limitées.","l2":"Revue systématique (JAMA Otolaryngol Head Neck Surg).","l3":{"points":["Lymphœdème cervico-facial."],"limites":["Peu d'essais contrôlés."],"pratique":"À préciser."},"em":[],"pre":"","topic":"oncologie-support","title":"Rehabilitation Interventions for Head and Neck Cancer-Associated Lymphedema: A Systematic Review.","journal":"JAMA otolaryngology-- head & neck surgery","journal_abbr":"JAMA Otolaryngol Head Neck Surg","authors":["Cheng JT","Leite VF","Tennison JM","et al."],"date":"2023-06-29","year":2023,"week":"2023-S26","doi":"10.1001/jamaoto.2023.1473","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"IMPORTANCE","text":"Head and neck cancer-associated lymphedema (HNCaL) affects up to 90% of survivors of head and neck cancer and is a substantial contributor to disability following head and neck cancer treatment. Despite the prevalence and morbidity associated with HNCaL, rehabilitation interventions are not well studied."},{"label":"OBJECTIVE","text":"To identify and appraise the current evidence for rehabilitation interventions in HNCaL."},{"label":"EVIDENCE REVIEW","text":"Five electronic databases were searched systematically from inception to January 3, 2023, for studies on HNCaL rehabilitation interventions. Study screening, data extraction, quality rating, and risk of bias assessment were performed by 2 independent reviewers."},{"label":"FINDINGS","text":"Of 1642 citations identified, 23 studies (1.4%; n = 2147 patients) were eligible for inclusion. Six studies (26.1%) were randomized clinical trials (RCTs) and 17 (73.9%) were observational studies. Five of the 6 RCTs were published during 2020 to 2022. Most studies had fewer than 50 participants (5 of 6 RCTs; 13 of 17 observational studies). Studies were categorized by intervention type, including standard lymphedema therapy (11 studies [47.8%]) and adjunct therapy (12 studies [52.2%]). Lymphedema therapy interventions included standard complete decongestive therapy (CDT) (2 RCTs, 5 observational studies), modified CDT (3 observational studies), therapy setting (1 RCT, 2 observational studies), adherence (2 observational studies), early manual lymphatic drainage (1 RCT), and inclusion of focused exercise (1 RCT). Adjunct therapy interventions included advanced pneumatic compression devices (APCDs) (1 RCT, 5 observational studies), kinesio taping (1 RCT), photobiomodulation (1 observational study), acupuncture/moxibustion (1 observational study), and sodium selenite (1 RCT, 2 observational studies). Serious adverse events were either not found (9 [39.1%]) or not reported (14 [60.9%]). Low-quality evidence suggested the benefit of standard lymphedema therapy, particularly in the outpatient setting and with at least partial adherence. High-quality evidence was found for adjunct therapy with kinesio taping. Low-quality evidence also suggested that APCDs may be beneficial."},{"label":"CONCLUSIONS AND RELEVANCE","text":"The results of this systematic review suggest that rehabilitation interventions for HNCaL, including standard lymphedema therapy with kinesio taping and APCDs, appear to be safe and beneficial. However, more prospective, controlled, and adequately powered studies are needed to clarify the ideal type, timing, duration, and intensity of lymphedema therapy components before treatment guidelines can be established."}],"keywords":[]},{"pmid":"37366663","title":"Treatments of COVID-19-Associated Taste and Saliva Secretory Disorders.","journal_abbr":"Dent J (Basel)","authors":["Tsuchiya H"],"date":"2023-05-25","year":2023,"doi":"10.3390/dj11060140","pmcid":"PMC10297082","license":"cc by","oa":true,"cited_by":8,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"An understanding of currently available treatment options is required for dental professionals because they may treat patients who were infected with SARS-CoV-2 or who recovered from COVID-19, and become aware of their abnormal taste and…","kw":"COVID-19 pathogenic mechanism saliva secretory disorder taste disorder treatment"},{"pmid":"37205934","title":"Investigation of the effect of Low-Level Laser Therapy on arm lymphedema in breast cancer patients: A noninvasive treatment for an intractable morbidity.","journal_abbr":"Health Sci Rep","authors":["Farhan F","Samei M","Abdshah A","et al."],"date":"2023-05-17","year":2023,"doi":"10.1002/hsr2.1261","pmcid":"PMC10189865","license":"cc by","oa":true,"cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"LLLT can, at least in association with current standard methods, be used for arm lymphedema to introduce further reductions in pain and volume.","kw":"breast cancer low‐level laser lymphedema"},{"pmid":"37116057","title":"Patient Experience of Photobiomodulation Therapy in Head and Neck Chronic Lymphedema.","journal_abbr":"J Palliat Med","authors":["Deng J","Lukens JN","Zhu J","et al."],"date":"2023-04-28","year":2023,"doi":"10.1089/jpm.2021.0419","cited_by":4,"pub_types":["Clinical Trial","Research Support, Non-U.S. Gov't"],"curated":false,"type":"nrct","level":3,"ctx":["lymphœdème"],"l1":"Rigorously designed clinical trials are needed to evaluate the effect of PBM therapy for head and neck cancer-related lymphedema. Trial Registration Number and Date of Registration: ClinicalTrials.gov Identifier: NCT03738332; date of…","kw":"experience head and neck cancer lymphedema photobiomodulation qualitative Humans Chronic Disease Head and Neck Neoplasms Low-Level Light Therapy Lymphedema Pati"},{"pmid":"37103598","title":"Advances in the prevention and treatment of breast cancer-related lymphedema.","journal_abbr":"Breast Cancer Res Treat","authors":["Donahue PMC","MacKenzie A","Filipovic A","et al."],"date":"2023-04-27","year":2023,"doi":"10.1007/s10549-023-06947-7","pmcid":"PMC10224871","license":"cc by","oa":true,"cited_by":98,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Progress in prevention and treatment of BCRL continues, requiring advances in early diagnosis, patient education, expert consensus and novel treatments designed for lymphatic rehabilitation following insults.","kw":"Breast cancer Breast cancer lymphedema Indocyanine green Lymphedema Manual lymphatic drainage Optical imaging Humans Female Breast Neoplasms Breast Cancer Lymph"},{"pmid":"37060370","title_fr":"PBM contre la xérostomie et la mucite des cancers ORL : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":53,"effect":"favorable","theme":"Xérostomie","l1":"Pendant la radiothérapie ORL, la PBM améliore la qualité de vie, avec un effet sur la xérostomie et la mucite.","l2":"Essai randomisé contre sham, 53 patients.","l3":{"points":["Qualité de vie."],"limites":["Un seul centre."],"pratique":"Option de soins de support."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation for the management of xerostomia and oral mucositis in patients with cancer: a randomized clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Carvalho E Silva RM","Mendes FM","Degasperi GR","et al."],"date":"2023-04-15","year":2023,"week":"2023-S15","doi":"10.1007/s10103-023-03760-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To evaluate the applicability of photobiomodulation therapy (PBM-T) in the management of xerostomia and OM. Fifty-three patients with head and neck squamous cell carcinoma were randomized into two groups: Sham and PBM-T. The Sham group received artificial saliva and laser simulation, while the PBM-T group received artificial saliva and PBM-T. Xerostomia-related quality of life (QoL), the presence or absence of OM lesions, the decayed-missing-filled teeth (DMFT) index, and periodontal charts were evaluated. The results of the QoL questionnaire, DMFT index, and periodontal chart were analyzed with the Kruskal-Wallis test, followed by the Student-Newman-Keuls test, while OM findings were compared using the Mann-Whitney test. QoL scores significantly increased in the Sham group (p < 0.0001), denoting more severe xerostomia symptoms (p = 0.0074), and decreased in the PBM-T group, indicating no or very mild xerostomia. Higher grades of OM were found in the Sham group than the PBM-T group (p = 0.0001). There was no significant difference in DMFT index or periodontal charts between the groups (p > 0.05). PBM-T improved QoL in patients with head and neck cancer treated with radiotherapy, whether as radiation alone or as an adjunct to chemotherapy and surgery."}],"keywords":["Cancer","Chemotherapy","Oral mucositis","Photobiomodulation","Radiotherapy","Xerostomia"]},{"pmid":"37025573","title":"Comments to \"The Randomized Controlled Study of Low-Level Laser Therapy, Kinesio-Taping and Manual Lymphatic Drainage in Patients With Stage II Breast Cancer-Related Lymphedema\".","journal_abbr":"Eur J Breast Health","authors":["Bergmann A","Andrade MFC","Dias M"],"date":"2023-04-01","year":2023,"doi":"10.4274/ejbh.galenos.2023.2023-1-2","pmcid":"PMC10071891","curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"","kw":""},{"pmid":"36820144","title":"Low-level laser and management of common complications after the mandibular third molar surgery: A double-blind randomized clinical trial.","journal_abbr":"Dent Res J (Isfahan)","authors":["Sigaroodi AK","Motevasseli S","Maleki D","et al."],"date":"2023-01-18","year":2023,"pmcid":"PMC9937931","license":"cc by-nc-sa","oa":true,"cited_by":8,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[808],"l1":"Our findings showed that the LLLT had beneficial effects on the management of pain, edema, and trismus following after 3rd molar extraction surgery.","kw":"Edema low-level laser therapy pain third molar trismus"},{"pmid":"36605467","title":"The Randomized Controlled Study of Low-Level Laser Therapy, Kinesio-Taping and Manual Lymphatic Drainage in Patients With Stage II Breast Cancer-Related Lymphedema.","journal_abbr":"Eur J Breast Health","authors":["Selcuk Yilmaz S","Ayhan FF"],"date":"2023-01-01","year":2023,"doi":"10.4274/ejbh.galenos.2022.2022-6-4","pmcid":"PMC9806938","cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Kinesio-taping led to better results than MLD and was similarly effective compared with low-level laser in stage II breast cancer-related lymphedema at the twelfth week of follow-up. Kinesio-taping and low-level laser should be considered…","kw":"Lymphedema breast cancer complex decongestive treatment kinesio-taping low level laser therapy manual lymphatic drainage"},{"pmid":"36571167","title":"Laser Therapy as a Treatment for Chronic Radiation Fibrosis A Commentary.","journal_abbr":"Lasers Surg Med","authors":["Shumaker PR"],"date":"2022-12-26","year":2022,"doi":"10.1002/lsm.23625","cited_by":1,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"","kw":"CPT codes adnexae dyspigmentation erythema fractional ablative CO2 laser therapy Humans Radiation Fibrosis Syndrome Laser Therapy Low-Level Light Therapy Lasers"},{"pmid":"36538405","title":"[Low-level laser therapy in oncology - what's new? Analysis of 2018-2021 publications].","journal_abbr":"Vopr Kurortol Fizioter Lech Fiz Kult","authors":["Moskvin SV","Strazhev SV"],"date":"2022-12-20","year":2022,"doi":"10.17116/kurort20229906156","pub_types":["English Abstract","Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"The use of only local illumination instead of systemic methods of LLLT does not allow obtaining the best results of treatment and prevention. Eliminating the shortcomings of treatment protocols with a focus on Russian experience, when…","kw":"low-level laser therapy lymphedema mucositis oncology radiodermatitis Humans Acupuncture Therapy Laser Therapy Low-Level Light Therapy Neoplasms Russia"},{"pmid":"36042421","title_fr":"Laser dans le lymphœdème lié au cancer du sein : revue systématique","type":"sr","level":1,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Le laser réduit la circonférence et le volume du bras plus qu'il n'améliore la mobilité de l'épaule et la douleur.","l2":"Revue systématique (PROSPERO CRD42022315076 ; PubMed, PEDro, Medline, Cochrane) des essais randomisés de laser basse énergie dans le lymphœdème après cancer du sein.\n\nLa circonférence et le volume du bras diminuent nettement à quatre semaines, et le bénéfice se maintient au suivi prolongé. En revanche, ni la mobilité de l'épaule ni la douleur ne diffèrent du placebo à 0, 1, 2 et 3 mois.","l3":{"points":["Essais de bonne qualité.","Distingue l'effet sur le volume de l'effet sur la fonction."],"limites":["Peu d'essais, durées courtes."],"pratique":"Attendre un effet sur le volume du bras plutôt que sur la douleur ou la mobilité."},"em":[],"pre":"","topic":"oncologie-support","title":"Clinical application of low-level laser therapy (Photo-biomodulation therapy) in the management of breast cancer-related lymphedema: a systematic review.","journal":"BMC cancer","journal_abbr":"BMC Cancer","authors":["Mahmood D","Ahmad A","Sharif F","et al."],"date":"2022-08-30","year":2022,"week":"2022-S35","doi":"10.1186/s12885-022-10021-8","pmcid":"PMC9426030","license":"cc by","oa":true,"pdf":"pdfs/36042421.pdf","cited_by":23,"pub_types":["Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"BACKGROUND","text":"Breast cancer-related lymphedema (BCRL) is a frequent issue that arises after mastectomy surgery in women and compromises physical and mental function. Previously published studies have shown positive effects with the use of Low-level laser therapy in another term Photo-biomodulation therapy (PBM). This research investigated the efficacy of clinical use of LLLT (PBM) in the treatment of metastatic breast cancer-related lymphedema."},{"label":"METHODS","text":"PubMed, PEDro, Medline, and the Cochrane Library were searched for LLLT clinical trials published before October 2021. The methodological quality of randomized trials and the effectiveness of Laser Therapy for BCRL were evaluated. The primary objectives were arm circumference or arm volume, whereas the secondary goals were to assess shoulder mobility and pain severity."},{"label":"RESULTS","text":"Eight clinical trials were analyzed in total. Typically, the included RCTs had good research quality. At four weeks, there was a considerable reduction in arm circumference/volume, and this continued with long-term follow-up. However, no statistically significant change in shoulder mobility or pain severity was seen between the laser and placebo groups at 0-, 1-, 2-, and 3-month short-term follow-up."},{"label":"CONCLUSIONS","text":"The findings of this comprehensive study demonstrated that LLLT (PBM) was successful in diminishing arm circumference and volume than improving shoulder mobility and pain. Data indicates that laser therapy (PBM) may be a beneficial treatment option for females with PML. Because of the scarcity of evidence, there is a strong need for well-conducted and longer-duration trials in this field."},{"label":"TRIAL REGISTRATION","text":"Details of the protocol for this systematic review were registered on PROSPERO and can be accessed at www.crd.york.ac.uk/PROSPERO/display_record.asp?ID=CRD42022315076 ."}],"keywords":["Breast cancer","Laser therapy","Low-level laser therapy","Lymphedema","Photo-biomodulation therapy","Postmastectomy lymphedema","Systematic review"]},{"pmid":"36110957","title_fr":"PBM contre les effets secondaires des traitements du cancer : position de la WALT 2022","type":"guideline","level":5,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Autres","l1":"La WALT juge les preuves solides pour prévenir et traiter de nombreuses complications des traitements du cancer, dont le lymphœdème, et propose des paramètres.","l2":"Recommandations d'un panel international (WALT, 2022).","l3":{"points":["Recommandations par complication."],"limites":["Consensus d'experts."],"pratique":"Référence pour les paramètres."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation therapy in management of cancer therapy-induced side effects: WALT position paper 2022.","journal":"Frontiers in oncology","journal_abbr":"Front Oncol","authors":["Robijns J","Nair RG","Lodewijckx J","et al."],"date":"2022-08-30","year":2022,"week":"2022-S35","doi":"10.3389/fonc.2022.927685","pmcid":"PMC9468822","license":"cc by","oa":true,"pdf":"pdfs/36110957.pdf","cited_by":120,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"DISCLAIMER","text":"This article is based on recommendations from the 12th WALT Congress, Nice, October 3-6, 2018, and a follow-up review of the existing data and the clinical observations of an international multidisciplinary panel of clinicians and researchers with expertise in the area of supportive care in cancer and/or PBM clinical application and dosimetry. This article is informational in nature. As with all clinical materials, this paper should be used with a clear understanding that continued research and practice could result in new insights and recommendations. The review reflects the collective opinion and, as such, does not necessarily represent the opinion of any individual author. In no event shall the authors be liable for any decision made or action taken in reliance on the proposed protocols."},{"label":"OBJECTIVE","text":"This position paper reviews the potential prophylactic and therapeutic effects of photobiomodulation (PBM) on side effects of cancer therapy, including chemotherapy (CT), radiation therapy (RT), and hematopoietic stem cell transplantation (HSCT)."},{"label":"BACKGROUND","text":"There is a considerable body of evidence supporting the efficacy of PBM for preventing oral mucositis (OM) in patients undergoing RT for head and neck cancer (HNC), CT, or HSCT. This could enhance patients' quality of life, adherence to the prescribed cancer therapy, and treatment outcomes while reducing the cost of cancer care."},{"label":"METHODS","text":"A literature review on PBM effectiveness and dosimetry considerations for managing certain complications of cancer therapy were conducted. A systematic review was conducted when numerous randomized controlled trials were available. Results were presented and discussed at an international consensus meeting at the World Association of photobiomoduLation Therapy (WALT) meeting in 2018 that included world expert oncologists, radiation oncologists, oral oncologists, and oral medicine professionals, physicists, engineers, and oncology researchers. The potential mechanism of action of PBM and evidence of PBM efficacy through reported outcomes for individual indications were assessed."},{"label":"RESULTS","text":"There is a large body of evidence demonstrating the efficacy of PBM for preventing OM in certain cancer patient populations, as recently outlined by the Multinational Association for Supportive Care in Cancer/International Society of Oral Oncology (MASCC/ISOO). Building on these, the WALT group outlines evidence and prescribed PBM treatment parameters for prophylactic and therapeutic use in supportive care for radiodermatitis, dysphagia, xerostomia, dysgeusia, trismus, mucosal and bone necrosis, lymphedema, hand-foot syndrome, alopecia, oral and dermatologic chronic graft-versus-host disease, voice/speech alterations, peripheral neuropathy, and late fibrosis amongst cancer survivors."},{"label":"CONCLUSIONS","text":"There is robust evidence for using PBM to prevent and treat a broad range of complications in cancer care. Specific clinical practice guidelines or evidence-based expert consensus recommendations are provided. These recommendations are aimed at improving the clinical utilization of PBM therapy in supportive cancer care and promoting research in this field. It is anticipated these guidelines will be revised periodically."}],"keywords":["cancer supportive care","cancer-treatment side effects","dermatitis","guidelines","mucositis","photobiomodulation (PBM)","recommendations"]},{"pmid":"36393948","title":"Efficacy of low-level laser therapy in the management of postoperative surgical sequelae after surgical removal of impacted mandibular third molars.","journal_abbr":"Natl J Maxillofac Surg","authors":["Thorat SD","Nilesh K"],"date":"2022-08-20","year":2022,"doi":"10.4103/njms.NJMS_52_20","pmcid":"PMC9651229","license":"cc by-nc-sa","oa":true,"cited_by":10,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[980],"l1":"LLLT with a diode laser of wavelength 980 nm can effectively reduce pain, swelling, and trismus in the postoperative phase after surgical extraction of the mandibular impacted third molar and promote healing at the operative site.","kw":"Impacted third molar laser dentistry pain swelling trismus"},{"pmid":"39902440","title":"Our Experience with Cryotherapy Versus Low-Level Laser Therapy in Managing Postoperative Discomfort of Third Molar Surgery.","journal_abbr":"J Maxillofac Oral Surg","authors":["Sharma SD","Vidya B","Gupta A","et al."],"date":"2022-07-12","year":2022,"doi":"10.1007/s12663-022-01759-6","pmcid":"PMC11787085","curated":false,"type":"autre","level":0,"ctx":[],"l1":"The mechanism of action and result outcomes for cryotherapy and LLLT has the potential to improve the quality of patient care provided by vast majority of clinicians in third molar surgery but when compared pain and swelling were better…","kw":"Cryotherapy Healing Low level laser therapy Third molar surgery"},{"pmid":"35874125","title":"Quality Assessment of PBM Protocols for Oral Complications in Head and Neck Cancer Patients: Part 1.","journal_abbr":"Front Oral Health","authors":["Gobbo M","Merigo E","Arany PR","et al."],"date":"2022-07-07","year":2022,"doi":"10.3389/froh.2022.945718","pmcid":"PMC9300948","license":"cc by","oa":true,"cited_by":14,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus","xérostomie"],"l1":"PBM therapy could significantly prevent or reduce the severity of many side effects related to cancer therapies. More research is needed to obtain recommendations over the preferable parameters.","kw":"dermatitis dysgeusia oedema oral cancer oral mucositis photobiomodulation"},{"pmid":"35700539","title":"Efficacy of two low-level laser therapy protocols following lower third molar surgery - a randomized, double-blind, controlled clinical trial.","journal_abbr":"Acta Odontol Latinoam","authors":["Ferreira GM","Prado LF","Santos KV","et al."],"date":"2022-06-14","year":2022,"doi":"10.54589/aol.35/1/31","pmcid":"PMC10283399","license":"cc by-nc","oa":true,"cited_by":5,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["trismus"],"nm":[660,789],"l1":"Both protocols performed similarly for pain control, swelling and trismus. Therefore, for practical reasons, a single laser application in the immediate postoperative period could be indicated for the management of postoperative…","kw":"low-level laser therapy pain swelling third molar trismus Double-Blind Method Edema Humans Low-Level Light Therapy Molar, Third Postoperative Pain"},{"pmid":"35743485","title":"Efficacy of Photobiomodulation in Reducing Symptomatology and Improving the Quality of Life in Patients with Xerostomia and Hyposalivation: A Randomized Controlled Trial.","journal_abbr":"J Clin Med","authors":["Ferrandez-Pujante A","Pons-Fuster E","López-Jornet P"],"date":"2022-06-14","year":2022,"doi":"10.3390/jcm11123414","pmcid":"PMC9225194","license":"cc by","oa":true,"cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["xérostomie","fatigue"],"nm":[810],"l1":"The beneficial effects of the diode laser in the PBM group persisted at one year post-treatment. Conclusions: Photobiomodulation with the diode laser is effective in patients with xerostomia and hyposalivation, and thus should be taken…","kw":"Xerostomia anxiety-depression laser therapy quality of life sleep disturbances"},{"pmid":"35911809","title":"Effectiveness of low-level laser therapy after surgical removal of impacted mandibular third molars: A randomized clinical trial.","journal_abbr":"Natl J Maxillofac Surg","authors":["Das AR","Vidya KC","Srikar MV","et al."],"date":"2022-04-20","year":2022,"doi":"10.4103/njms.njms_297_21","pmcid":"PMC9326211","license":"cc by-nc-sa","oa":true,"cited_by":9,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Low-level laser therapy was effective in reducing the postoperative pain, edema, and trismus in the third molar surgeries.","kw":"Low-level laser postoperative pain surgical removal third molar"},{"pmid":"35213927","title":"Noninvasive Systemic Modalities for Prevention of Head and Neck Radiation-Associated Soft Tissue Injury: A Narrative Review.","journal_abbr":"J Reconstr Microsurg","authors":["Kim LN","Rubenstein RN","Chu JJ","et al."],"date":"2022-02-25","year":2022,"doi":"10.1055/s-0042-1742731","pmcid":"PMC9402815","cited_by":4,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"While we cannot endorse any of these nine modalities for immediate clinical use, they may prove fruitful areas for further investigation.","kw":"Amifostine Deferoxamine Fibroblast Growth Factor 7 Humans Melatonin Pravastatin"},{"pmid":"36703670","title":"Comparative Study of the Efficacy of Low-Level Laser Therapy and Dexamethasone in Reducing the Severity of Post-Operative Inflammatory Response Following Surgical Extraction of Mandibular Third Molars.","journal_abbr":"J Maxillofac Oral Surg","authors":["Kohli A","Anehosur V","Radder K"],"date":"2022-01-23","year":2022,"doi":"10.1007/s12663-021-01681-3","pmcid":"PMC9871140","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"This study demonstrates that LLLT was beneficial in reduction in edema and trismus compared to dexamethasone following surgical extraction of third molars.","kw":"Dexamethasone Edema Low-level laser therapy (LLLT) Postoperative Trismus"},{"pmid":"34779937","title_fr":"Laser dans le lymphœdème lié au cancer du sein : revue des revues systématiques","type":"sr","level":1,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Le laser est sûr, mais sa supériorité sur les autres traitements n'est pas établie dans le lymphœdème lié au cancer du sein.","l2":"Revue des revues systématiques, complétée par une revue systématique actualisée d'essais randomisés (PubMed, Embase, Cochrane), sur le laser basse énergie dans le lymphœdème lié au cancer du sein.\n\nLa qualité de preuve est faible à très faible pour la plupart des critères. Le laser apporte un bénéfice par rapport à la compression, au placebo ou à l'absence de traitement, mais ne fait pas mieux que les autres interventions actives. Aucun effet indésirable n'est rapporté.","l3":{"points":["Évalue la qualité des revues existantes (GRADE).","Sécurité rassurante."],"limites":["Essais à risque de biais élevé ou incertain."],"pratique":"Traitement sûr, à proposer en complément ; sa supériorité sur les soins de référence n'est pas établie."},"em":[],"pre":"","topic":"oncologie-support","title":"The effectiveness and safety of low-level laser therapy on breast cancer-related lymphedema: An overview and update of systematic reviews.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Wang Y","Ge Y","Xing W","et al."],"date":"2021-11-15","year":2021,"week":"2021-S46","doi":"10.1007/s10103-021-03446-3","pmcid":"PMC8971164","license":"cc by","oa":true,"pdf":"pdfs/34779937.pdf","cited_by":14,"pub_types":["Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"","text":"The objective of our overview of systematic reviews was to critically analyze the evidence from existing systematic reviews investigating the effectiveness and safety of low-level laser therapy (LLLT) in patients with breast cancer-related lymphedema (BCRL). In addition, an updated and comprehensive systematic review was conducted, which aimed to provide updated evidence about this topic. PubMed, EMBASE, and Cochrane Library databases were systematically searched for systematic reviews and randomized controlled trials (RCTs) investigating the effectiveness and safety of LLLT in patients with BCRL. The methodological quality for each of included systematic reviews or RCTs was assessed using the Assessing the Methodological Quality of Systematic Reviews 2 (AMSTAR 2) tool or Cochrane risk of bias tool, respectively. The updated systematic review separately compared the effectiveness of LLLT to each of active or negative interventions. Data were pooled with random-effects models for each outcome per comparison. The evidence quality of outcomes was assessed using the Grading of Recommendations, Assessment, Development and Evaluation (GRADE) or GRADE-Confidence in the Evidence from Reviews of Qualitative research (GRADE-CERQual) for quantitative studies and qualitative studies, respectively. Seven systematic reviews and ten RCTs met the eligibility criteria. Conflicting results regarding the effectiveness of LLLT were presented by the overview of systematic reviews. The AMSTAR 2 showed that the methodological quality of included systematic reviews was low or critically low quality due to one or more critical weaknesses. The GRADE and GRADE-CERQual showed that the evidence quality was low to very low for most outcomes. The updated systematic review showed that LLLT may offer additional benefits as compared to compression therapies (pneumatic compression or compression bandage), placebo laser, or no treatment for patients with BCRL. However, when compared to other types of active interventions, LLLT did not improve outcomes significantly. None of the treatment-related adverse event was reported. Many trials had a high or unclear risk of bias for two or more items, and our updated systematic review showed low quality of evidence per outcome using GRADE approach. Due to insufficient data and poor quality of evidence, there is uncertain to reach these conclusions that LLLT is superior to another active or negative intervention and is safe. More RCTs of high methodological quality, with large sample sizes and long-term follow-up, are needed to inform clinical guidelines and routine practice."}],"keywords":["Breast cancer–related lymphedema","Low-level laser therapy","Overview","Photobiomodulation therapy","Systematic reviews"]},{"pmid":"34777487","title":"Conservative treatment of lymphedema: the state of the art.","journal_abbr":"J Vasc Bras","authors":["Bergmann A","Baiocchi JMT","de Andrade MFC"],"date":"2021-10-11","year":2021,"doi":"10.1590/1677-5449.200091","pmcid":"PMC8565523","license":"cc by","oa":true,"cited_by":38,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"In addition, since this is a chronic condition, the patient must adhere to the treatment. To this end, the therapeutic proposal may be the key to better control of limb volume.","kw":"combined modality therapy lymphedema physical therapy specialty rehabilitation treatment"},{"pmid":"34623486","title":"Clinical use of photobiomodulation as a supportive care during radiation therapy.","journal_abbr":"Support Care Cancer","authors":["Klausner G","Troussier I","Canova CH","et al."],"date":"2021-10-08","year":2021,"doi":"10.1007/s00520-021-06518-w","cited_by":7,"pub_types":["Editorial"],"curated":false,"type":"letter","level":0,"ctx":["lymphœdème"],"l1":"","kw":"Low-level light therapy Lymphedema Neoplasms Photobiomodulation Radiation dermatitis Radiation therapy Humans Low-Level Light Therapy Radiodermatitis Stomatitis"},{"pmid":"34424207","title":"Evaluation of the salivary flow of patients undergoing conventional radiotherapy for head and neck cancer.","journal_abbr":"Gen Dent","authors":["Lima MHCT","Ribeiro LN","Albuquerque RF","et al."],"date":"2021-08-23","year":2021,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"l1":"The mean total radiation dose (65 Gy) received by the patients in the present sample did not appear to influence the XI values or salivary volume. The data reinforced the subjective nature of xerostomia, which is not always related to…","kw":"hyposalivation radiotherapy salivation squamous cell carcinoma xerostomia Cross-Sectional Studies Head and Neck Neoplasms Humans Male Xerostomia"},{"pmid":"34409539","title_fr":"Lumière basse énergie et xérostomie liée à l'hyposialie : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"La PBM soulage la xérostomie et l'hyposialie à court terme, sans effet durable sur la qualité de vie.","l2":"Revue systématique avec méta-analyse d'essais cliniques.","l3":{"points":["Effet à court terme."],"limites":["Pas d'effet durable."],"pratique":"Bénéfice transitoire."},"em":[],"pre":"","topic":"oncologie-support","title":"Effects of low-level light therapy on xerostomia related to hyposalivation: a systematic review and meta-analysis of clinical trials.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Golež A","Frangež I","Cankar K","et al."],"date":"2021-08-19","year":2021,"week":"2021-S33","doi":"10.1007/s10103-021-03392-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":26,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Hyposalivation is a condition represented by a reduced salivary flow and may include symptoms such as mouth dryness (xerostomia), loss of taste, pain, dysphagia, and dysphonia, all of which greatly affect an individual's quality of life.The aim of the present study was to systematically review the effects of low-level light therapy irradiation (photobiomodulation) on salivary gland function in patients with hyposalivation.The main question of the systematic review was: \"Does low-level light irradiation therapy of the salivary glands affect salivary flow rate or indicators of salivary function (ion and protein concentrations) in patients with xerostomia or hyposalivation?\" The question was based on the PICO (participant, intervention, control, outcome) principle and followed the PRISMA guidelines. Databases were explored and papers published between the years 1997 and 2020 were reviewed for the following Mesh-term keywords and their corresponding entry terms in different combinations: \"Low-level light therapy,\" \"Xerostomia,\" \"Saliva,\" \"Salivary glands,\" \"Salivation.\"The initial sample consisted of 220 articles. Of those, 47 articles were used for full-text analysis and 18 were used for a systematic review, 14 were used in meta-analysis. According to their individual quality, most articles were classified as high quality of evidence according to the GRADE score. Meta-analysis of the evidence observed increase of unstimulated salivary flow 0.51 SMD compared to placebo (95% CI: 0.16-0.86), I2 = 50%, p = 0.005.The findings of our review revealed evidence of a beneficial effect of photobiomodulation therapy on salivary gland function. The therapy alleviates xerostomia and hyposalivation. However, these effects are reported short term only and did not induce lasting effects of photobiomodulation therapy on patients' quality of life."}],"keywords":["Low-level light therapy","Photobiomodulation","Saliva","Salivary glands","Salivation","Xerostomia"]},{"pmid":"34387119","title":"Photobiomodulation Therapy in Head and Neck Cancer-Related Lymphedema: A Pilot Feasibility Study.","journal_abbr":"Integr Cancer Ther","authors":["Deng J","Lukens JN","Swisher-McClure S","et al."],"date":"2021-08-13","year":2021,"doi":"10.1177/15347354211037938","pmcid":"PMC8366198","license":"cc by-nc","oa":true,"cited_by":15,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["lymphœdème","trismus"],"l1":"PBM therapy was feasible and potentially effective for the treatment of head and neck lymphedema. Future randomized controlled trials are warranted to examine the efficacy of PBM therapy for HNC-related lymphedema.","kw":"fibrosis head and neck cancer lymphedema photobiomodulation Feasibility Studies Head and Neck Neoplasms Humans Low-Level Light Therapy Lymphedema Quality of Lif"},{"pmid":"34272181","title":"[State of art of photobiomodulation in the management of radiotherapy adverse events: Indications and level of evidence].","journal_abbr":"Cancer Radiother","authors":["Klausner G","Bensadoun RJ","Champion A","et al."],"date":"2021-07-13","year":2021,"doi":"10.1016/j.canrad.2021.06.025","cited_by":4,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème","trismus","xérostomie"],"l1":"The published data suggest that PBM may be considered as a full-fledged supportive care for patients treated with radiotherapy, or at least in the setting of a therapeutic clinical trial. However, until strong evidence has been published…","kw":"Cancer Low-level light therapy Lymphedema Lymphœdème Mucite Neoplasms Acute Disease Clinical Protocols Deglutition Disorders Fibrosis Humans Low-Level Light The"},{"pmid":"34230117","title_fr":"Prise en charge intégrée du lymphœdème lié au cancer du sein : revue de l'état de l'art","type":"review","level":5,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"—","theme":"Lymphœdème","l1":"Revue des traitements du lymphœdème lié au cancer du sein, dont le laser ; il n'existe pas encore de traitement de référence.","l2":"Revue narrative de 33 articles.","l3":{"points":["Panorama complet."],"limites":["Revue descriptive."],"pratique":"Pour situer le laser."},"em":[],"pre":"","topic":"oncologie-support","title":"Integrated Treatment of Breast Cancer-related Lymphedema: A Descriptive Review of the State of the Art.","journal":"Anticancer research","journal_abbr":"Anticancer Res","authors":["Marchica P","D'Arpa S","Magno S","et al."],"date":"2021-07-05","year":2021,"week":"2021-S27","doi":"10.21873/anticanres.15109","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":26,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND/AIM","text":"Upper limb breast cancer-related lymphedema (BCRL) is a chronic and severe condition affecting a significant percentage of breast cancer survivors. Even though its physiopathology is well-known, there is no worldwide consensus on BCRL evaluation and a gold-standard treatment. This narrative review aims at providing a brief descriptive overview with regard to BCRL treatment modalities."},{"label":"MATERIALS AND METHODS","text":"We conducted a literature search within the PubMed database, and 33 articles out of 56 were selected, including reviews, systematic reviews, and meta-analyses aiming find the most updated evidence regarding BCRL treatment modalities."},{"label":"RESULTS","text":"Physical exercise (aerobic exercise, resistance exercise, aquatic therapy), bandages, and intermittent pneumatic compression were shown to be most effective in BCRL patients, in terms of swelling reduction in the acute-intensive phase. Furthermore, physical exercise was beneficial also as a maintenance tool. Manual lymphatic drainage demonstrated efficacy in preventing secondary lymphedema if applied immediately after breast cancer surgery or in early phases of BCRL or as a maintenance tool. Complementary procedures such as acupuncture, reflexology, yoga and photo-biomodulation therapy did not show conclusive results in BCRL treatment. Surgery was shown effective in managing symptoms (liposuction), preventing (lymphaticovenular anastomosis) and treating BCRL (vascularized lymph node transfer)."},{"label":"CONCLUSION","text":"BCRL is still a challenging condition either for breast cancer survivors and clinicians, deeply impacting patient functioning and quality of life. Due to the lack of globally accepted criteria in evaluating BCRL, to date a gold standard treatment for this widespread issue is still needed."}],"keywords":["Breast cancer-related lymphedema","complementary medicine","photo-biomodulation therapy","physical exercise","physical therapy","review","surgery"]},{"pmid":"34014116","title_fr":"Interventions contre le trismus des cancers ORL : revue systématique d'essais randomisés","type":"sr","level":1,"pop":"adulte","ctx":["trismus"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Trismus & fibrose radio-induite","l1":"Dans le trismus des cancers ORL, les exercices et dispositifs d'ouverture sont comparables ; le laser associé à l'exercice pourrait être bénéfique.","l2":"Revue systématique d'essais randomisés (PubMed, Embase, CINAHL, Cochrane, mars 2020) des interventions contre le trismus des cancers ORL.\n\nLes programmes d'exercices et les dispositifs d'ouverture buccale ont une efficacité comparable. Un essai chez des patients avec trismus installé montre qu'associer le laser basse énergie (ou les ultrasons) aux exercices fait mieux que les exercices seuls. Les rappels de suivi améliorent l'ouverture buccale dans deux essais.","l3":{"points":["Essais randomisés uniquement.","Souligne le rôle de l'observance."],"limites":["Un seul essai avec laser.","Pas de consensus sur l'intervention optimale."],"pratique":"Le laser se discute en complément des exercices, jamais à leur place."},"em":[],"pre":"","topic":"oncologie-support","title":"Interventions for Trismus in Head and Neck Cancer Patients: A Systematic Review of Randomized Controlled Trials.","journal":"Integrative cancer therapies","journal_abbr":"Integr Cancer Ther","authors":["Chee S","Byrnes YM","Chorath KT","et al."],"date":"2021-05-20","year":2021,"week":"2021-S20","doi":"10.1177/15347354211006474","pmcid":"PMC8145608","license":"cc by-nc","oa":true,"pdf":"pdfs/34014116.pdf","cited_by":25,"pub_types":["Research Support, Non-U.S. Gov't","Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"BACKGROUND","text":"Current treatment for head and neck cancers (HNCs) have led to an improved survival. However, the sequelae of cancer treatment often result in trismus, or reduced mouth opening. The purpose of this report is to identify interventional studies for trismus management in HNC patients."},{"label":"METHODS","text":"A search of PubMed, Embase, Cumulated Index to Nursing and Allied Health Literature, and the Cochrane Library was conducted in March 2020 for randomized controlled trials (RCTs) involving interventions for trismus for head and neck cancer within 10 years. Intervention could involve the use of an exercise regime, jaw rehabilitation device, technological device, medication or massage therapy. The primary outcome was the measurement of mouth opening."},{"label":"RESULTS","text":"Eleven RCTs involving a total of 685 patients with HNC were included. Six RCTs evaluated the effectiveness of a jaw mobilization device with exercises; there was no significant benefit of an exercise regime with a jaw mobilization device either initiated before, during or after treatment compared to no exercise. Two RCTs compared 2 intervention groups that involved exercises only, with 1 study assessing the benefit of weekly supervised physical therapy with gum chewing and another evaluating the benefit of immediate (1-2 days) versus delayed (7-10 days) initiation of exercise post-surgery; there was no significant difference between groups in either study. One RCT that recruited only patients with trismus demonstrated that an exercise regime in combination with low-level laser therapy or low-intensity ultrasound had superior results in mouth opening measurements compared to exercise alone. Two RCTs compared intervention groups with and without follow-up reminders; both studies showed a significant improvement in mouth opening measurements in groups with follow-up reminders."},{"label":"CONCLUSION","text":"This systematic review did not convey a clear consensus as to optimal intervention for trismus in HNC patients. A variety of exercise regimens and jaw rehabilitation devices appear to have comparable effectiveness. However, efforts focused on increasing adherence to a particular intervention protocol may positively impact mouth opening measures in head and neck cancer patients. Also, low-level laser therapy and low-intensity ultrasound coupled with exercise may be beneficial for patients with trismus."}],"keywords":["exercise","head and neck cancer","mouth opening","randomized controlled trial","rehabilitation","systematic review","trismus"]},{"pmid":"33989716","title":"Local application of low level laser therapy in mice ameliorates ovarian damage induced by cyclophosphamide.","journal_abbr":"Mol Cell Endocrinol","authors":["Oubiña G","Pascuali N","Scotti L","et al."],"date":"2021-05-12","year":2021,"doi":"10.1016/j.mce.2021.111318","cited_by":5,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"pre":"vivo","l1":"Vascular morphology, analysed by CD31 and α-SMA immunostaining, was restored in LLLT-treated ovaries compared to CTX alone. In conclusion, application of LLLT prior to CTX might serve as a promising and novel protocol to preserve female…","kw":"Angiogenesis Apoptosis Cancer Chemotherapy Low level laser therapy Ovary Animals Cyclophosphamide Cytochrome P-450 Enzyme System Disease Models, Animal Female H"},{"pmid":"33826415","title_fr":"Compression pneumatique intermittente plus laser dans le lymphœdème après mastectomie : effet à long terme","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Compression pneumatique et laser améliorent le lymphœdème, la force et la douleur ; leur association est un peu supérieure à long terme, surtout sur la douleur.","l2":"Essai randomisé (Lymphat Res Biol).","l3":{"points":["Effet à long terme."],"limites":["Gain modeste."],"pratique":"Association utile."},"em":[],"pre":"","topic":"oncologie-support","title":"Long-Term Effectiveness of Combined Intermittent Pneumatic Compression Plus Low-Level Laser Therapy in Patients with Postmastectomy Lymphedema: A Randomized Controlled Trial.","journal":"Lymphatic research and biology","journal_abbr":"Lymphat Res Biol","authors":["Kozanoglu E","Gokcen N","Basaran S","et al."],"date":"2021-04-07","year":2021,"week":"2021-S14","doi":"10.1089/lrb.2020.0132","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Background: Upper limb lymphedema may be revealed after breast cancer and its treatment. Among different treatment approaches, intermittent pneumatic compression (IPC) therapy and low-level laser therapy (LLLT) are reported as effective modalities in the treatment of postmastectomy upper limb lymphedema (PML). The aim of the current study is to investigate the long-term effectiveness of combined IPC plus LLLT versus IPC therapy alone in patients with PML. Methods and Results: The patients were allocated into two groups in this single-blinded, controlled clinical trial. Group I received combined treatment with IPC plus LLLT (n = 21) and group II received only IPC (n = 21). IPC treatment was given 5 sessions per week for 4 weeks (20 sessions). LLLT was also performed 5 sessions per week for 4 weeks (20 sessions). Clinical evaluations were performed before and after the treatment at the 3, 6, and 12-month follow-up visits. According to within-group analysis, statistically significant improvements in the circumference difference (Cdiff) and grip strength were observed in both groups (for Cdiff, p = 0.018 and p = 0.032, respectively; for grip strength, p = 0.001 and p = 0.046, respectively). Visual analog scale values for arm pain and shoulder pain during motion were decreased only in group I. Conclusion: Both interventions have positive effects on lymphedema, grip strength, and pain. Long-term effects of combined therapy, especially on pain, are slightly superior to the pneumatic compression alone."}],"keywords":["breast cancer","low-level laser therapy","lymphedema","physical therapy","pneumatic compression","postmastectomy"]},{"pmid":"33745088","title_fr":"PBM des glandes salivaires chez l'hémodialysé : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[808],"n":44,"effect":"favorable","theme":"Xérostomie","l1":"Chez l'insuffisant rénal hémodialysé, la PBM améliore l'hyposialie et réduit l'urée salivaire.","l2":"Essai randomisé contre placebo, 44 patients.","l3":{"points":["Xérostomie hors cancer."],"limites":["Un seul centre."],"pratique":"Option à considérer."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Effects of photobiomodulation in salivary glands of chronic kidney disease patients on hemodialysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Pavesi VCS","Martins MD","Coracin FL","et al."],"date":"2021-03-20","year":2021,"week":"2021-S11","doi":"10.1007/s10103-020-03158-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This randomized placebo-controlled trial evaluates the impact of photobiomodulation (PBMT) on the salivary flow and biochemistry of patients with chronic kidney disease (CKD) on hemodialysis. Forty-four patients on hemodialysis self-responded two questionnaires for oral health and salivary gland function perception. The subjects were evaluated for function of salivary glands and randomly allocated to two groups: PBMT group (three irradiations at 808 nm, 100 mW, 142 J/cm2, and 4 J per site); and placebo group. Patients were submitted to non-stimulated and stimulated sialometry and after the treatment at baseline and 14 days. Salivary volume and biochemical of the saliva were analyzed. At baseline, most subjects had self-perception of poor oral health (52.6%) and salivary dysfunction (63.1%). Clinical exam revealed that 47.3% of subjects presented dry mucosa. PBMT promoted increase of the non-stimulated (p = 0.027) and stimulated saliva (p = 0.014) and decrease of urea levels in both non-stimulated (p = 0.0001) and stimulated saliva (p = 0.0001). No alteration was detected in total proteins and calcium analysis. Patients with kidney disease can present alteration in flow, concentrations, and composition of saliva, affecting oral health, but our findings suggest that PBMT is effective to improve hyposalivation and urea levels in saliva of patients with CKD."}],"keywords":["Chronic kidney disease","Hemodialysis","Hyposalivation","Low level laser","Photobiomodulation","Xerostomia"]},{"pmid":"33776469","title":"Evaluation of Adjunctive Photobiomodulation (PBMT) for COVID-19 Pneumonia via Clinical Status and Pulmonary Severity Indices in a Preliminary Trial.","journal_abbr":"J Inflamm Res","authors":["Vetrici MA","Mokmeli S","Bohm AR","et al."],"date":"2021-03-19","year":2021,"doi":"10.2147/JIR.S301625","pmcid":"PMC7989376","license":"cc by-nc","oa":true,"cited_by":27,"pub_types":["Case Reports","Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":[],"l1":"PBMT is a safe and effective potential treatment for COVID-19 pneumonia and improves clinical status in COVID-19 pneumonia.","kw":"BCRSS COVID-19 RALE SMART-COP low-level laser therapy pneumonia"},{"pmid":"33678141","title":"The history of light therapy in hospital physiotherapy and medicine with emphasis on Australia: Evolution into novel areas of practice.","journal_abbr":"Physiother Theory Pract","authors":["Liebert A","Kiat H"],"date":"2021-03-07","year":2021,"doi":"10.1080/09593985.2021.1887060","cited_by":14,"pub_types":["Historical Article","Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Although it has fallen somewhat out of favour over the past decades, there has been a renewed interest using modern techniques in recent times. There has been continuous use of light as a therapy in hospitals in Australia, most…","kw":"Physiotherapy history light therapy photobiomodulation phototherapy Australia History, 19th Century History, 20th Century History, 21st Century Hospitals Humans"},{"pmid":"33587373","title":"Kaposi's Sarcoma-Related Lymphedema Treated by a Nd:YAG Laser.","journal_abbr":"Dermatol Surg","authors":["Nasca MR","Luppino I","Micali G"],"date":"2021-02-15","year":2021,"doi":"10.1097/DSS.0000000000002904","cited_by":5,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["lymphœdème"],"l1":"","kw":"Humans Lasers, Solid-State Low-Level Light Therapy Lymphedema Sarcoma, Kaposi Skin Neoplasms"},{"pmid":"33411048","title_fr":"Rapport coût-efficacité de la PBM contre les toxicités des traitements du cancer : revue","type":"sr","level":3,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Autres","l1":"La PBM paraît coût-efficace contre la mucite et le lymphœdème lié au cancer du sein ; les bénéfices économiques sont probablement sous-estimés.","l2":"Revue systématique.","l3":{"points":["Argument pour l'adoption dans les centres."],"limites":["Peu d'évaluations économiques complètes."],"pratique":"Argument médico-économique."},"em":[],"pre":"","topic":"oncologie-support","title":"Cost-effectiveness of photobiomodulation therapy for the prevention and management of cancer treatment toxicities: a systematic review.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Kauark-Fontes E","Rodrigues-Oliveira L","Epstein JB","et al."],"date":"2021-01-07","year":2021,"week":"2021-S01","doi":"10.1007/s00520-020-05949-1","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"To identify and summarize the evidence on the cost-effectiveness of photobiomodulation (PBM) therapy for the prevention and treatment of cancer treatment-related toxicities."},{"label":"METHODS","text":"This systematic review was performed according to the Preferred Reporting Items for Systematic Reviews and Meta-Analyses statement (PRISMA) and Meta-analysis Of Observational Studies in Epidemiology (MOOSE). Scopus, MEDLINE/PubMed, and Embase were searched electronically."},{"label":"RESULTS","text":"A total of 1490 studies were identified, and after a two-step review, 4 articles met the inclusion criteria. The included studies analyzed the cost-effectiveness of PBM therapy used in the context of lymphedema for breast cancer and oral mucositis (OM) induced by chemotherapy and radiotherapy. Better outcomes were associated with PBM therapy. The incremental cost-effectiveness ratio ranged from 3050.75 USD to 5592.10 USD per grade 3-4 OM case prevented. PBM therapy cost 21.47 USD per percentage point reduction in lymphedema in comparison with 80.51 USD for manual lymph drainage and physical therapy."},{"label":"CONCLUSION","text":"There is limited evidence that PBM therapy is cost-effective in the prevention and treatment of specific cancer treatment-related toxicities, namely, OM and breast cancer-related lymphedema. Studies may have underreported the benefits due to a lack of a comprehensive cost evaluation. This suggests a wider acceptance of PBM therapy at cancer treatment centers, which has thus far been limited by the number of robust clinical studies that demonstrate cost-effectiveness for the prevention and treatment of toxicities."}],"keywords":["Cancer toxicities","Cost","Photobiomodulation","Systematic review"]},{"pmid":"34277488","title":"Photobiomodulation in the treatment of xerostomia associated with hyposalivation in a pediatric patient with systemic scleroderma.","journal_abbr":"Autops Case Rep","authors":["de Oliveira AB","Ferrisse TM","Salomão KB","et al."],"date":"2020-12-14","year":2020,"doi":"10.4322/acr.2020.220","pmcid":"PMC8101649","license":"cc by","oa":true,"cited_by":3,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"nm":[660,808],"l1":"After this therapy, an increase in salivary flow, remission of the xerostomia, and an improvement in mastication and swallowing were observed. Photobiomodulation therapy was effective in controlling xerostomia in this pediatric patient,…","kw":"laser therapy low-level light therapy pediatrics scleroderma, systemic xerostomia"},{"pmid":"33247577","title":"Evaluation of the salivary function of patients in treatment with radiotherapy for head and neck cancer submitted to photobiomodulation.","journal_abbr":"Med Oral Patol Oral Cir Bucal","authors":["Ribeiro LN","Lima MH","Carvalho AT","et al."],"date":"2020-11-28","year":2020,"doi":"10.4317/medoral.23912","pmcid":"PMC7806351","license":"cc by","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[830],"l1":"Based upon the results of this study it was possible to conclude that the use of photobiomodulation did not significantly interfere with the xerostomia complaint of patients in treatment with radiotherapy, however, it does seem to prevent…","kw":"Cross-Sectional Studies Dental Caries Female Head and Neck Neoplasms Humans Male"},{"pmid":"34803281","title":"Laser as a promising non-invasive technique to treat oral submucous fibrosis: A systematic review of the literature.","journal_abbr":"Saudi Dent J","authors":["Gupta S","Jawanda MK"],"date":"2020-11-17","year":2020,"doi":"10.1016/j.sdentj.2020.11.005","pmcid":"PMC8589611","license":"cc by-nc-nd","oa":true,"cited_by":5,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus"],"l1":"Observing the current literature, it can be concluded that laser might be used as a potential non-invasive approach in the management of OSMF, however, large scale studies are required to investigate the efficacy and other effects of this…","kw":"AN, Areca nut CO2, Carbon-dioxide CTGF/CCN2, Connective tissue growth factor Er Cr YS GG, Erbium Chromium: Yttrium – Scandium – Gallium – Garnet Er, YAG Erbium:"},{"pmid":"33036145","title":"Photobiomodulation Dose Parameters in Dentistry: A Systematic Review and Meta-Analysis.","journal_abbr":"Dent J (Basel)","authors":["Cronshaw M","Parker S","Anagnostaki E","et al."],"date":"2020-10-06","year":2020,"doi":"10.3390/dj8040114","pmcid":"PMC7711492","license":"cc by","oa":true,"cited_by":48,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Many factors can confound clinical success including variations in anatomy, site location, clinical condition and subject individuality. To achieve higher levels of predictable outcome, a mature appreciation of these factors, plus an…","kw":"dentistry diode laser low-level laser therapy (LLLT) photobiomodulation (PBM) systematic review"},{"pmid":"33039721","title_fr":"La PBM prévient-elle l'hyposialie pendant la radiothérapie ORL ? Méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"Pendant la radiothérapie ORL, la PBM augmente le débit salivaire non stimulé (+0,20 mL/min) et stimulé (+0,27 mL/min).","l2":"Méta-analyse d'essais contrôlés (Crit Rev Oncol Hematol).","l3":{"points":["Effet préventif."],"limites":["Hétérogénéité très élevée (I² 95 %)."],"pratique":"Prévention prometteuse."},"em":[],"pre":"","topic":"oncologie-support","title":"Does laser photobiomodulation prevent hyposalivation in patients undergoing head and neck radiotherapy? A systematic review and meta-analysis of controlled trials.","journal":"Critical reviews in oncology/hematology","journal_abbr":"Crit Rev Oncol Hematol","authors":["Louzeiro GC","Teixeira DDS","Cherubini K","et al."],"date":"2020-10-01","year":2020,"week":"2020-S40","doi":"10.1016/j.critrevonc.2020.103115","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"INTRODUCTION","text":"Head and neck radiotherapy can cause hypofunction of the salivary glands. Many studies report that laser photobiomodulation (PBM) is able to minimize radiation-induced hyposalivation, yet there is no consensus about its effects."},{"label":"OBJECTIVE","text":"To carry out a meta-analysis of controlled clinical trials that used PBM to prevent radiation-induced hyposalivation."},{"label":"METHODS","text":"A systematic search was performed through Embase, Medline/PubMed, Cochrane, EBSCO, Scopus, LILACS and Web of Science databases. The strategy included comparisons of the effect of PBM with placebo/clinical follow-up on unstimulated and/or stimulated salivary flow in patients undergoing head and neck radiotherapy."},{"label":"RESULTS","text":"Six clinical trials were included, five of which were used for meta-analysis. Evidence was observed between the use of PBM and increased unstimulated salivary flow (MD 0.20 mL/min, 95 % Cl 0.10-0.30, I² = 96 %, p < 0.00001) and in stimulated salivary flow (MD 0.27 mL/min, 95 % CI 0.08-0.46, I² = 95 %, p < 0.00001)."},{"label":"CONCLUSION","text":"PBM appears to minimize radiation-induced hyposalivation."}],"keywords":["Hyposalivation","Low-level laser therapy","Photobiomodulation","Radiotherapy","Salivary glands","Xerostomia"]},{"pmid":"32964596","title_fr":"Bénéfices aigus et cumulés de la PBM dans la xérostomie : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[790,830],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"La PBM améliore la xérostomie et l'hyposialie, avec un effet immédiat et cumulatif, mais sans consensus sur les paramètres.","l2":"Revue systématique avec méta-analyse (Oral Dis).","l3":{"points":["Toutes causes confondues."],"limites":["Protocoles non standardisés."],"pratique":"Prometteur."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Acute and cumulative benefits of Photobiomodulation for xerostomia: A systematic review and meta-analysis.","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Galiano-Castillo N","Liu L","Lozano-Lozano M","et al."],"date":"2020-09-23","year":2020,"week":"2020-S39","doi":"10.1111/odi.13648","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The objective was to explore the effectiveness of photobiomodulation therapy for treating patients who suffer xerostomia and/or hyposalivation due to the most prevalent clinical diagnoses. We searched PubMed, Scopus, Web of Science, CINAHL and Cochrane Library for randomized or clinical controlled trials published until 31 October 2019. Risk of bias assessment and meta-analysis were conducted using the Cochrane tools. A total of 274 records were retrieved, and 11 met the inclusion criteria. Interventions whose parameters ranged between wavelengths of 790-830 nm (infrared), 30-120 mW of power and an energy density below 30 J/cm-2 were associated with improvements in xerostomia/hyposalivation. As for the assessment of methodological quality, 10 of the 11 articles included had a high risk of overall bias. Only 3 articles provided sufficient information to conduct a meta-analysis for quality of life, compared with placebo in patients with burning mouth syndrome, showing a standardized mean difference between groups from baseline of -0.90 (-1.48; -0.32). The present review and meta-analysis suggest that photobiomodulation therapy is an effective, non-invasive and safe approach in patients with xerostomia. However, despite the potential, it is not possible to reach a reliable consensus on the parameters to be used, and future studies should be conducted by standardizing intervention protocols."}],"keywords":["Xerostomia","low-level light therapy","meta-analysis","systematic review"]},{"pmid":"32734392","title":"Taste and smell disturbances in cancer patients: a scoping review of available treatments.","journal_abbr":"Support Care Cancer","authors":["Sevryugin O","Kasvis P","Vigano M","et al."],"date":"2020-07-30","year":2020,"doi":"10.1007/s00520-020-05609-4","cited_by":37,"pub_types":["Scoping Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"This scoping review identifies the current state of knowledge regarding chemosensory alterations within supportive cancer care. Despite not reaching firm conclusions, this article offers therapeutic venues to further explore in larger and…","kw":"Cancer Dysgeusia Smell Taste Treatment Adult Amifostine Carnosine Dronabinol Humans Neoplasms"},{"pmid":"32793501","title":"Review on the Cellular Mechanisms of Low-Level Laser Therapy Use in Oncology.","journal_abbr":"Front Oncol","authors":["Tam SY","Tam VCW","Ramkumar S","et al."],"date":"2020-07-24","year":2020,"doi":"10.3389/fonc.2020.01255","pmcid":"PMC7393265","license":"cc by","oa":true,"cited_by":82,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"This review aims to summarize the current knowledge of the cellular mechanisms of LLLT by considering its effects on cell proliferation, metabolism, angiogenesis, apoptosis and inflammation. With a better understanding of the cellular…","kw":"cellular mechanism inflammation low-level laser therapy metabolism oncology oncology treatment side effects"},{"pmid":"32570059","title_fr":"PBM, débit salivaire et xérostomie pendant la radiothérapie ORL : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[660,810],"n":null,"effect":"neutre","theme":"Xérostomie","l1":"Pendant la radiothérapie ORL, la PBM préserve le pH salivaire mais ne change ni le débit, ni la xérostomie, ni la qualité de vie à court terme.","l2":"Essai randomisé contrôlé.","l3":{"points":["Effet sur le pH."],"limites":["Suivi court."],"pratique":"Effet limité."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Effect of photobiomodulation on salivary flow and composition, xerostomia and quality of life of patients during head and neck radiotherapy in short term follow-up: A randomized controlled clinical trial.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Louzeiro GC","Cherubini K","de Figueiredo MAZ","et al."],"date":"2020-06-13","year":2020,"week":"2020-S24","doi":"10.1016/j.jphotobiol.2020.111933","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":31,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Xerostomia and hyposalivation are frequent conditions in patients undergoing head and neck radiotherapy, which usually lead to a worsening of quality of life. This study aimed to assess whether photobiomodulation (PBM) can minimize hyposalivation, xerostomia and qualitative changes on saliva and improve quality of life in patients undergoing radiotherapy in short-term follow-up. Twenty-one patients were randomly divided into two groups: sham group (SG) and laser group (LG). A diode laser was used for intra- (660 nm, 10 J/cm2, 0.28 J per point, 40 mW) and extra-oral (810 nm, 25 J/cm2, 0.7 J per point, 40 mW) applications over the salivary glands, three times a week, during the entire radiotherapy period. In SG, the tip of the instrument was sealed with blue rubber to prevent the passage of light. Xerostomia and pH were evaluated and unstimulated and stimulated salivary flow was determined before the start of radiotherapy (T1), after the 15th session (T2), after the end of radiotherapy (T3) and 60 days after radiotherapy (T4). Concentrations of calcium, total proteins, chloride, sodium, potassium and amylase and catalase activities were evaluated in stimulated saliva samples. Quality of life was assessed at times T1 and T4. Generalized estimating equations were used to assess differences in the outcome between times and groups. All patients showed worsening in unstimulated (p = .003) and stimulated (p < .001) salivary flow, xerostomia (p < .05) and quality of life during radiotherapy (p = .001). An increase in chloride concentrations was observed at times T3 and T4 (p < 0,05), and a reduction in amylase activity at T3 (p < .05). Unstimulated saliva pH was higher in LG than SG at T3 (p = .037). No difference between groups was noted in relation to salivary flow and composition, xerostomia or quality of life. Our results suggest that PBM may help in preserving salivary pH during radiotherapy."}],"keywords":["Photobiomodulation","Quality of life","Radiotherapy","Saliva","Salivary flow rate","Xerostomia"]},{"pmid":"32460618","title":"Photobiomodulation Therapy to Mitigate Radiation Fibrosis Syndrome.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Tam M","Arany PR","Robijns J","et al."],"date":"2020-05-27","year":2020,"doi":"10.1089/photob.2019.4766","cited_by":6,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["trismus"],"l1":"Results: Photobiomodulation (PBM) using low energy, nonionizing light primarily in the visible (especially red) or near-infrared spectrum has been demonstrated to decrease acute side effects of radiation in rigorously conducted phase III…","kw":"photobiomodulation (PBM) radiation fibrosis syndrome (RFS) radiation therapy Humans Low-Level Light Therapy Neoplasms Radiation Pneumonitis Radiotherapy"},{"pmid":"32760900","title":"Kinesio taping and low-level laser therapy in breast cancer-related lymphedema in an arm with arteriovenous fistula for hemodialysis.","journal_abbr":"Turk J Phys Med Rehabil","authors":["Özçete ZA","Eyigör S"],"date":"2020-05-18","year":2020,"doi":"10.5606/tftrd.2020.3430","pmcid":"PMC7401690","cited_by":6,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["lymphœdème"],"l1":"The arm volume difference was decreased from 691 mL to 454 mL after the treatments. Low-level laser therapy and kinesio taping should be kept in mind as alternative techniques for appropriate cases in the treatment of lymphedema.","kw":"Kinesio taping low-level laser therapy lymphedema"},{"pmid":"32311925","title":"Evaluation of photobiomodulation in salivary production of patients with xerostomy induced by anti-hypertensive drugs: Study protocol clinical trial (SPIRIT compliant).","journal_abbr":"Medicine (Baltimore)","authors":["Varellis MLZ","Gonçalves MLL","Pavesi VCS","et al."],"date":"2020-04-22","year":2020,"doi":"10.1097/MD.0000000000019583","pmcid":"PMC7220222","license":"cc by","oa":true,"cited_by":6,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["xérostomie"],"nm":[808],"l1":"This protocol will determine the effectiveness of photodynamic therapy regarding the reduction of xerostomia in older adults using antihypertensive drugs.","kw":"Antihypertensive Agents Double-Blind Method Humans Lasers, Semiconductor Low-Level Light Therapy Randomized Controlled Trials as Topic"},{"pmid":"32109187","title_fr":"PBM et dysfonction des glandes salivaires après cancer : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Xérostomie","l1":"Malgré des résultats préliminaires positifs, il est trop tôt pour affirmer l'efficacité de la PBM contre l'hyposialie et la xérostomie après cancer.","l2":"Revue systématique.","l3":{"points":["La plupart des essais sont positifs."],"limites":["Essais hétérogènes."],"pratique":"Incertain."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation Therapy for Cancer Treatment-Related Salivary Gland Dysfunction: A Systematic Review.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Heiskanen V","Zadik Y","Elad S"],"date":"2020-02-28","year":2020,"week":"2020-S09","doi":"10.1089/photob.2019.4767","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":27,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: Symptoms and clinical signs of decreased saliva secretion are a common after cancer therapy. The goal of this research is to systematically review the evidence about the efficacy of photobiomodulation therapy (PBMT) for the management of cancer treatment-related xerostomia or salivary hypofunction. Methods: PubMed was searched for articles investigating the clinical effects of PBMT on cancer therapy-related xerostomia or hyposalivation. The publications that met the eligibility criteria were evaluated for the quality of the study design, physical parameter setting reproducibility, specifics of the treatment protocol, clinical outcomes, and adverse effects. The strongest evidence was given a heavier weight in the overall conclusions. Results: A total of 314 articles were identified, and 5 controlled trials were included in this systematic review. Most of the studies were in head and neck cancer patients treated with radiotherapy (RT) or radiochemotherapy (RT-CT), and one study was in dry mouth associated with hematopoietic stem cell transplantation (HSCT). Data showed conflicting results for either prevention or treatment of RT- or RT-CT-induced dry mouth or hyposalivation. The data for HSCT-related dry mouth were positive. Conclusions: Despite positive preliminary outcomes in most of the trials, it is too early to confidently determine the efficacy of PBM for cancer therapy-related hyposalivation or xerostomia."}],"keywords":["cancer","dry mouth","laser","photobiomodulation","salivary hypofunction","xerostomia"]},{"pmid":"32073990","title_fr":"PRP, laser basse énergie et physiothérapie décongestive dans le lymphœdème du membre inférieur","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Dans le lymphœdème du membre inférieur, le laser améliore les mesures, mais c'est le PRP qui apparaît comme l'option nouvelle à explorer.","l2":"Essai randomisé à 3 bras (Lymphat Res Biol).","l3":{"points":["Membre inférieur."],"limites":["Petit effectif."],"pratique":"Le laser reste une option parmi d'autres."},"em":[],"pre":"","topic":"oncologie-support","title":"A Randomized Controlled Trial Comparing Platelet-Rich Plasma, Low-Level Laser Therapy, and Complex Decongestive Physiotherapy in Patients with Lower Limb Lymphedema.","journal":"Lymphatic research and biology","journal_abbr":"Lymphat Res Biol","authors":["Akgul A","Tarakci E","Arman N","et al."],"date":"2020-02-19","year":2020,"week":"2020-S08","doi":"10.1089/lrb.2019.0064","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Background: Platelet-rich plasma (PRP) is an autologous concentrated preparation of platelets characterized by lymphangiogenetic and tissue-repairing effects. Although PRP has been safely used in many different fields, there is no clinical study regarding the use of PRP in lymphedema treatment in humans. We assessed the clinical outcomes of PRP in patients with lower extremity lymphedema (LEL) in a randomized controlled trial. Methods and Results: Patients with secondary LEL were randomly allocated to one of three groups consisting of treatment with PRP with complex decongestive physiotherapy (PRP+CDP group), low-level laser therapy with CDP (LLLT+CDP group), and only CDP (CDP group). Assessment of Lymphedema Quality of-Life Questionnaire (LYMQOL) for health-related quality of life, lower-extremity-circumference (LEC) for edema, tissue dielectric constant (TDC) for extremity volume, 6-minute walking test (6MWT) for functional capacity, and numeric rating scale (NRS) scoring for extremity fullness were evaluated both before and after treatment. Forty-five patients (68.8% female) with mean age 40.84 ± 15.81 years were included in the study. Significant differences in LYMQOL, LEC, NRS, and TDC values both before and after treatment were found in all groups; however, there were no statistically significant difference in values between the three groups. In the PRP+CDP group, LYMQOL values had a larger effect size than the other two groups. Significant differences in 6MWT values both before and after treatment were found in PRP+CDP and LLLT+CDP groups; however, there was no statistically significant difference in the CDP group. Conclusion: This is the first clinical study to evaluate the usage of PRP in patients with secondary LEL. PRP might be an additional treatment option of lymphedema management; however, more clinical trials in humans are needed to yield more evidence in the usage of PRP in patients with lymphedema."}],"keywords":["QoL","complex decongestive physiotherapy","low-level laser therapy","platelet-rich plasma","secondary lymphedema"]},{"pmid":"31905890","title":"Clinical Usefulness of Bright White Light Therapy for Depressive Symptoms in Cancer Survivors: Results from a Series of Personalized (N-of-1) Trials.","journal_abbr":"Healthcare (Basel)","authors":["Kronish IM","Cheung YK","Julian J","et al."],"date":"2019-12-30","year":2019,"doi":"10.3390/healthcare8010010","pmcid":"PMC7151038","license":"cc by","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Conclusions: There were heterogeneous effects of three-week BWL on self-reported depressive symptoms among cancer survivors, with some finding a benefit but others finding no benefit or even harm. Implications for Cancer Survivors:…","kw":"N-of-1 trials bright white light therapy cancer survivor depression personalized medicine."},{"pmid":"31873066","title":"Photobiomodulation in Oral Medicine.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Kalhori KAM","Vahdatinia F","Jamalpour MR","et al."],"date":"2019-12-25","year":2019,"doi":"10.1089/photob.2019.4706","cited_by":29,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Conclusions: PBMT can be effective (as an alternative treatment or in combination with other therapies) in improving symptoms or in the complete treatment of oral diseases. However, further clinical studies are still necessary to achieve…","kw":"low-level laser therapy oral medicine photobiomodulation Humans Low-Level Light Therapy Oral Medicine"},{"pmid":"31754836","title_fr":"PBM dans le syndrome main-pied des chimiothérapies : étude pilote","type":"rct","level":2,"pop":"adulte","ctx":["main-pied"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Syndrome main-pied & ongles","l1":"Dans le syndrome main-pied, la PBM réduit les signes par rapport au sham et la douleur chez près de la moitié des patients, sans effet indésirable.","l2":"Étude pilote contrôlée contre sham.","l3":{"points":["Nouvelle indication."],"limites":["Pilote."],"pratique":"Piste prometteuse."},"em":[],"pre":"","topic":"oncologie-support","title":"Use of low-level laser therapy (LLLT) or photobiomodulation (PBM) for the management of the hand-foot syndrome (HSF) or palmo-plantar erythrodysesthesia (PPED) associated with cancer therapy.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Latifyan S","Genot MT","Fernez B","et al."],"date":"2019-11-21","year":2019,"week":"2019-S47","doi":"10.1007/s00520-019-05099-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of this pilot study was to determine whether photobiomodulation (PBM) might be effective for chemotherapy-induced palmo-plantar erythrodyesthesia (PPED), as it is for mucositis or radio dermatitis; no standard therapy exists for PPED. Patients were allocated to PBM or sham irradiation and were blindly assessed after 2 weeks. Pain and satisfaction with treatment were also evaluated. We found a significant benefit from PBM in comparison with sham treatment (p < 0.03) and a decrease of pain in 49% of the patients. No adverse reactions were observed. We concluded that PBM might represent a useful approach for the management of PPED."}],"keywords":["Chemotherapy-induced toxicity","Low-level laser","Palmo-plantar erythrodysesthesia","Photobiomodulation"]},{"pmid":"31780036","title_fr":"PBM dans le lymphœdème lié au cancer du sein : méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":316,"effect":"mitigé","theme":"Lymphœdème","l1":"La PBM réduit légèrement la circonférence et le volume du bras, sans bénéfice significatif sur le lymphœdème dans cette méta-analyse de 2019.","l2":"Méta-analyse d'essais randomisés (PROSPERO CRD42018102107 ; PubMed, Embase, PEDro, Scopus, CINAHL, CENTRAL) : neuf essais, 316 patientes, six poolés.\n\nPas de différence significative sur la circonférence ou le volume du bras après traitement, à un mois et à trois mois, ni sur la force de préhension et la douleur. La tendance reste légèrement favorable à la PBM.","l3":{"points":["Méta-analyse d'essais randomisés avec suivi à trois mois."],"limites":["Six essais poolés seulement, petits effectifs.","Résultat contradictoire avec d'autres synthèses."],"pratique":"Ne pas promettre de réduction de volume : le bénéfice, s'il existe, est modeste."},"k":9,"em":[],"pre":"","topic":"oncologie-support","title":"Effects of photobiomodualtion therapy on breast cancer-related lymphoedema: A systematic review and meta-analysis of randomised controlled trials.","journal":"Complementary therapies in medicine","journal_abbr":"Complement Ther Med","authors":["Chen HY","Tsai HH","Tam KW","et al."],"date":"2019-09-24","year":2019,"week":"2019-S39","doi":"10.1016/j.ctim.2019.102200","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"OBJECTIVE","text":"Lymphoedema characterised by the persistent accumulation of the interstitial fluid in peripheral tissues post breast cancer treatments. Photobiomodualtion therapy (PBMT) is widely used as supportive care in patients with breast cancer or breast cancer-related lymphoedema (BCRL). This systematic review and meta-analysis analysed the effectiveness and safety of PBMT for the treatment of BCRL."},{"label":"METHOD","text":"PubMed, EMBASE, PEDro, SCOPUS, CINAHL, and Cochrane Central Register of Controlled Trials were searched for RCTs on PBMT published before July 2019. Randomised controlled trials (RCTs) that evaluated the efficacy of PBMT on BCRL were included. The primary outcome was the arm circumference or volume, and secondary outcomes were grip strength and pain scores. This study is registered with PROSPERO (number CRD 42018102107)."},{"label":"RESULTS","text":"We reviewed nine RCTs that included 316 patients and six studies for mata-analysis. We found no significant difference in the reduction of the arm circumference or arm volume after treatment, one month, and three month follow-up between the PBMT and control groups. Studies revealed no significant differences in the reduction in grip strength and pain scores at 0, 1, 2, and 3 month between the PBMT and control groups."},{"label":"CONCLUSIONS","text":"Although PBMT demonstrated a slight improvement in reducing arm circumference and arm volume, the results of our meta-analysis did not show significant benefits in relieving of lymphoedema. Further trials are needed to recruit more participants, and to evaluate the long-term efficacy and safety of PBMT in management of breast cancer-related lymphoedema."}],"keywords":["Breast cancer","Low-level laser therapy","Lymphoedema","Meta-analysis","Photobiomodualtion therapy"]},{"pmid":"31079232","title_fr":"Laser en complément de la thérapie décongestive dans le lymphœdème : essai pilote contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Ajouter le laser à la thérapie décongestive complète soulage les symptômes et la détresse émotionnelle, sans réduction supplémentaire du volume.","l2":"Essai pilote randomisé en double aveugle contre placebo.","l3":{"points":["Gain sur les symptômes."],"limites":["Pas d'effet sur le volume."],"pratique":"Complément de confort."},"em":[],"pre":"","topic":"oncologie-support","title":"Complementary low-level laser therapy for breast cancer-related lymphedema: a pilot, double-blind, randomized, placebo-controlled study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Kilmartin L","Denham T","Fu MR","et al."],"date":"2019-05-11","year":2019,"week":"2019-S19","doi":"10.1007/s10103-019-02798-1","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":24,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This pilot, double-blind, randomized, placebo-controlled study is aimed at evaluating the effectiveness of low-level laser therapy (LLLT) as a complementary treatment to complete decongestive therapy (CDT) treating lymphedema among breast cancer patients for 12 months post-intervention. Study population was breast cancer patients who were diagnosed and referred to lymphedema clinic for CDT. Participants (n = 22) were randomized and assigned into either an active laser intervention group or an inactive laser placebo-control group. Active LLLT was administered to participants twice a week at the beginning of each CDT session. Outcome measures included lymphedema symptoms, symptom distress, and limb volume by an infrared perometer. Participants in the active and placebo laser groups were comparable in demographic and clinical predictors of lymphedema. In comparison with the placebo group (83.3%), significantly fewer participants in the active laser group (55.6%) reported more than one lymphedema symptom (p = 0.012) at 12 months post-intervention. Significantly, more patients in the active laser group (44.4%) reported less than two impaired limb mobility symptoms in comparison with the placebo group (33.3%) at 12 months post-intervention (p = 0.017). The active laser group had statistically significant improvements in symptom distress of sadness (p = 0.005) from 73 to 11% and self-perception (p = 0.030) from 36 to 0% over time from baseline to 12-months post-intervention. There was no significant reduction in limb volume. Findings of the trial demonstrated significant benefits of complementary LLLT for relieving symptoms and improvement of emotional distress in breast cancer patients with lymphedema."}],"keywords":["Breast cancer","Low-level laser","Lymphedema","Quality of life","Symptoms"]},{"pmid":"31050958","title":"Photobiomodulation with Low-Level Laser in the Treatment of Trismus After Radiotherapy: A Case Report.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Bernal Rodriguez CG","Eduardo CP","Aranha ACC","et al."],"date":"2019-05-04","year":2019,"doi":"10.1089/photob.2018.4524","cited_by":3,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"Results: The efficacy of the PBM protocol on the trismus after radiotherapy was evidenced by the decrease of pain and increase of the buccal opening. Conclusions: The use of PBM with low-level laser is an option for the treatment of…","kw":"chemotherapy glossectomy photobiomodulation trismus Aged Humans Low-Level Light Therapy Male Oropharyngeal Neoplasms Pain Measurement"},{"pmid":"31109692","title_fr":"Sécurité tumorale et effets indésirables de la PBM contre les toxicités des traitements du cancer : revue","type":"sr","level":3,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Autres","l1":"Selon les données disponibles, la PBM utilisée contre les toxicités des traitements du cancer n'entraîne pas de problème de sécurité tumorale.","l2":"Revue systématique (Oral Oncol, 2019).","l3":{"points":["Question centrale pour l'oncologie de support."],"limites":["Données humaines à long terme limitées."],"pratique":"Rassurant."},"em":[],"pre":"","topic":"oncologie-support","title":"Tumor safety and side effects of photobiomodulation therapy used for prevention and management of cancer treatment toxicities. A systematic review.","journal":"Oral oncology","journal_abbr":"Oral Oncol","authors":["de Pauli Paglioni M","Araújo ALD","Arboleda LPA","et al."],"date":"2019-04-10","year":2019,"week":"2019-S15","doi":"10.1016/j.oraloncology.2019.04.004","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":68,"pub_types":["Research Support, Non-U.S. Gov't","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT), also known as low-level laser therapy (LLLT), has been increasingly used for the treatment of toxicities related to cancer treatment. One of the challenges for the universal acceptance of PBMT use in cancer patients is whether or not there is a potential for the light to stimulate the growth of residual malignant cells that evaded oncologic treatment, increasing the risk for tumor recurrences and development of a second primary tumor. Current science suggests promising effects of PBMT in the prevention and treatment of breast cancer-related lymphedema and oral mucositis, among other cancer treatment toxicities. Nevertheless, this seems to be the first systematic review to analyze the safety of the use of PBMT for the management of cancer-related toxicities. Scopus, MEDLINE/PubMed, and Embase were searched electronically. A total of 27 articles met the search criteria. Selected studies included the use of PBMT for prevention and treatment of oral mucositis, lymphedema, radiodermatitis, and peripheral neuropathy. Most studies showed that no side effects were observed with the use of PBMT. The results of this systematic review, based on current literature, suggest that the use of PBMT in the prevention and management of cancer treatment toxicities does not lead to the development of tumor safety issues."}],"keywords":["Cancer","Cancer treatment toxicities","Laser","Mucositis","Photobiomodulation","Safety","Side effect","Systematic review"]},{"pmid":"30613078","title":"Effects of Ultrasound, Laser and Exercises on Temporomandibular Joint Pain and Trismus Following Head and Neck Cancer.","journal_abbr":"Ann Rehabil Med","authors":["Elgohary HM","Eladl HM","Soliman AH","et al."],"date":"2018-12-28","year":2018,"doi":"10.5535/arm.2018.42.6.846","pmcid":"PMC6325320","license":"cc by-nc","oa":true,"cited_by":20,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"The LIUS and TET are more effective than LLLT and/or TET in reducing TMJ pain and trismus following HNC.","kw":"Head and neck neoplasms Lasers Temporomandibular joint Trismus Ultrasonics"},{"pmid":"30423851","title":"Photobiomodulation Therapy in the Treatment of Oral Mucositis, Dysgeusia and Oral Dryness as Side-Effects of Head and Neck Radiotherapy in a Cancer Patient: A Case Report.","journal_abbr":"Dent J (Basel)","authors":["Mobadder ME","Farhat F","Mobadder WE","et al."],"date":"2018-11-10","year":2018,"doi":"10.3390/dj6040064","pmcid":"PMC6313426","license":"cc by","oa":true,"cited_by":17,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"l1":"For the assessment of oral dryness or hyposalivation, quantity of the total resting and stimulated saliva (Q-sal, mL/min) was measured.Photobiomodulation parameters, applications, and treatment protocol used were suggested by an…","kw":"Photobiomodulation, low-level laser therapy, dysgeusia, oral mucositis, oral dryness, hyposalivation, cancer."},{"pmid":"30313126","title":"Efficacy of diode-emitting diode (LED) photobiomodulation in pain management, facial edema, trismus, and quality of life after extraction of retained lower third molars: A randomized, double-blind, placebo-controlled clinical trial: Erratum.","journal_abbr":"Medicine (Baltimore)","authors":[],"date":"2018-10-14","year":2018,"doi":"10.1097/MD.0000000000012882","pmcid":"PMC6203495","license":"cc by","oa":true,"pub_types":["Published Erratum"],"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"","kw":""},{"pmid":"32158068","title":"Laser phototherapy in acute posttraumatic trismus - Case-series study.","journal_abbr":"Laser Ther","authors":["Rasca E","Namour A","Fauchon-Giumelli A","et al."],"date":"2018-09-30","year":2018,"doi":"10.5978/islsm.27_18-OR-21","pmcid":"PMC7034254","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"em":["cw"],"l1":"By scanning with an 810-nm laser beam, within less than 20 hours after the trauma, large areas of all the involved tissues and not just a few points, as described until now, the limited mouth opening in acute posttraumatic trismus was…","kw":"acute trismus laser phototherapy low-level laser therapy mandibular trauma masticatory muscles temporomandibular joint"},{"pmid":"29851090","title_fr":"Laser basse énergie dans le lymphœdème lié au cancer du sein : essai de faisabilité","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[810,980],"n":null,"effect":"neutre","theme":"Lymphœdème","l1":"Ajouter le laser à la prise en charge habituelle est faisable mais n'apporte pas de bénéfice clinique dans cet essai de faisabilité.","l2":"Essai randomisé de faisabilité (Nouvelle-Zélande).","l3":{"points":["114 patientes nécessaires pour un essai définitif."],"limites":["Non conçu pour l'efficacité."],"pratique":"Prépare un essai plus large."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Low level laser therapy for the management of breast cancer-related lymphedema: A randomized controlled feasibility study.","journal":"Lasers in surgery and medicine","journal_abbr":"Lasers Surg Med","authors":["Baxter GD","Liu L","Tumilty S","et al."],"date":"2018-05-30","year":2018,"week":"2018-S22","doi":"10.1002/lsm.22947","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"This study aimed to determine the feasibility of conducting a full scale randomized controlled trial investigating the effectiveness of low level laser therapy (LLLT), also known as photobiomodulation (PBM) therapy, used in addition to conventional therapy, for managing breast cancer related lymphedema (BCRL)."},{"label":"MATERIALS AND METHODS","text":"Patients with BCRL were recruited from the Southern District Health Board (New Zealand) via lymphedema therapists' referrals, and randomly allocated into either the laser group, which received BCRL conventional therapy (e.g., wearing compression garments, massage therapy, and/or exercise) plus a 6-week LLLT (PBM) intervention program (wavelength: 980/810 nm (80:20 ratio); output power: 500 mW beam spot size: 5 cm2 ; irradiance: 100 mW/cm2 ; treatment time per area: 1 minute dosage per area treated: 30J (6J/cm2 ); 10 points of treatment from axilla to wrist total LLLT (PBM) treatment time: 10 minutes total dosage delivered: 300 J), or the control group, which received BCRL conventional therapy alone. Feasibility was determined by recruitment and randomization rates, retention of participants and treatment protocol adherence, and was assessed during the recruiting and intervention periods. Data on participant satisfaction and adverse reactions of LLLT (PBM) were collected on completion of this study. Clinical outcomes (i.e., limb circumference, participant's perceived symptoms, psychological impacts, and activity disability) were assessed at baseline, and 6 and 12 weeks post-randomization."},{"label":"RESULTS","text":"Over a 6-month recruitment window, 17 participants with BCRL were recruited in the study, and randomized into the two groups (recruitment rate of 81%, and randomization rate of 100%). Treatment adherence was high in the laser group (88.9% of participants completed all treatments). Retention rates were 88.9% for the laser group and 100% for the control group at both 6 and 12 weeks post-randomization. All participants who completed LLLT (PBM) treatment indicated that they were satisfied with the treatment. No serious adverse reactions were reported in this study. Clinical outcomes failed to show additional benefits of LLLT (PBM) intervention."},{"label":"CONCLUSION","text":"This study demonstrated that it is feasible to conduct a fully powered RCT to definitively test the effectiveness of the additional use of LLLT (PBM) in the management of BCRL. For such a trial, 114 participants will be needed at baseline. Lasers Surg. Med. 50:924-932, 2018. © 2018 Wiley Periodicals, Inc."}],"keywords":["New Zealand","breast cancer related lymphedema","feasibility study","limb","low level laser therapy","parameters","photobiomodulation","randomized controlled trial","women"]},{"pmid":"29794809","title":"Photobiomodulation or low-level laser therapy in the management of cancer therapy-induced mucositis, dermatitis and lymphedema.","journal_abbr":"Curr Opin Oncol","authors":["Bensadoun RJ"],"date":"2018-05-26","year":2018,"doi":"10.1097/CCO.0000000000000452","cited_by":53,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"The article discusses LLLT/PBM mechanisms of action, dosimetry, and safety, and aims to identify some cancer treatment side-effects for which LLLT/PBM may prove to be effective (oral mucositis, radiation dermatitis, lymphedema). In…","kw":"Dermatitis Head and Neck Neoplasms Humans Low-Level Light Therapy Lymphedema Mucositis"},{"pmid":"29751100","title":"Low-level laser therapy with 850 nm recovers salivary function via membrane redistribution of aquaporin 5 by reducing intracellular Ca2+ overload and ER stress during hyperglycemia.","journal_abbr":"Biochim Biophys Acta Gen Subj","authors":["Biswas R","Ahn JC","Moon JH","et al."],"date":"2018-05-09","year":2018,"doi":"10.1016/j.bbagen.2018.05.008","cited_by":13,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["xérostomie"],"nm":[850],"pre":"vivo","l1":"High glucose induces intracellular Ca2+ overload and ER stress that disrupt AQP5 functional expression. Low-level laser therapy with 850 nm improves salivary function by increasing AQP5 membrane distribution in hyperglycemia-induced…","kw":"AQP5 Diabetes ER stress LLLT Salivary hypo-function Xerostomia Animals Aquaporin 5 Calcium Cell Membrane Diabetes Mellitus, Experimental Endoplasmic Reticulum S"},{"pmid":"29581740","title":"Effects of low-level laser therapy following surgical extraction of the lower third molar with objective measurement of swelling using a three-dimensional system.","journal_abbr":"Exp Ther Med","authors":["Koparal M","Kucuk AO","Alan H","et al."],"date":"2018-03-02","year":2018,"doi":"10.3892/etm.2018.5921","pmcid":"PMC5863601","license":"cc by-nc-nd","oa":true,"cited_by":26,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"The mean VAS measurements did not differ significantly among the groups at postoperative day 2; however, significantly reduced VAS values were observed in Group 2 compared with Group 1 at postoperative day 7 (P<0.05). The present study…","kw":"low-level laser therapy mandibular third molar surgery pain swelling trismus"},{"pmid":"29470703","title":"Guide for health professionals addressing oral care for individuals in oncological treatment based on scientific evidence.","journal_abbr":"Support Care Cancer","authors":["Carvalho CG","Medeiros-Filho JB","Ferreira MC"],"date":"2018-02-22","year":2018,"doi":"10.1007/s00520-018-4111-7","cited_by":23,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"The guide drafted has the function of assisting health professionals involved in the oral care of patients with cancer, enabling the prevention or treatment of oral complications stemming from oncological treatment.","kw":"Chemotherapy Dental care Oral health Oral hygiene Practice guideline Radiotherapy Adult Health Personnel Humans Neoplasms Oral Health"},{"pmid":"29216916","title_fr":"Laser dans le lymphœdème lié au cancer du sein : revue systématique","type":"sr","level":1,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Le laser peut être considéré comme un traitement efficace du lymphœdème lié au cancer du sein ; il fait mieux que l'absence de traitement à court terme.","l2":"Revue systématique des essais cliniques de laser basse énergie dans le lymphœdème lié au cancer du sein (PubMed, AMED, Web of Science, bases chinoises).\n\nPreuve forte (trois essais de bonne qualité) d'une réduction de la circonférence ou du volume du membre supérieure au placebo à court terme ; preuve modérée (un essai) sur la douleur à court terme ; preuve limitée contre l'absence de traitement. La qualité méthodologique des essais est bonne, mais les paramètres de traitement sont mal rapportés.","l3":{"points":["Classement explicite du niveau de preuve par critère.","Essais contre placebo de bonne qualité."],"limites":["Peu d'essais ; suivi court.","Paramètres optimaux inconnus."],"pratique":"Le laser peut compléter le drainage et la compression, sur des cures courtes."},"em":[],"pre":"","topic":"oncologie-support","title":"Low level laser therapy (Photobiomodulation therapy) for breast cancer-related lymphedema: a systematic review.","journal":"BMC cancer","journal_abbr":"BMC Cancer","authors":["Baxter GD","Liu L","Petrich S","et al."],"date":"2017-12-07","year":2017,"week":"2017-S49","doi":"10.1186/s12885-017-3852-x","pmcid":"PMC5719569","license":"cc by","oa":true,"pdf":"pdfs/29216916.pdf","cited_by":78,"pub_types":["Systematic Review"],"curated":true,"depth":2,"abstract":[{"label":"BACKGROUND","text":"Breast cancer related lymphedema (BCRL) is a prevalent complication secondary to cancer treatments which significantly impacts the physical and psychological health of breast cancer survivors. Previous research shows increasing use of low level laser therapy (LLLT), now commonly referred to as photobiomodulation (PBM) therapy, for BCRL. This systematic review evaluated the effectiveness of LLLT (PBM) in the management of BCRL."},{"label":"METHODS","text":"Clinical trials were searched in PubMed, AMED, Web of Science, and China National Knowledge Infrastructure up to November 2016. Two reviewers independently assessed the methodological quality and adequacy of LLLT (PBM) in these clinical trials. Primary outcome measures were limb circumference/volume, and secondary outcomes included pain intensity and range of motion. Because data were clinically heterogeneous, best evidence synthesis was performed."},{"label":"RESULTS","text":"Eleven clinical trials were identified, of which seven randomized controlled trials (RCTs) were chosen for analysis. Overall, the methodological quality of included RCTs was high, whereas the reporting of treatment parameters was poor. Results indicated that there is strong evidence (three high quality trials) showing LLLT (PBM) was more effective than sham treatment for limb circumference/volume reduction at a short-term follow-up. There is moderate evidence (one high quality trial) indicating that LLLT (PBM) was more effective than sham laser for short-term pain relief, and limited evidence (one low quality trial) that LLLT (PBM) was more effective than no treatment for decreasing limb swelling at short-term follow-up."},{"label":"CONCLUSIONS","text":"Based upon the current systematic review, LLLT (PBM) may be considered an effective treatment approach for women with BCRL. Due to the limited numbers of published trials available, there is a clear need for well-designed high-quality trials in this area. The optimal treatment parameters for clinical application have yet to be elucidated."}],"keywords":["Breast cancer related lymphedema","Low level laser therapy","Photobiomodulation","Systematic review"]},{"pmid":"29133965","title":"Evaluation of adjunctive effect of low-level laser Therapy on pain, swelling and trismus after surgical removal of impacted lower third molar: A double blind randomized clinical trial.","journal_abbr":"Laser Ther","authors":["Farhadi F","Eslami H","Majidi A","et al."],"date":"2017-11-15","year":2017,"doi":"10.5978/islsm.17-OR-13","pmcid":"PMC5675908","cited_by":32,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"Under limitations of this study, using low-power laser with mentioned parameters, clinically reduces pain, swelling and trismus after surgical removal of impacted mandibular wisdom, but not statistically significant.","kw":"Low level laser Therapy (LLLT) Pain, Lower third molar Trismus swelling"},{"pmid":"29119963","title":"[What physiotherapeutic method for the treatment of post-mastectomy lymphedema is the most effective?].","journal_abbr":"Vopr Kurortol Fizioter Lech Fiz Kult","authors":["Grushina TI"],"date":"2017-11-10","year":2017,"doi":"10.17116/kurort201794459-66","cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Electrical neurostimulation of the blood vessels and skeletal muscles proved especially effective for the treatment of I-II grade lymphedema while magnetic therapy was most efficient for the management of grade III-IV lymphedema. The…","kw":"breast cancer lymphedema physiotherapy rehabilitation Aged Female Humans Lymphedema Mastectomy Middle Aged"},{"pmid":"29119483","title_fr":"Laser basse énergie dans la xérostomie du syndrome de Sjögren primitif : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[808],"n":null,"effect":"neutre","theme":"Xérostomie","l1":"Dans le syndrome de Sjögren primitif, le protocole de laser testé n'améliore ni la sécheresse buccale ni le débit salivaire.","l2":"Essai randomisé contre placebo (NCT02066896).","l3":{"points":["Résultat négatif."],"limites":["Un seul protocole."],"pratique":"Pas d'intérêt démontré dans le Sjögren."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Low-level laser therapy for xerostomia in primary Sjögren's syndrome: a randomized trial.","journal":"Clinical rheumatology","journal_abbr":"Clin Rheumatol","authors":["Fidelix T","Czapkowski A","Azjen S","et al."],"date":"2017-11-09","year":2017,"week":"2017-S45","doi":"10.1007/s10067-017-3898-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":34,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To evaluate the effectiveness of low-level laser therapy (LLLT) in the treatment of xerostomia in primary Sjögren's syndrome (SS), a randomized clinical trial of patients with dry mouth symptoms associated with primary SS receiving care at a university hospital was conducted. Sixty-six patients were randomly assigned with a 1:1 allocation ratio to receive LLLT (laser group, n = 33) or placebo treatment (placebo group, n = 33). Patients in the laser group received LLLT twice a week for 6 weeks, for a total of 12 treatment sessions. Laser irradiation was performed with an aluminum-gallium-arsenide laser diode at a wavelength of 808 nm, 100-mW output power, and energy density of 4.0 J/cm2 per irradiation point per session. Placebo treatment was performed following the same protocol used for irradiated patients and using the same laser device to mimic a real irradiation, but with no active laser emission and the tip of the laser probe covered with aluminum foil. The outcomes of interest were xerostomia inventory scores, salivary flow rate, salivary beta-2 microglobulin levels, and salivary sodium and chlorine concentrations. Patients in both groups showed no improvement in xerostomia. Likewise, there was no significant improvement in xerostomia inventory scores (p = 0.301) or salivary flow rate (p = 0.643) in either group. There was no difference in salivary beta-2 microglobulin levels, sodium concentration, and chlorine concentration before and after intervention or between the two groups. The LLLT protocol used in this study effected no improvement in xerostomia or salivary flow rate in patients with primary SS. ClinicalTrials.gov Identifier: NCT02066896."}],"keywords":["Low-level laser therapy","Saliva biochemistry","Sjögren’s syndrome","Xerostomia"]},{"pmid":"29053051","title":"Photobiomodulation Therapy Alleviates Tissue Fibroses Associated with Chronic Graft-Versus-Host Disease: Two Case Reports and Putative Anti-Fibrotic Roles of TGF-β.","journal_abbr":"Photomed Laser Surg","authors":["Epstein JB","Raber-Durlacher JE","Huysmans MC","et al."],"date":"2017-10-19","year":2017,"doi":"10.1089/pho.2017.4297","cited_by":20,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"We discuss these observations in the context of currently understood molecular mechanisms, especially induction of transforming growth factor beta and NFκB that appear to be counter-intuitive to their known roles in matrix synthesis and…","kw":"dysphagia fibrosis hematopoietic stem cell transplantation low-level light/laser therapy oral graft versus host disease photobiomodulation therapy Adult Child C"},{"pmid":"29022754","title_fr":"Deux protocoles de PBM dans l'hyposialie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[685,830],"n":30,"effect":"favorable","theme":"Xérostomie","l1":"Dans l'hyposialie, les deux longueurs d'onde testées augmentent le débit salivaire, avec un effet encore présent 10 jours après la fin du traitement.","l2":"Essai randomisé, 30 patients, 10 séances.","l3":{"points":["Effet régénératif possible."],"limites":["Pas de placebo."],"pratique":"Option à considérer."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Different Protocols of Photobiomodulation Therapy of Hyposalivation.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Brzak BL","Cigić L","Baričević M","et al."],"date":"2017-10-12","year":2017,"week":"2017-S41","doi":"10.1089/pho.2017.4325","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":31,"pub_types":["Comparative Study","Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"Photobiomodulation (PBM) therapy has proved to be effective for a wide range of oral pathologies including oral dryness, but the literature still lacks reports of clinical trials and protocols. The purpose of our study was to evaluate the effects of different wavelengths of PBM on salivation in patients suffering from hyposalivation aiming at determination of optimal treatment protocol."},{"label":"MATERIALS AND METHODS","text":"This study included 30 patients whose major salivary glands were treated with low-intensity diode laser BTL2000 (Medical Technologies, s.r.o., Czech Republic) during 10 consecutive days. Patients were randomly assigned into two groups, each of 15 patients, and treated with PBM of 830 nm and PBM of 685 nm, respectively. The whole unstimulated and stimulated saliva quantities were measured each day during 10 days, before and after laser treatment, and at 10th day after treatment was ended."},{"label":"RESULTS","text":"Results have shown that the laser treatment significantly improves salivation (p < 0.0001) in both groups after 10 days treatment. The salivation also remains improved 10 days after the end of treatment. The patients treated with PBM of 830 nm have had continuously higher values of quantity of saliva."},{"label":"CONCLUSIONS","text":"Our results have shown that both laser wavelengths were effective in increasing salivary flow rate, and the improvement in salivation was statistically significant. The effect of treatment could be observed 10 days after the completion of treatment, thus providing evidence not only of stimulative effect but also indicating regenerative potential of PBM therapy."}],"keywords":["hyposalivation","photobiomodulation","protocol"]},{"pmid":"29020483","title":"Efficacy of low-level laser therapy as an auxiliary tool for management of acute side effects of head and neck radiotherapy.","journal_abbr":"J Cosmet Laser Ther","authors":["González-Arriagada WA","Ramos LMA","Andrade MAC","et al."],"date":"2017-10-12","year":2017,"doi":"10.1080/14764172.2017.1376097","cited_by":29,"pub_types":["Observational Study"],"curated":false,"type":"cohort","level":4,"ctx":["xérostomie"],"l1":"The introduction of laser therapy in the supportive care for patients undergoing HNRT showed benefits for the patient and the medical system, reducing morbidity and costs associated with side-effects.","kw":"Head and neck cancer adverse effects oral mucositis radiation xerostomia Adult Aged Case-Control Studies Female Head and Neck Neoplasms Humans"},{"pmid":"28933995","title":"Identification, assessment and management of breast oedema after treatment for cancer.","journal_abbr":"Int J Palliat Nurs","authors":["Todd M"],"date":"2017-09-22","year":2017,"doi":"10.12968/ijpn.2017.23.9.440","cited_by":10,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"The principles of managing breast oedema are based on lymphoedema practice, particularly manual lymphatic drainage and kinesio taping. This article gives an overview of the identification, assessment and management of breast oedema…","kw":"breast cancer breast oedema breast-conserving surgery lymphoedema Athletic Tape Breast Neoplasms Diagnosis, Differential Exercise Female Humans"},{"pmid":"28877002","title":"Lymphedema: Pathogenesis and Novel Therapies.","journal_abbr":"Annu Rev Med","authors":["Dayan JH","Ly CL","Kataru RP","et al."],"date":"2017-09-06","year":2017,"doi":"10.1146/annurev-med-060116-022900","cited_by":129,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"These findings have allowed for the development of novel medical and surgical therapies that may potentially alter the standard of care for a disease that has largely been treated by compression. This review seeks to provide an overview…","kw":"CD4+ cells complete decongestive therapy lymph node transfer lymphovenous bypass Breast Cancer Lymphedema Disease Progression Exercise Therapy Genetic Therapy H"},{"pmid":"28578368","title":"Effect of pre-operatory low-level laser therapy on pain, swelling, and trismus associated with third-molar surgery.","journal_abbr":"Med Oral Patol Oral Cir Bucal","authors":["Petrini M","Ferrante M","Trentini P","et al."],"date":"2017-06-05","year":2017,"doi":"10.4317/medoral.21398","pmcid":"PMC5549519","license":"cc by","oa":true,"cited_by":17,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"Pre-surgical LLLT treatment seems to increase the analgesic effect of LLLT. However, trismus and edema were reduced in both laser treated groups, independently from the period of irradiation.","kw":"Edema Humans Low-Level Light Therapy Molar, Third Postoperative Pain Postoperative Complications"},{"pmid":"28258315","title":"Impact of low-level laser therapy on hyposalivation, salivary pH, and quality of life in head and neck cancer patients post-radiotherapy.","journal_abbr":"Lasers Med Sci","authors":["Palma LF","Gonnelli FAS","Marcucci M","et al."],"date":"2017-03-03","year":2017,"doi":"10.1007/s10103-017-2180-3","cited_by":44,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["xérostomie"],"nm":[808],"em":["cw"],"l1":"There were significant increases in both mean salivary flow rates (unstimulated: p = 0.0012; stimulated: p < 0.0001), mean pH values (p = 0.0002 and p = 0.0004), and mean score from the quality of life questionnaire (p < 0.0001).…","kw":"Head and neck neoplasms Low-level light therapy Radiotherapy Adult Aged Demography Female Head and Neck Neoplasms Humans"},{"pmid":"28249650","title_fr":"Traitements de la xérostomie et de l'hyposialie radio-induites : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Xérostomie","l1":"Dans la xérostomie radio-induite, la pilocarpine et la céviméline restent la première ligne ; les autres traitements, dont le laser, ne sont pas soutenus par les données de 2016.","l2":"Revue systématique avec méta-analyse d'essais randomisés (Oral Oncol).","l3":{"points":["Hiérarchie des traitements."],"limites":["Peu d'essais laser à l'époque."],"pratique":"Le laser n'est pas la première ligne."},"em":[],"pre":"","topic":"oncologie-support","title":"Interventions for the management of radiotherapy-induced xerostomia and hyposalivation: A systematic review and meta-analysis.","journal":"Oral oncology","journal_abbr":"Oral Oncol","authors":["Mercadante V","Al Hamad A","Lodi G","et al."],"date":"2017-01-19","year":2017,"week":"2017-S03","doi":"10.1016/j.oraloncology.2016.12.031","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":115,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"INTRODUCTION","text":"Salivary gland hypofunction is a common and permanent adverse effect of radiotherapy to the head and neck. Randomised trials of available treatment modalities have produced unclear results and offer little reliable guidance for clinicians to inform evidence-based therapy. We have undertaken this systematic review and meta-analysis to estimate the effectiveness of available interventions for radiotherapy-induced xerostomia and hyposalivation."},{"label":"METHODS","text":"We searched MEDLINE, Cochrane Central, EMBASE, AMED, and CINAHL database through July 2016 for randomised controlled trials comparing any topical or systemic intervention to active and/or non-active controls for the treatment of radiotherapy-induced xerostomia. The results of clinically and statistically homogenous studies were pooled and meta-analyzed."},{"label":"RESULTS","text":"1732 patients from twenty studies were included in the systematic review. Interventions included systemic or topical pilocarpine, systemic cevimeline, saliva substitutes/mouthcare systems, hyperthermic humidification, acupuncture, acupuncture-like transcutaneous electrical nerve stimulation, low-level laser therapy and herbal medicine. Results from the meta-analysis, which included six studies, suggest that both cevimeline and pilocarpine can reduce xerostomia symptoms and increase salivary flow compared to placebo, although some aspects of the relevant effect size, duration of the benefit, and clinical meaningfulness remain unclear. With regard to interventions not included in the meta-analysis, we found no evidence, or very weak evidence, that they can reduce xerostomia symptoms or increase salivary flow in this population."},{"label":"CONCLUSIONS","text":"Pilocarpine and cevimeline should represent the first line of therapy in head and neck cancer survivors with radiotherapy-induced xerostomia and hyposalivation. The use of other treatment modalities cannot be supported on the basis of current evidence."}],"keywords":["Acupuncture","Radiotherapy","Saliva","Sialogogue","Xerostomia"]},{"pmid":"28912943","title":"Assessment of Low-Level Laser Therapy Effects After Extraction of Impacted Lower Third Molar Surgery.","journal_abbr":"J Lasers Med Sci","authors":["Raiesian S","Khani M","Khiabani K","et al."],"date":"2017-01-08","year":2017,"doi":"10.15171/jlms.2017.08","pmcid":"PMC5420364","cited_by":26,"curated":false,"type":"autre","level":0,"ctx":["trismus"],"nm":[980],"l1":"The amount of swelling according to different measurements did not significantly differ between the two groups neither at 24 hours nor at 1 week after surgery. Conclusion: Our findings showed that LLLT was useful in reducing pain and…","kw":"Laser therapy Maximum mouth opening Pain Swelling Third molar"},{"pmid":"27943450","title_fr":"PBM dans le lymphœdème lié au cancer du sein : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":40,"effect":"neutre","theme":"Lymphœdème","l1":"Un protocole court de PBM par laser en grappe n'améliore ni la qualité de vie, ni la douleur, ni la force, ni le volume du bras par rapport au placebo.","l2":"Essai randomisé en double aveugle contre placebo, 40 patientes.","l3":{"points":["Résultat négatif."],"limites":["Protocole court (8 séances)."],"pratique":"Les protocoles courts ne suffisent pas."},"em":[],"pre":"","topic":"oncologie-support","title":"Photobiomodulation therapy in breast cancer-related lymphedema: a randomized placebo-controlled trial.","journal":"Photodermatology, photoimmunology & photomedicine","journal_abbr":"Photodermatol Photoimmunol Photomed","authors":["Storz MA","Gronwald B","Gottschling S","et al."],"date":"2016-12-13","year":2016,"week":"2016-S50","doi":"10.1111/phpp.12284","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":22,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"The aim of our study was to examine the effects of photobiomodulation therapy (PBMT) in the treatment of breast cancer-related lymphedema using a compactly designed treatment regime consisting of eight therapy sessions in combination with a cluster laser device covering a total area size of 78.54 cm² over the axillary."},{"label":"METHODS","text":"Forty patients with unilateral lymphedema were enrolled in this double-blind, placebo-controlled trial in order to evaluate effects of PBMT on lymphedema-related pain, quality of life, grip strength and limb volume difference. Subjects received irradiation for ten minutes per session using a cluster laser covering a beam area of 78.54 cm². The applied energy was 384 Joules resulting in an energy density of 4.89 J/cm²."},{"label":"RESULTS","text":"Post-treatment, a 50% reduction in median pain scores and an increase in mean quality of life were observed. Mean grip strength was persistently higher after eight sessions of PBMT compared with pretreatment; however, no statistically significant intergroup differences (P > 0.05) were found over the time course."},{"label":"CONCLUSION","text":"PBMT using a compactly designed treatment regime in combination with a cluster laser device did not significantly improve quality of life, pain scores, grip strength and limb volume over the time course."}],"keywords":["breast cancer-related lymphedema","grip strength","limb volume","pain","photobiomodulation therapy"]},{"pmid":"29908550","title":"The Diagnosis and Treatment of Peripheral Lymphedema: 2016 Consensus Document of the International Society of Lymphology.","journal_abbr":"Lymphology","authors":["Executive Committee"],"date":"2016-12-01","year":2016,"cited_by":341,"pub_types":["Consensus Statement"],"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Therefore, the document has been, and should continue to be, challenged and debated in the pages of Lymphology (e.g., as Letters to the Editor) and ideally will remain a continued focal point for robust discussion at local, national and…","kw":"Aftercare Anti-Bacterial Agents Antiparasitic Agents Compression Bandages Cytoreduction Surgical Procedures Diuretics"},{"pmid":"27866178","title":"Low-level Laser Therapy: A Review of Its Applications in the Management of Oral Mucosal Disorders.","journal_abbr":"Altern Ther Health Med","authors":["Spanemberg JC","Figueiredo MA","Cherubini K","et al."],"date":"2016-11-21","year":2016,"cited_by":17,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Although information on the use of the laser for some lesions has already been consolidated, further research is needed, especially randomized, controlled clinical trials with long-term follow-up. Those studies will allow the safe use of…","kw":"Burning Mouth Syndrome Herpes Labialis Humans Lichen Planus, Oral Low-Level Light Therapy Mouth Diseases"},{"pmid":"28030915","title":"Current Treatments for Breast Cancer-Related Lymphoedema: A Systematic Review.","journal_abbr":"Asian Pac J Cancer Prev","authors":["Li L","Yuan L","Chen X","et al."],"date":"2016-11-01","year":2016,"doi":"10.22034/APJCP.2016.17.11.4875","pmcid":"PMC5454690","license":"cc by-sa","oa":true,"cited_by":40,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Conclusion: Although many treatments for BCRL might reduce lymphoedema volume, their effects were not well established. The quality of many of the original studies in the included reviews was not optimal, so that in future randomized…","kw":"Breast cancer lymphoedema systematic review combined physical therapy"},{"pmid":"27655559","title":"Photobiomodulation therapy in the management of chronic oral graft-versus-host disease.","journal_abbr":"Support Care Cancer","authors":["Epstein JB","Raber-Durlacher JE","Lill M","et al."],"date":"2016-09-21","year":2016,"doi":"10.1007/s00520-016-3401-1","cited_by":22,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"l1":"Oral pain, sensitivity, and dry mouth improved in most patients. These findings suggest PBM therapy may represent an additional approach for management of oral cGVHD, and suggest that controlled studies should be conducted to confirm the…","kw":"Hematopoietic stem cell transplantation Hyposalivation LLLT Low-level laser therapy Oral graft-versus-host disease PBM therapy Adolescent Adult Aged Chronic Dis"},{"pmid":"27613370","title":"Laser acupuncture attenuates oxaliplatin-induced peripheral neuropathy in patients with gastrointestinal cancer: a pilot prospective cohort study.","journal_abbr":"Acupunct Med","authors":["Hsieh YL","Chou LW","Hong SF","et al."],"date":"2016-09-09","year":2016,"doi":"10.1136/acupmed-2016-011112","cited_by":38,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Following treatment with LA, neurotoxicity symptoms were significantly improved in cancer patients with OIPN. Further randomised controlled trials are needed to evaluate the role of LA as a therapeutic option in the management of OIPN.","kw":"ONCOLOGY Acupuncture Therapy Adult Aged Aged, 80 and over Antineoplastic Agents Female"},{"pmid":"27539464","title":"The use of low-level light therapy in supportive care for patients with breast cancer: review of the literature.","journal_abbr":"Lasers Med Sci","authors":["Robijns J","Censabella S","Bulens P","et al."],"date":"2016-08-19","year":2016,"doi":"10.1007/s10103-016-2056-y","cited_by":51,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"The findings of this review suggest that LLLT is a promising option for the management of breast cancer treatment-related side effects. However, it still remains important to define appropriate treatment and irradiation parameters for…","kw":"Breast cancer Low-level light therapy Oncology Photobiomodulation therapy Supportive care Breast Neoplasms Clinical Trials as Topic Female Humans Low-Level Ligh"},{"pmid":"27457369","title":"Evaluation of the effects of the low-level laser therapy on swelling, pain, and trismus after removal of impacted lower third molar.","journal_abbr":"Head Face Med","authors":["Alan H","Yolcu Ü","Koparal M","et al."],"date":"2016-07-26","year":2016,"doi":"10.1186/s13005-016-0121-1","pmcid":"PMC4960798","license":"cc by","oa":true,"cited_by":52,"pub_types":["Evaluation Study"],"curated":false,"type":"autre","level":0,"ctx":["trismus"],"l1":"Although there were decreasing trismus, swelling, and pain level, with this LLLT, there was significant difference only in the 7th day pain level in the laser group compared with the control group.","kw":"3dMD 3rd molar Laser Pain Swelling Trismus Adolescent Adult Case-Control Studies Female Humans Low-Level Light Therapy"},{"pmid":"27415181","title":"The Effectiveness of Low-Level Laser Therapy in Patients with Drug-Induced Hyposalivation: A Pilot Study.","journal_abbr":"Photomed Laser Surg","authors":["Terlević Dabić D","Jurišić S","Vučićević Boras V","et al."],"date":"2016-07-14","year":2016,"doi":"10.1089/pho.2016.4109","cited_by":18,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[830],"l1":"The results of this study showed that the LLLT increased unstimulated salivary flow rate significantly. However, stimulated salivary flow rate did not increase significantly after the LLLT. In patients who underwent sham laser therapy,…","kw":"Aged Female Humans Lasers, Semiconductor Low-Level Light Therapy Male"},{"pmid":"27196626","title_fr":"Laser contre la baisse du débit salivaire pendant la radiochimiothérapie ORL","type":"nrct","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[660],"n":27,"effect":"favorable","theme":"Xérostomie","l1":"Pendant la radiochimiothérapie ORL, le laser intrabuccal (660 nm, 10 J/cm²) maintient un débit salivaire plus élevé que les soins habituels.","l2":"Étude prospective longitudinale contrôlée, 27 patients.","l3":{"points":["Prévention de l'hyposialie."],"limites":["Non randomisée."],"pratique":"Prévention possible."},"em":[],"pre":"","topic":"oncologie-support","title":"Low-Level Laser for Mitigation of Low Salivary Flow Rate in Head and Neck Cancer Patients Undergoing Radiochemotherapy: A Prospective Longitudinal Study.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Gonnelli FA","Palma LF","Giordani AJ","et al."],"date":"2016-05-19","year":2016,"week":"2016-S20","doi":"10.1089/pho.2016.4104","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":30,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"The present study aimed to assess the impact of low-level laser (LLL) on low salivary flow rate in patients undergoing radiochemotherapy (RT-CT) for head and neck cancer."},{"label":"BACKGROUND DATA","text":"LLL has shown efficiency in preventing hyposalivation in patients under different pathological conditions, including those undergoing RT-CT."},{"label":"METHODS","text":"During all RT-CT, 17 patients received laser therapy and 10 received clinical care only. An Indium-Gallium-Aluminum-Phosphorus diode laser was punctually used for intraoral (660 nm, 40 mW, 10 J/cm(2), illuminated area 0.04 cm(2), 10 sec) and extraoral irradiation (780 nm, 15 mW, 3.8 J/cm(2), illuminated area 0.04 cm(2), 10 sec), three times a week and on alternate days, for a total of 21 sessions. Unstimulated salivary flow rate was assessed before the first RT session (N0), at the 15th RT session (N15), at the last RT session (Nf), and at 30 (N30) and 90 days after the end of the oncologic treatment (N90)."},{"label":"RESULTS","text":"At N15, Nf, and N30, patients treated with LLL showed significantly higher averages of salivary flow rate when compared with patients receiving clinical care only."},{"label":"CONCLUSIONS","text":"LLL seems to be an efficient tool for mitigation of salivary hypofunction in patients undergoing RT for head and neck cancer."}],"keywords":[]},{"pmid":"26984249","title":"Low-level laser therapy/photobiomodulation in the management of side effects of chemoradiation therapy in head and neck cancer: part 2: proposed applications and treatment protocols.","journal_abbr":"Support Care Cancer","authors":["Zecha JA","Raber-Durlacher JE","Nair RG","et al."],"date":"2016-03-17","year":2016,"doi":"10.1007/s00520-016-3153-y","pmcid":"PMC4846551","cited_by":154,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"nm":[633,685,780,830],"em":["pulse"],"l1":"PBM may have a role in supportive care for a broad range of complications associated with the treatment of HNC with CRT. The suggested PBM irradiation and dosimetric parameters, which are potentially effective for these complications, are…","kw":"Chemotherapy Head and neck cancer LLLT Low-level laser therapy Low-level light therapy Mucositis Chemoradiotherapy Clinical Protocols Drug-Related Side Effects "},{"pmid":"26984240","title":"Low level laser therapy/photobiomodulation in the management of side effects of chemoradiation therapy in head and neck cancer: part 1: mechanisms of action, dosimetric, and safety considerations.","journal_abbr":"Support Care Cancer","authors":["Zecha JA","Raber-Durlacher JE","Nair RG","et al."],"date":"2016-03-16","year":2016,"doi":"10.1007/s00520-016-3152-z","pmcid":"PMC4846477","cited_by":158,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Based on its therapeutic effects, PBM may have utility in a broad range of oral, oropharyngeal, facial, and neck complications of HNC treatment. Although evidence suggests that PBM using LLLT is safe in HNC patients, more research is…","kw":"Chemotherapy Head and neck cancer LLLT and PBM Low level laser therapy Low level light therapy Mucositis Chemoradiotherapy Drug-Related Side Effects and Adverse"},{"pmid":"26714983","title":"Anti-inflammatory and lymphangiogenetic effects of low-level laser therapy on lymphedema in an experimental mouse tail model.","journal_abbr":"Lasers Med Sci","authors":["Jang DH","Song DH","Chang EJ","et al."],"date":"2015-12-29","year":2015,"doi":"10.1007/s10103-015-1854-y","cited_by":27,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["lymphœdème"],"pre":"vivo","l1":"qPCR showed that expressions of VEGFR3 were (p = 0.002) increased in the laser group. These results suggest that LLLT has anti-inflammatory and lymphangiogenetic effects for the management of lymphedema.","kw":"Low-level laser therapy Lymphangiogenesis Lymphedema Vascular endothelial growth factor C Animals Disease Models, Animal Female Gene Expression Regulation Infla"},{"pmid":"26355716","title":"In vitro study on the safety of near infrared laser therapy in its potential application as postmastectomy lymphedema treatment.","journal_abbr":"J Photochem Photobiol B","authors":["Cialdai F","Landini I","Capaccioli S","et al."],"date":"2015-08-11","year":2015,"doi":"10.1016/j.jphotobiol.2015.08.003","cited_by":15,"curated":false,"type":"preclinical","level":5,"ctx":["lymphœdème"],"nm":[808,905],"pre":"vitro","l1":"The results showed that, limited to the laser source, treatment conditions and experimental models used, laser radiation did not significantly affect the behavior of human breast adenocarcinoma cells, including their clonogenic…","kw":"Breast cancer cells NIR laser Postmastectomy lymphedema Apoptosis Breast Cancer Lymphedema Breast Neoplasms Cell Line, Tumor Cell Proliferation Cell Survival"},{"pmid":"26180372","title":"Complex decongestive physical therapy and low-level laser therapy for the treatment of pediatric congenital lymphedema: a case report.","journal_abbr":"J Phys Ther Sci","authors":["Hwang WT","Chung SH","Lee JS"],"date":"2015-06-30","year":2015,"doi":"10.1589/jpts.27.2021","pmcid":"PMC4500035","license":"cc by-nc-nd","oa":true,"cited_by":9,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"The moisture content of the left upper limb decreased 70 mL (6.66%), while moisture ratio increased by 0.007%. [Conclusion] Complex decongestive physical therapy and low-level laser therapy are effective for reducing lymphedema in…","kw":"Complex decongestive physical therapy Low-level laser therapy Lymphedema"},{"pmid":"25772311","title":"Prevention and management of lymphedema after breast cancer treatment.","journal_abbr":"Breast J","authors":["Merchant SJ","Chen SL"],"date":"2015-03-13","year":2015,"doi":"10.1111/tbj.12391","cited_by":38,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"Lymphedema of the arm after breast cancer treatment continues to challenge clinicians worldwide. In this review, we examine the main modalities, both nonsurgical and surgical, to prevent and treat this as yet incurable condition.","kw":"breast cancer lymphedema prevention treatment Arm Axilla Breast Neoplasms Compression Bandages Female Humans"},{"pmid":"25432632","title_fr":"Laser basse énergie, douleur et volume dans le lymphœdème lié au cancer du sein : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Preuves de force modérée : le laser réduit le volume du bras et la douleur, avec un gain de volume supérieur aux traitements sans laser.","l2":"Revue systématique avec méta-analyse (J Cancer Surviv, 2014).","l3":{"points":["Réduction de volume cliniquement pertinente."],"limites":["Effet sur la douleur non significatif entre groupes."],"pratique":"Option de la prise en charge décongestive."},"em":[],"pre":"","topic":"oncologie-support","title":"Effect of low-level laser therapy on pain and swelling in women with breast cancer-related lymphedema: a systematic review and meta-analysis.","journal":"Journal of cancer survivorship : research and practice","journal_abbr":"J Cancer Surviv","authors":["Smoot B","Chiavola-Larson L","Lee J","et al."],"date":"2014-11-29","year":2014,"week":"2014-S48","doi":"10.1007/s11764-014-0411-1","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":70,"pub_types":["Meta-Analysis","Research Support, N.I.H., Extramural","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"This study aims to examine literature on effectiveness of low-level laser therapy (LLLT) in reducing limb volume and pain in adults with breast cancer-related lymphedema (BCRL)."},{"label":"METHODS","text":"PubMed, PEDro, CINAHL, and Cochrane databases were searched using (lymphedema OR edema OR swelling) AND (breast cancer OR mastectomy) AND (laser OR low-level laser therapy OR LLLT OR cold laser). Intervention studies or meta-analyses reporting LLLT for BCRL were included in the search. Pooled effect sizes (ES) and 95 % confidence intervals (CI) were calculated for volume and pain. No limitations were placed on length of follow-up, publication year, or language. Final search was conducted on October 16, 2014."},{"label":"RESULTS","text":"Nine studies met criteria for inclusion. Within-group pooled ES for volume (six studies) was -0.52 (-0.78, -0.25), representing a 75.7-ml reduction in limb volume after LLLT. Between-group pooled ES for volume (four studies) was -0.62 (-0.97, -0.28), representing a 90.9-ml greater reduction in volume with treatment including LLLT versus not including LLLT. Within-group pooled ES for pain reduction (three studies) was -0.62 (-1.06, -0.19), pain reduction of 13.5 mm (0-100 mm VAS). Between-group pooled ES for pain reduction (two studies) was non-significant at -1.21 (-4.51, 2.10)."},{"label":"CONCLUSION","text":"Moderate-strength evidence supports LLLT in the management of BCRL, with clinically relevant within-group reductions in volume and pain immediately after conclusion of LLLT treatments. Greater reductions in volume were found with the use of LLLT than in treatments without it."},{"label":"IMPLICATIONS FOR CANCER SURVIVORS","text":"LLLT confers clinically meaningful reductions in arm volume and pain in women with BCRL."}],"keywords":[]},{"pmid":"25302460","title":"Effect of low-level laser therapy on radiotherapy-induced hyposalivation and xerostomia: a pilot study.","journal_abbr":"Photomed Laser Surg","authors":["Saleh J","Figueiredo MA","Cherubini K","et al."],"date":"2014-10-11","year":2014,"doi":"10.1089/pho.2014.3741","cited_by":44,"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[830],"l1":"With the parameters used, LLLT was not able to increase SFR or decrease xerostomia. The results may be associated with the late effects of radiotherapy on glandular structure, such as fibrosis and acinar atrophy.","kw":"Adult Aged Female Head and Neck Neoplasms Humans Low-Level Light Therapy"},{"pmid":"24820476","title_fr":"Laser-acupuncture et débit salivaire dans le syndrome de Gougerot-Sjögren","type":"rct","level":2,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser-acupuncture"],"nm":[650],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"Dans le syndrome de Sjögren, la laser-acupuncture augmente le débit salivaire (étude préliminaire).","l2":"Étude préliminaire contrôlée.","l3":{"points":["Xérostomie hors cancer."],"limites":["Petit effectif."],"pratique":"À confirmer."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Effect of laser acupuncture on salivary flow rate in patients with Sjögren's syndrome.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Cafaro A","Arduino PG","Gambino A","et al."],"date":"2014-05-13","year":2014,"week":"2014-S20","doi":"10.1007/s10103-014-1590-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":17,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Sjögren's syndrome (SS) is a multisystem autoimmune disease characterized by hypofunction of the salivary and lacrimal glands, frequently relieved with symptomatic treatments, such as saliva substitutes, eye lubricants, and cholinergic stimulators. The aim of this pilot randomized placebo-controlled study was to estimate the effects of laser acupuncture on salivary flow rates in patients with severe hyposalivation due to SS. A prospective cohort of 26 female patients affected by SS has been evaluated. The laser therapy equipment used was the Pointer Pulse, emitting light in the red visible spectrum (650 nm), with a power of 5 mW and an irradiation time of 120 s per acupoint, in an area of 3.14 mm(2) (fluence = 19.2 J/cm(2), power density = 0.16 W/cm(2), total dose = 0.6 J). The following acupuncture points were stimulated bilaterally: LI 2 Erjian, ST 5 Daying, ST 6 Jiache, ST 7 Xiaguan, SI 19 Tinggong, and BL 13 Feishu. True laser acupuncture led to a significantly higher amount of saliva production, measured after the end of the protocol (5 weeks), and during the 6-month follow-up period. The results are stable from the end of the protocol until the 3rd month of follow-up; during the last control, a slight but significant decrease in production has also been shown. This preliminary study proposes laser acupuncture as a possible treatment for improving salivary flow rates in patients with SS, but further validation on a larger sample is still necessary."}],"keywords":[]},{"pmid":"24461647","title":"[Low level laser therapy in inflammatory and infectious oral diseases].","journal_abbr":"Rev Stomatol Chir Maxillofac Chir Orale","authors":["André CV","Bosc R","Chader H","et al."],"date":"2014-01-21","year":2014,"doi":"10.1016/j.revsto.2013.12.009","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"All the selected studies were assessed with a Sackett's score of IV. No study presented the required quality standards to recommend the treatment of LLLT for the selected indications.","kw":"Infection orale Inflammation orale Laser basse puissance Low Level Laser Therapy Oral infection Oral inflammation Humans Infections Low-Level Light Therapy Mout"},{"pmid":"24384541","title":"Effect of laser acupuncture and auricular acupressure in a child with trismus as a sequela of medulloblastoma.","journal_abbr":"Acupunct Med","authors":["Ferreira DC","De Rossi A","Torres CP","et al."],"date":"2014-01-02","year":2014,"doi":"10.1136/acupmed-2013-010484","cited_by":11,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["trismus"],"l1":"The patient's family also noted reduced anxiety and hyperactivity. These results suggest that laser acupuncture and auricular acupressure for trismus and facial paralysis following cancer treatment is worth further investigation.","kw":"Acupressure Acupuncture Points Acupuncture Therapy Child, Preschool Combined Modality Therapy Humans"},{"pmid":"24424395","title":"Protein conformational modulation by photons: a mechanism for laser treatment effects.","journal_abbr":"Med Hypotheses","authors":["Liebert AD","Bicknell BT","Adams RD"],"date":"2013-12-26","year":2013,"doi":"10.1016/j.mehy.2013.12.009","license":"cc by-nc-sa","cited_by":36,"curated":false,"type":"autre","level":0,"ctx":[],"nm":[450,910],"l1":"Under the hypothesis, these observed biological effects would play a part in the bystander effect, the abscopal effect, and other systemic effects observed with the application of low level laser (LLLT). The implications of the hypothesis…","kw":"Lasers Photons Protein Conformation Proteins"},{"pmid":"24347912","title":"High-level Evidence Exists for Low-level Laser Therapy on Chemoradiotherapy-induced Oral Mucositis in Cancer Survivors.","journal_abbr":"Indian J Palliat Care","authors":["Kumar SP","Prasad K","Shenoy K","et al."],"date":"2013-12-19","year":2013,"doi":"10.4103/0973-1075.121542","pmcid":"PMC3853400","license":"cc by-nc-sa","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"","kw":""},{"pmid":"24292198","title":"Comments on \"Comparison of the influence of ozone and laser therapies on pain, swelling, and trismus following impacted third-molar surgery\".","journal_abbr":"Lasers Med Sci","authors":["He W","Yu F","Duan P"],"date":"2013-11-30","year":2013,"doi":"10.1007/s10103-013-1476-1","cited_by":1,"pub_types":["Letter","Comment"],"curated":false,"type":"letter","level":0,"ctx":["trismus"],"l1":"","kw":"Edema Female Humans Low-Level Light Therapy Male Molar, Third"},{"pmid":"23949015","title":"LED and laser photobiomodulation in the prevention and treatment of oral mucositis: experimental study in hamsters.","journal_abbr":"Clin Oral Investig","authors":["Freire Mdo R","Freitas R","Colombo F","et al."],"date":"2013-08-15","year":2013,"doi":"10.1007/s00784-013-1058-4","cited_by":13,"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[660,670],"pre":"both","l1":"The best results were obtained from the preventive laser and LED photobiomodulation groups; both treatments were effective in diminishing the OM lesions.","kw":"Animals Cricetinae Female Laser Therapy Male Mesocricetus"},{"pmid":"23803270","title_fr":"Laser basse énergie comme alternative au drainage lymphatique manuel : essai pilote","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":46,"effect":"mitigé","theme":"Lymphœdème","l1":"Le laser associé au bandage pourrait remplacer le drainage manuel pour gagner du temps, mais le bandage seul explique peut-être la baisse de volume.","l2":"Essai pilote randomisé à 3 bras, 46 patientes.","l3":{"points":["Amélioration cutanée sous laser."],"limites":["Effet propre du laser non isolé."],"pratique":"Option pour gagner du temps."},"em":[],"pre":"","topic":"oncologie-support","title":"A pilot randomized trial evaluating low-level laser therapy as an alternative treatment to manual lymphatic drainage for breast cancer-related lymphedema.","journal":"Oncology nursing forum","journal_abbr":"Oncol Nurs Forum","authors":["Ridner SH","Poage-Hooper E","Kanar C","et al."],"date":"2013-06-28","year":2013,"week":"2013-S26","doi":"10.1188/13.ONF.383-393","pmcid":"PMC3887507","license":null,"oa":false,"pdf":null,"cited_by":44,"pub_types":["Randomized Controlled Trial","Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE/OBJECTIVES","text":"To examine the impact of advanced practice nurse (APN)-administered low-level laser therapy (LLLT) as both a stand-alone and complementary treatment for arm volume, symptoms, and quality of life (QOL) in women with breast cancer-related lymphedema."},{"label":"DESIGN","text":"A three-group, pilot, randomized clinical trial."},{"label":"SETTING","text":"A private rehabilitation practice in the southeastern United States."},{"label":"SAMPLE","text":"46 breast cancer survivors with treatment-related lymphedema."},{"label":"METHODS","text":"Patients were screened for eligibility and then randomized to either manual lymphatic drainage (MLD) for 40 minutes, LLLT for 20 minutes, or 20 minutes of MLD followed by 20 minutes of LLLT. Compression bandaging was applied after each treatment. Data were collected pretreatment, daily, weekly, and at the end of treatment."},{"label":"MAIN RESEARCH VARIABLES","text":"Independent variables consisted of three types of APN-administered lymphedema treatment. Outcome variables included limb volume, extracellular fluid, psychological and physical symptoms, and QOL."},{"label":"FINDINGS","text":"No statistically significant between-group differences were found in volume reduction; however, all groups had clinically and statistically significant reduction in volume. No group differences were noted in psychological and physical symptoms or QOL; however, treatment-related improvements were noted in symptom burden within all groups. Skin improvement was noted in each group that received LLLT."},{"label":"CONCLUSIONS","text":"LLLT with bandaging may offer a time-saving therapeutic option to conventional MLD. Alternatively, compression bandaging alone could account for the demonstrated volume reduction."},{"label":"IMPLICATIONS FOR NURSING","text":"APNs can effectively treat lymphedema. APNs in private healthcare practices can serve as valuable research collaborators."},{"label":"KNOWLEDGE TRANSLATION","text":"Lasers may provide effective, less burdensome treatment for lymphedema. APNs with lymphedema certification can effectively treat this patient population with the use of LLLT. In addition, bioelectrical impedance and tape measurements can be used to assess lymphedema."}],"keywords":[]},{"pmid":"23192573","title_fr":"Laser basse énergie dans le lymphœdème secondaire au cancer du sein : revue systématique","type":"ma","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Le laser est prometteur dans le lymphœdème après cancer du sein, mais aucune étude n'a évalué le risque de récidive ou de métastase.","l2":"Revue systématique.","l3":{"points":["Question de la sécurité oncologique."],"limites":["Données de sécurité absentes en 2012."],"pratique":"Voir les revues de sécurité ultérieures (2019)."},"em":[],"pre":"","topic":"oncologie-support","title":"Low-level laser therapy in secondary lymphedema after breast cancer: systematic review.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["E Lima MT","E Lima JG","de Andrade MF","et al."],"date":"2012-11-29","year":2012,"week":"2012-S48","doi":"10.1007/s10103-012-1240-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":37,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Complex physical therapy is the main treatment for the secondary lymphedema after breast cancer. The low-level laser therapy (LLLT) has been used in order to stimulate lymphangiogenesis, encourage lymphatic motility, and reduce lymphostatic fibrosis. However, these factors could also favor the development of recurrence and metastasis. The objective of this study is to discuss the use of LLLT in the treatment of lymphedema after breast cancer. This study utilized a systematic review on the use of LLLT in the treatment of lymphedema after breast cancer. Evaluating quality of articles was conducted through the PEDro scale. Of the 41 articles identified, four were considered to be of high methodological quality (score ≥ 5). The low-level laser in the axillary region was performed in all studies. The control group was not similar across studies. The results presented showed that there was a reduction in limb volume in the group subjected to low-power laser when compared with other treatments. No studies have evaluated the risk of metastasis or relapse in the irradiated areas. Because no studies have included the complex physical therapy as the comparison group, we cannot claim that laser treatment is the best efficacy or effectiveness in lymphedema treatment after breast cancer. No studies have evaluated the hypothesis that the LLLT can increase the risk of recurrence or metastasis. Therefore, the questions about the safety of this procedure in cancer patients remain."}],"keywords":[]},{"pmid":"23008299","title":"Cancer-related lymphedema risk factors, diagnosis, treatment, and impact: a review.","journal_abbr":"J Clin Oncol","authors":["Paskett ED","Dean JA","Oliveri JM","et al."],"date":"2012-09-24","year":2012,"doi":"10.1200/JCO.2012.41.8574","cited_by":161,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"CONCLUSION Research into causes, prevention, and effect on QOL of LE and information on LE in cancers other than breast is needed. Consensus on definitions and measurement, increased patient and provider awareness of signs and symptoms,…","kw":"Exercise Humans Lymphedema Neoplasms Overweight Risk Factors"},{"pmid":"22875413","title_fr":"Laser basse énergie dans le lymphœdème après cancer du sein : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Lymphœdème","l1":"Preuves modérées à fortes d'efficacité du laser dans le lymphœdème lié au cancer du sein ; 1 à 2 J/cm² par point sur la zone fibreuse réduisent le volume.","l2":"Revue systématique de 7 bases, essais 1990–2011 (Support Care Cancer).","l3":{"points":["Dose recommandée : 1–2 J/cm² par point."],"limites":["Cinq petites études."],"pratique":"Repère de dose utile."},"em":[],"pre":"","topic":"oncologie-support","title":"A systematic review of the effect of low-level laser therapy in the management of breast cancer-related lymphedema.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Omar MT","Shaheen AA","Zafar H"],"date":"2012-08-09","year":2012,"week":"2012-S32","doi":"10.1007/s00520-012-1546-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":37,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"The purpose of this study was to review the effect of low-level laser therapy (LLLT) in the management of breast cancer-related lymphedema (BCRL)."},{"label":"METHODS","text":"A systematic review of seven databases for clinical trials for LLLT in the management of BCRL published between 1990 and 2011 was performed."},{"label":"RESULTS","text":"A total of eight studies on 230 patients were found. The methodological qualities of the selected studies were assessed with the Physiotherapy Evidence Database scale, and the studies were categorized according to Sackett's levels of evidence. Five studies were graded at evidence level II. Two studies were graded at evidence level III, and the remaining study was graded at evidence level V."},{"label":"CONCLUSIONS","text":"There is moderate to strong evidence for the effectiveness of LLLT for the management of BCRL from five small studies of acceptable methodological quality. A dose of 1-2 J/cm(2) per point applied to several points covering the fibrotic area can reduce limb volume following BCRL. Further well-designed, large-scale studies are required to determine more precisely how effective LLLT may be in BCRL."}],"keywords":[]},{"pmid":"22853435","title":"A preliminary study of the safety of red light phototherapy of tissues harboring cancer.","journal_abbr":"Photomed Laser Surg","authors":["Myakishev-Rempel M","Stadler I","Brondon P","et al."],"date":"2012-08-01","year":2012,"doi":"10.1089/pho.2011.3186","pmcid":"PMC3423866","cited_by":40,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't","Research Support, U.S. Gov't, Non-P.H.S."],"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[670],"pre":"vivo","l1":"This experiment suggests that LLLT at these parameters may be safe even when malignant lesions are present. Further studies on the effects of photoirradiation on neoplasms are warranted.","kw":"Animals Carcinoma, Squamous Cell Cell Proliferation Disease Models, Animal Equipment Design Low-Level Light Therapy"},{"pmid":"22730712","title_fr":"Laser basse énergie et xérostomie : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["xérostomie"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Xérostomie","l1":"Le laser peut améliorer le débit salivaire et régénérer l'épithélium des canaux salivaires ; il est sûr dans la xérostomie.","l2":"Revue systématique (PubMed seul).","l3":{"points":["Base mécanistique."],"limites":["Une seule base interrogée."],"pratique":"Paramètres à préciser."},"em":[],"pre":"","topic":"oncologie-support","title":"[The effects of low-level laser therapy on xerostomia (mouth dryness)].","journal":"Medicinski pregled","journal_abbr":"Med Pregl","authors":["Pavlić V"],"date":"2012-06-27","year":2012,"week":"2012-S26","doi":"10.2298/mpns1206247p","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"INTRODUCTION","text":"Xerostomia is a subjective complaint of mouth/oral dryness, caused by a reduction in normal salivary secretion due to different causes. Even though there are many available treatment modalities to enhance salivary flow, the therapy often remains unsatisfactory. The low-level laser therapy (low-level laser irradiation, photo-biomodulation) has been extensively used as a new, non-invasive approach and advantageous tool for reduction of xerostomia. Therefore, the aim of this study is to give a systematic overview on the effects of low-level laser therapy on xerostomia."},{"label":"MATERIAL AND METHODS","text":"A systematic review of published articles in PubMed database was carried out using keywords: \"low-level laser therapy\", \"xerostomia\", \"mouth dryness\"."},{"label":"RESULTS","text":"In all published articles, which were considered adequate for this overview, positive effects of low-level laser therapy were reported. Low-level laser therapy could significantly enhance salivary secretion and improve antimicrobial characteristics of secreted saliva (increased level of secretory immunoglobulin A; sIgA). Furthermore, low-level laser therapy could improve salivary flow and regeneration of salivary duct epithelial cells."},{"label":"CONCLUSION","text":"The current literature suggests that low-level laser therapy can be safely and effectively used as an advanced treatment modality for reduction of xerostomia. Further in vivo, in vitro and clinical studies using different irradiation parameters are suggested to determine the best laser parameters to be used."}],"keywords":[]},{"pmid":"22458118","title":"Changes in tissue water and indentation resistance of lymphedematous limbs accompanying low level laser therapy (LLLT) of fibrotic skin.","journal_abbr":"Lymphology","authors":["Mayrovitz HN","Davey S"],"date":"2012-03-31","year":2012,"cited_by":30,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème","trismus"],"l1":"On follow-up visit, 17 previously LLLT treated legs were sham treated with an inactive LLLT unit and measurements replicated. A TIR and TDC change-pattern similar to that obtained with the active LLLT was obtained, but sham-related…","kw":"Aged Aged, 80 and over Body Water Extremities Female Fibrosis"},{"pmid":"22091317","title":"Treatment of Lymphedema Praecox through Low Level Laser Therapy (LLLT).","journal_abbr":"J Res Med Sci","authors":["Mahram M","Rajabi M"],"date":"2011-11-18","year":2011,"pmcid":"PMC3214406","license":"cc by-nc-sa","oa":true,"cited_by":2,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["lymphœdème"],"l1":"The treatment was achieved to decrease the edema and no significant increase in circumference of involved leg was found following three months after the course of treatment. Although LLLT can be considered a beneficial treatment for…","kw":"LLLT Laser Low Level Laser Therapy Lymphedema Praecox Treatment"},{"pmid":"21054200","title":"The effect of low-level laser therapy on salivary glands in patients with xerostomia.","journal_abbr":"Photomed Laser Surg","authors":["Lončar B","Stipetić MM","Baričević M","et al."],"date":"2010-11-06","year":2010,"doi":"10.1089/pho.2010.2792","cited_by":47,"pub_types":["Comparative Study","Research Support, Non-U.S. Gov't"],"curated":false,"type":"nrct","level":3,"ctx":["xérostomie"],"nm":[904],"em":["pulse"],"l1":"The results of our study indicate that the effects of low-level laser therapy on salivary glands are not only stimulating, but also regenerative to a degree since the glandular response to the same amount of applied laser energy increased…","kw":"Adult Aged Case-Control Studies Female Follow-Up Studies Humans"},{"pmid":"20445997","title":"The short-term effects of low-level laser therapy in the management of breast-cancer-related lymphedema.","journal_abbr":"Support Care Cancer","authors":["Dirican A","Andacoglu O","Johnson R","et al."],"date":"2010-05-06","year":2010,"doi":"10.1007/s00520-010-0888-8","cited_by":28,"curated":false,"type":"autre","level":0,"ctx":["lymphœdème"],"l1":"Patients with BCRL received additional benefits from LLLT when used in conjunction with standard lymphedema treatment. These benefits include reduction in limb circumference, pain, increase in range of motion and scar mobility.…","kw":"Adult Arm Breast Neoplasms Cellulitis Cicatrix Combined Modality Therapy"},{"pmid":"20538293","title_fr":"Laser dans le lymphœdème après mastectomie : essai en double aveugle contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[904],"n":50,"effect":"favorable","theme":"Lymphœdème","l1":"Le laser réduit le volume du bras, augmente la mobilité de l'épaule et la force de préhension chez environ 93 % des patientes, mieux que le placebo à 8 et 12 semaines.","l2":"Essai randomisé en double aveugle contre placebo, 50 patientes.","l3":{"points":["Effet sur la fonction de l'épaule."],"limites":["Taux de réponse élevé, à confirmer."],"pratique":"Option efficace."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Treatment of post-mastectomy lymphedema with laser therapy: double blind placebo control randomized study.","journal":"The Journal of surgical research","journal_abbr":"J Surg Res","authors":["Ahmed Omar MT","Abd-El-Gayed Ebid A","El Morsy AM"],"date":"2010-04-18","year":2010,"week":"2010-S15","doi":"10.1016/j.jss.2010.03.050","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":40,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"In post-mastectomy patients, lymphedema has the potential to become a permanent progressive condition and become extremely resistant to treatment. Thus, it can results in function impairment and decrease quality of life. The aim of this study was to evaluate the effect of low level laser therapy (LLLT) on limb volume, shoulder mobility, and hand grip strength."},{"label":"MATERIAL AND METHODS","text":"Fifty women with breast cancer-related lymphedema were enrolled in a double-blind, placebo controlled trial. Patients were randomly assigned to active laser (n = 25) and placebo (n = 25) groups and received irradiation with Ga-As laser device that had wavelength of 904 nm, power of 5 mW, and spot size of 0.2 cm(2) over the axillary and arm areas, three times a week for 12 wk. The total energy applied at each point was 300 mjoules over seven points, giving a dosage of 1.5 joules/cm(2) in the active group. The placebo group received placebo therapy in which the laser had been disabled without affecting its apparent function. Limb circumference, shoulder mobility, and grip strength were measured before treatment and at 4, 8, and 12 wk."},{"label":"RESULTS","text":"The two groups had similar parameters at baseline. The reduction of limb volume tended to decline in both groups. The trend being more significantly pronounced in active LLLT group than placebo at 8 and 12 wk, respectively (P < 0.05). Goniometric data for shoulder mobility and hand grip strength were statistically significance for LLLT group than for placebo."},{"label":"CONCLUSION","text":"Laser treatment was found to be effective in reducing the limb volume, increase shoulder mobility, and hand grip strength in approximately 93% of patients with postmastectomy lymphedema."}],"keywords":[]},{"pmid":"20186057","title":"Supportive care in head and neck oncology.","journal_abbr":"Curr Opin Oncol","authors":["de Castro G","Guindalini RS"],"date":"2010-02-27","year":2010,"doi":"10.1097/CCO.0b013e32833818ff","cited_by":9,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"The best outcomes in head and neck squamous cell carcinoma patients treated in the multidisciplinary context can only be achieved with an adequate patient selection, an experienced and motivated team and if the best possible supportive…","kw":"Antineoplastic Agents Carcinoma, Squamous Cell Head and Neck Neoplasms Humans Mucositis Radiotherapy"},{"pmid":"19938253","title":"Laser as a therapy for dry mouth symptoms in a patient with Sjögren's syndrome: a case report.","journal_abbr":"Spec Care Dentist","authors":["Simões A","Platero MD","Campos L","et al."],"date":"2009-11-26","year":2009,"doi":"10.1111/j.1754-4505.2009.00078.x","cited_by":25,"pub_types":["Case Reports","Research Support, Non-U.S. Gov't"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"nm":[780],"l1":"After LPT, the parotid salivary gland pain and swelling were no longer present. Treatment with LPT was an effective method to improve the quality of life of this patient with SS.","kw":"Female Humans Lasers, Semiconductor Low-Level Light Therapy Middle Aged Pain Measurement"},{"pmid":"19938271","title":"The diagnosis and treatment of peripheral lymphedema.","journal_abbr":"Lymphology","authors":["Piller N","Carati C"],"date":"2009-11-26","year":2009,"cited_by":20,"pub_types":["Comment","Letter"],"curated":false,"type":"letter","level":0,"ctx":["lymphœdème"],"l1":"","kw":"Humans Low-Level Light Therapy Lymphedema Practice Guidelines as Topic Societies, Scientific"},{"pmid":"19878027","title_fr":"Laser basse énergie dans le lymphœdème après mastectomie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":21,"effect":"favorable","theme":"Lymphœdème","l1":"Douze séances de laser en 4 semaines réduisent le volume du bras et améliorent la souplesse des tissus et la fonction (DASH), avec un effet maintenu à 4 semaines.","l2":"Essai randomisé contre absence de laser, 21 patientes.","l3":{"points":["Amélioration fonctionnelle progressive."],"limites":["Petit effectif ; pas de placebo."],"pratique":"Option complémentaire."},"em":[],"pre":"","topic":"oncologie-support","title":"Managing postmastectomy lymphedema with low-level laser therapy.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Lau RW","Cheing GL"],"date":"2009-11-03","year":2009,"week":"2009-S45","doi":"10.1089/pho.2008.2330","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":40,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"We aimed to investigate the effects of low-level laser therapy (LLLT) in managing postmastectomy lymphedema."},{"label":"BACKGROUND DATA","text":"Postmastectomy lymphedema (PML) is a common complication of breast cancer treatment that causes various symptoms, functional impairment, or even psychosocial morbidity. A prospective, single-blinded, controlled clinical trial was conducted to examine the effectiveness of LLLT on managing PML."},{"label":"METHODS","text":"Twenty-one women suffering from unilateral PML were randomly allocated to receive either 12 sessions of LLLT in 4 wk (the laser group) or no laser irradiation (the control group). Volumetry and tonometry were used to monitor arm volume and tissue resistance; the Disabilities of Arm, Shoulder, and Hand (DASH) questionnaire was used for measuring subjective symptoms. Outcome measures were assessed before and after the treatment period and at the 4 wk follow-up."},{"label":"RESULTS","text":"Reduction in arm volume and increase in tissue softening was found in the laser group only. At the follow-up session, significant between-group differences (all p < 0.05) were found in arm volume and tissue resistance at the anterior torso and forearm region. The laser group had a 16% reduction in the arm volume at the end of the treatment period, that dropped to 28% in the follow-up. Moreover, the laser group demonstrated a cumulative increase from 15% to 33% in the tonometry readings over the forearm and anterior torso. The DASH score of the laser group showed progressive improvement over time."},{"label":"CONCLUSION","text":"LLLT was effective in the management of PML, and the effects were maintained to the 4 wk follow-up."}],"keywords":[]},{"pmid":"19814701","title":"Laser phototherapy as topical prophylaxis against radiation-induced xerostomia.","journal_abbr":"Photomed Laser Surg","authors":["Simões A","de Campos L","de Souza DN","et al."],"date":"2009-10-10","year":2009,"doi":"10.1089/pho.2009.2486","cited_by":39,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["xérostomie"],"nm":[660],"l1":"According to Wilcoxon and Student statistical test, xerostomia for G1 was lower than for G2 (p < 0.05), and salivary flow rate was no different before and after RT, except for stimulated collection of G2, which was lower (p < 0.05). Our…","kw":"Adolescent Adult Aged Carcinoma, Squamous Cell Female Head and Neck Neoplasms"},{"pmid":"19811082","title":"The effect of laser irradiation on proliferation of human breast carcinoma, melanoma, and immortalized mammary epithelial cells.","journal_abbr":"Photomed Laser Surg","authors":["Powell K","Low P","McDonnell PA","et al."],"date":"2009-10-09","year":2009,"doi":"10.1089/pho.2008.2445","cited_by":22,"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[904],"pre":"both","l1":"Before a definitive conclusion can be made regarding the safety of laser for breast cancer-related lymphoedema, further in vivo research is required.","kw":"Adenocarcinoma Analysis of Variance Breast Neoplasms Carcinoma, Ductal, Breast Cell Line Cell Line, Tumor"},{"pmid":"19164399","title_fr":"Compression pneumatique ou laser basse énergie dans le lymphœdème après mastectomie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":47,"effect":"favorable","theme":"Lymphœdème","l1":"Dans le lymphœdème après mastectomie, compression pneumatique et laser sont efficaces ; le laser donne de meilleurs résultats à long terme.","l2":"Essai randomisé, 47 patientes (Clin Rehabil).","l3":{"points":["Effet plus durable sous laser."],"limites":["Pas de placebo."],"pratique":"Alternative à la compression pneumatique."},"em":[],"pre":"","topic":"oncologie-support","title":"Efficacy of pneumatic compression and low-level laser therapy in the treatment of postmastectomy lymphoedema: a randomized controlled trial.","journal":"Clinical rehabilitation","journal_abbr":"Clin Rehabil","authors":["Kozanoglu E","Basaran S","Paydas S","et al."],"date":"2009-01-24","year":2009,"week":"2009-S04","doi":"10.1177/0269215508096173","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":48,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"To compare the long-term efficacy of pneumatic compression and low-level laser therapies in the management of postmastectomy lymphoedema."},{"label":"DESIGN","text":"Randomized controlled trial."},{"label":"SETTING","text":"Department of Physical Medicine and Rehabilitation of Cukurova University, Turkey."},{"label":"SUBJECTS","text":"Forty-seven patients with postmastectomy lymphoedema were enrolled in the study."},{"label":"INTERVENTIONS","text":"Patients were randomly allocated to pneumatic compression (group I, n=24) and low-level laser (group II, n=23) groups. Group I received 2 hours of compression therapy and group II received 20 minutes of laser therapy for four weeks. All patients were advised to perform daily limb exercises."},{"label":"MAIN MEASURES","text":"Demographic features, difference between sum of the circumferences of affected and unaffected limbs (delta C), pain with visual analogue scale and grip strength were recorded."},{"label":"RESULTS","text":"Mean age of the patients was 48.3 (10.4) years. Delta C decreased significantly at one, three and six months within both groups, and the decrease was still significant at month 12 only in group II (P = 0.004). Improvement of group II was greater than that of group I post treatment (P = 0.04) and at month 12 after 12 months (P = 0.02). Pain was significantly reduced in group I only at posttreatment evaluation, whereas in group II it was significant post treatment and at follow-up visits. No significant difference was detected in pain scores between the two groups. Grip strength was improved in both groups, but the differences between groups were not significant."},{"label":"CONCLUSIONS","text":"Patients in both groups improved after the interventions. Group II had better long-term results than group I. Low-level laser might be a useful modality in the treatment of postmastectomy lymphoedema."}],"keywords":[]},{"pmid":"19147865","title":"Lymphedema: a primer on the identification and management of a chronic condition in oncologic treatment.","journal_abbr":"CA Cancer J Clin","authors":["Lawenda BD","Mondry TE","Johnstone PA"],"date":"2009-01-17","year":2009,"doi":"10.3322/caac.20001","cited_by":239,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["lymphœdème"],"l1":"The authors also identify some of the resources available both to cancer patients with lymphedema and to the clinicians who treat them. It is hoped that this review will convey the importance of the early identification and management of…","kw":"Chronic Disease Humans Low-Level Light Therapy Lymph Node Excision Lymphedema Physical Therapy Modalities"},{"pmid":"18997921","title":"Eating disorders part II: clinical strategies for dental treatment.","journal_abbr":"J Contemp Dent Pract","authors":["Aranha AC","Eduardo Cde P","Cordás TA"],"date":"2008-11-01","year":2008,"cited_by":11,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["xérostomie"],"l1":"Oral complications of eating disorders are a major concern. The difficulties of recognizing the oral manifestations, and the failure to do so, may lead to serious systemic problems in addition to progressive and irreversible damage to the…","kw":"Dental Care for Chronically Ill Dental Caries Dental Restoration, Permanent Dentin Sensitivity Feeding and Eating Disorders Humans"},{"pmid":"18800946","title":"Improvement in quality of life of an oncological patient by laser phototherapy.","journal_abbr":"Photomed Laser Surg","authors":["Campos L","Simões A","Sá PH","et al."],"date":"2008-09-20","year":2008,"doi":"10.1089/pho.2008.2300","cited_by":42,"pub_types":["Case Reports","Research Support, Non-U.S. Gov't"],"curated":false,"type":"cases","level":4,"ctx":["xérostomie"],"nm":[660],"l1":"Normal oral function and consequent improvements in the quality of life of this oncologic patient were observed with LPT.","kw":"Adolescent Carcinoma, Mucoepidermoid Female Head and Neck Neoplasms Humans Low-Level Light Therapy"},{"pmid":"17018707","title_fr":"Thérapies conservatrices du lymphœdème du bras après cancer du sein : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Lymphœdème","l1":"Parmi les traitements conservateurs du lymphœdème du bras, le laser fait partie des options qui réduisent le volume, mais les essais restent trop petits.","l2":"Revue systématique (Ann Oncol, 2006).","l3":{"points":["Panorama des traitements physiques."],"limites":["Essais de faible effectif."],"pratique":"Option complémentaire."},"em":[],"pre":"","topic":"oncologie-support","title":"A systematic review of common conservative therapies for arm lymphoedema secondary to breast cancer treatment.","journal":"Annals of oncology : official journal of the European Society for Medical Oncology","journal_abbr":"Ann Oncol","authors":["Moseley AL","Carati CJ","Piller NB"],"date":"2006-10-03","year":2006,"week":"2006-S40","doi":"10.1093/annonc/mdl182","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":149,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Secondary arm lymphoedema is a chronic and distressing condition which affects a significant number of women who undergo breast cancer treatment. A number of health professional and patient instigated conservative therapies have been developed to help with this condition, but their comparative benefits are not clearly known. This systematic review undertook a broad investigation of commonly instigated conservative therapies for secondary arm lymphoedema including; complex physical therapy, manual lymphatic drainage, pneumatic pumps, oral pharmaceuticals, low level laser therapy, compression bandaging and garments, limb exercises and limb elevation. It was found that the more intensive and health professional based therapies, such as complex physical therapy, manual lymphatic drainage, pneumatic pump and laser therapy generally yielded the greater volume reductions, whilst self instigated therapies such as compression garment wear, exercises and limb elevation yielded smaller reductions. All conservative therapies produced improvements in subjective arm symptoms and quality of life issues, where these were measured. Despite the identified benefits, there is still the need for large scale, high level clinical trials in this area."}],"keywords":[]},{"pmid":"16673054","title_fr":"Laser basse énergie dans le lymphœdème après mastectomie : petit essai contrôlé","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[890],"n":11,"effect":"favorable","theme":"Lymphœdème","l1":"Chez 11 femmes, le laser réduit le lymphœdème après mastectomie par rapport au placebo.","l2":"Essai contrôlé en double aveugle, 11 patientes.","l3":{"points":["Effet sur le volume."],"limites":["Très petit effectif."],"pratique":"Paramètres optimaux à définir."},"em":[],"pre":"","nm_auto":true,"topic":"oncologie-support","title":"Low-level laser therapy in management of postmastectomy lymphedema.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Kaviani A","Fateh M","Yousefi Nooraie R","et al."],"date":"2006-05-04","year":2006,"week":"2006-S18","doi":"10.1007/s10103-006-0380-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":49,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this paper was to study the effects of low-level laser therapy (LLLT) in the treatment of postmastectomy lymphedema. Eleven women with unilateral postmastectomy lymphedema were enrolled in a double-blind controlled trial. Patients were randomly assigned to laser and sham groups and received laser or placebo irradiation (Ga-As laser device with a wavelength of 890 nm and fluence of 1.5 J/cm2) over the arm and axillary areas. Changes in patients' limb circumference, pain score, range of motion, heaviness of the affected limb, and desire to continue the treatment were measured before the treatment and at follow-up sessions (weeks 3, 9, 12, 18, and 22) and were compared to pretreatment values. Results showed that of the 11 enrolled patients, eight completed the treatment sessions. Reduction in limb circumference was detected in both groups, although it was more pronounced in the laser group up to the end of 22nd week. Desire to continue treatment at each session and baseline score in the laser group was greater than in the sham group in all sessions. Pain reduction in the laser group was more than in the sham group except for the weeks 3 and 9. No substantial differences were seen in other two parameters between the two treatment groups. In conclusion, despite our encouraging results, further studies of the effects of LLLT in management of postmastectomy lymphedema should be undertaken to determine the optimal physiological and physical parameters to obtain the most effective clinical response."}],"keywords":[]},{"pmid":"12973834","title_fr":"Laser basse énergie dans le lymphœdème après mastectomie : essai en double aveugle contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["lymphœdème"],"aim":"traitement","mode":["laser"],"nm":[904],"n":61,"effect":"favorable","theme":"Lymphœdème","l1":"Dans le lymphœdème après mastectomie, deux cycles de laser axillaire réduisent le volume du bras, le liquide extracellulaire et la dureté des tissus chez environ un tiers des patientes à 3 mois.","l2":"Essai randomisé en double aveugle contre placebo (Cancer, 2003).","l3":{"points":["Un cycle ne suffit pas, deux cycles sont efficaces."],"limites":["Effet chez une minorité de patientes ; pas de gain d'amplitude."],"pratique":"Essai fondateur ; prévoir au moins deux cycles."},"em":[],"pre":"","topic":"oncologie-support","title":"Treatment of postmastectomy lymphedema with low-level laser therapy: a double blind, placebo-controlled trial.","journal":"Cancer","journal_abbr":"Cancer","authors":["Carati CJ","Anderson SN","Gannon BJ","et al."],"date":"2003-09-16","year":2003,"week":"2003-S38","doi":"10.1002/cncr.11641","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":95,"pub_types":["Clinical Trial","Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"The current study describes the results of a double blind, placebo-controlled, randomized, single crossover trial of the treatment of patients with postmastectomy lymphedema (PML) with low-level laser therapy (LLLT)."},{"label":"METHODS","text":"Participants received placebo or one cycle or two cycles of LLLT to the axillary region of their affected arm. They were monitored for reductions in affected limb volume, upper body extracellular tissue fluid distribution, dermal tonometry, and range of limb movement."},{"label":"RESULTS","text":"There was no significant improvement reported immediately after any of the treatments. However, the mean affected limb volume was found to be significantly reduced at 1 month or 3 months of follow-up after 2 cycles of active laser treatment. Approximately 31% of subjects had a clinically significant reduction in the volume of their PML-affected arm (> 200 mLs) approximately 2-3 months after 2 cycles of treatment. There was no significant effect of placebo treatment, or one cycle of laser treatment, on affected limb volume. The extracellular fluid index of the affected and unaffected arms and torso were reported to be significantly reduced at 3 months after 2 cycles of laser therapy, and there was significant softening of the tissues in the affected upper arm. Treatment did not appear to improve range of movement of the affected arm."},{"label":"CONCLUSIONS","text":"Two cycles of laser treatment were found to be effective in reducing the volume of the affected arm, extracellular fluid, and tissue hardness in approximately 33% of patients with postmastectomy lymphedema at 3 months after treatment."}],"keywords":[]}];
